import{d as ua,C as m,o as pa,c as ya,j as n,a as e,E as t,k as i,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const xa=JSON.parse('{"title":"庄子·让王","description":"从辞让天下、太王迁岐、王子搜避位与子华子辨轻重入手，理解权位、土地与生命之间的关系。","frontmatter":{"title":"庄子·让王","description":"从辞让天下、太王迁岐、王子搜避位与子华子辨轻重入手，理解权位、土地与生命之间的关系。","category":"庄子","aliases":["让王","庄子让王"],"source":["用户提供的《庄子·让王》原文及相关注解"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-28.md","filePath":"daoism/zhuang-zi/chapter-28.md","lastUpdated":1792641266000}'),ma={name:"daoism/zhuang-zi/chapter-28.md"},qa=ua({...ma,setup(wa){const d=[{id:"rangwang-rang",term:"让",pinyin:"ràng",meaning:"辞让、让与；此处指把天下交给他人。"},{id:"rangwang-tianxia",term:"天下",pinyin:"tiān xià",meaning:"此处主要指统治天下的权位与事务。另：不是把天地万物当作个人财产。"},{id:"rangwang-xuyou",term:"许由",pinyin:"xǔ yóu",meaning:"传说中的隐者，在《庄子》多篇中出现。另：本段只写“不受”，没有展开他的完整理由。"},{id:"rangwang-zizhou",term:"子州支父·子州之父·子州之伯",pinyin:"称名待辨；父在人名中通常读 fǔ",meaning:"所供文本中的人物称名，应作为完整称名理解。另：保留原文写法；常见文本另有“子州支伯”等写法。不将“之父”直接解释为“他的父亲”，也不擅自统一称名。"},{id:"rangwang-youzhike",term:"犹之可也",pinyin:"yóu zhī kě yě",meaning:"还可以、尚可。另：回答并未首先以能力不足或君位不义为由拒绝。"},{id:"rangwang-suiran",term:"虽然",pinyin:"suī rán",meaning:"即使如此、话虽如此。另：不完全等同现代让步连词的用法。"},{id:"rangwang-shi",term:"适",pinyin:"shì",meaning:"恰好、正好。"},{id:"rangwang-youyou",term:"幽忧之病",pinyin:"yōu yōu zhī bìng",meaning:"幽深忧患、忧郁一类病苦。另：不直接对应某种现代医学诊断，也不因它是拒绝理由便断定是假托。"},{id:"rangwang-fangqiezhi",term:"方且治之",pinyin:"fāng qiě zhì zhī",meaning:"正准备、正在着手治疗它。"},{id:"rangwang-weixia",term:"未暇",pinyin:"wèi xiá",meaning:"没有闲暇、尚无余力。"},{id:"rangwang-zhizhong",term:"至重",pinyin:"zhì zhòng",meaning:"极为贵重、重要。"},{id:"rangwang-wuyitianxia",term:"无以天下为",pinyin:"wú yǐ tiān xià wéi",meaning:"不以天下为所求，不把取得天下作为自身目标。另：不是以“不想要”的姿态表演来争取权位。"},{id:"rangwang-tuotianxia",term:"托天下",pinyin:"tuō tiān xià",meaning:"将治理天下的事务托付给他。另：本段突出不争求的价值，不是在提供完整的统治者选任程序。"},{id:"rangwang-daqi",term:"大器",pinyin:"dà qì",meaning:"重大的权位与事务。另：不是普通的大型器具。"},{id:"rangwang-yisheng",term:"易生",pinyin:"yì shēng",meaning:"以生命交换天下，或因天下而损害生命。"},{id:"rangwang-yipimao",term:"衣皮毛",pinyin:"yì pí máo",meaning:"穿皮毛衣物；衣在此用作动词。"},{id:"rangwang-gechi",term:"葛絺",pinyin:"gé chī",meaning:"葛布衣物；絺为细葛布。"},{id:"rangwang-shoulian",term:"收敛",pinyin:"shōu liǎn",meaning:"收获、收聚作物。另：不是收敛情绪。"},{id:"rangwang-xiushi",term:"休食",pinyin:"xiū shí",meaning:"休息、饮食。"},{id:"rangwang-zide",term:"心意自得",pinyin:"xīn yì zì dé",meaning:"内心自在满足。另：联系善卷的回答，表现为不依赖外在权位来补足自身生活。"},{id:"rangwang-quanquan",term:"捲捲",pinyin:"quán quán",meaning:"通常联系勤勤、劳心用力的样子理解。另：不按现代“卷起来”解释，具体训释仍有差异。"},{id:"rangwang-hou",term:"后",pinyin:"hòu",meaning:"君主，此处称舜。"},{id:"rangwang-baoli",term:"葆力之士",pinyin:"相关训释待辨",meaning:"常联系恃力、用力经营者理解。另：不径释为保养体力；应结合“以舜之德为未至也”把握批评方向。"},{id:"rangwang-fufu-qidai",term:"夫负妻戴",pinyin:"fū fù qī dài",meaning:"丈夫背负物品，妻子顶戴物品。"},{id:"rangwang-ruhai",term:"入于海",pinyin:"rù yú hǎi",meaning:"通常联系远入海滨、海上隐居理解。另：不能仅凭此句认定投海自尽。"},{id:"rangwang-fan",term:"反",pinyin:"fǎn",meaning:"通“返”，返回。"},{id:"rangwang-taiwang",term:"大王",pinyin:"tài wáng",meaning:"即太王，周人先祖；大在此通常按“太”读。"},{id:"rangwang-danfu",term:"亶父·囗父",pinyin:"dǎn fǔ；囗为缺字",meaning:"人名，通常称古公亶父。另：“大王囗父”中的“囗”是所供文本的缺字，结合前文“亶父”理解；原文保留，不默改。"},{id:"rangwang-bin",term:"豳",pinyin:"bīn",meaning:"古地名，太王原居之地。"},{id:"rangwang-diren",term:"狄人",pinyin:"dí rén",meaning:"古代族群称谓，此处为攻豳的一方。"},{id:"rangwang-shizhiyi",term:"事之以……",pinyin:"shì zhī yǐ",meaning:"用某物奉事、馈赠对方，试图满足其要求。"},{id:"rangwang-pibo",term:"皮帛",pinyin:"pí bó",meaning:"兽皮与丝织品。"},{id:"rangwang-yuren",term:"与人之兄居而杀其弟",pinyin:"按句义理解",meaning:"与人之兄共同生活，却因争战使其弟被杀。另：结合上下文理解，不必认作太王亲手杀人；下一句以父子关系作相应说明。"},{id:"rangwang-mianju",term:"子皆勉居矣",pinyin:"zǐ jiē miǎn jū yǐ",meaning:"你们努力安居吧；子在此称众人。"},{id:"rangwang-xiyiyi",term:"奚以异",pinyin:"xī yǐ yì",meaning:"有什么不同。"},{id:"rangwang-suoyongyang",term:"所用养",pinyin:"suǒ yòng yǎng",meaning:"用来供养生命的东西，此处首先涉及土地。"},{id:"rangwang-suoyang",term:"所养",pinyin:"suǒ yǎng",meaning:"所要供养、保全的生命，此处也包括民众。"},{id:"rangwang-zhangshengce",term:"杖生䇲",pinyin:"字形及训释待辨",meaning:"常联系拄着未经精细加工的木杖、枝条离去理解。另：保留所供字形，不将此处理解为筮占动作。"},{id:"rangwang-xianglian",term:"相连而从",pinyin:"xiāng lián ér cóng",meaning:"接连跟随。"},{id:"rangwang-zunsheng",term:"尊生",pinyin:"zūn shēng",meaning:"看重生命，不使生命轻易成为外物的代价。另：太王故事中的尊生也涉及民众，不只涉及统治者自身。"},{id:"rangwang-yiyangshangshen",term:"以养伤身",pinyin:"yǐ yǎng shāng shēn",meaning:"因供养之物或享用它们的方式，反而伤害身体。"},{id:"rangwang-yilileixing",term:"以利累形",pinyin:"yǐ lì lèi xíng",meaning:"为追求利益而使身体受累、受损。"},{id:"rangwang-zhongshizhi",term:"重失之",pinyin:"zhòng shī zhī",meaning:"把失去高官尊爵看得极重，难以放下。"},{id:"rangwang-qingwang",term:"轻亡其身",pinyin:"qīng wáng qí shēn",meaning:"轻忽自身死亡、毁伤的危险。"},{id:"rangwang-sanshishi",term:"三世弑其君",pinyin:"sān shì shì qí jūn",meaning:"接连三代发生杀害君主的事。另：弑为臣下杀君等关系中的特定称谓。"},{id:"rangwang-wangzisou",term:"王子搜",pinyin:"wáng zǐ sōu",meaning:"故事中的越国王子。"},{id:"rangwang-huanzhi",term:"患之",pinyin:"huàn zhī",meaning:"为此忧惧，将其视作危险。"},{id:"rangwang-danxue",term:"丹穴",pinyin:"dān xué",meaning:"名称或隐居处。另：具体地望不宜强定。"},{id:"rangwang-congzhidanxue",term:"从之丹穴",pinyin:"按句义理解",meaning:"追寻他到丹穴。另：句式简约，不机械按现代语序拆解。"},{id:"rangwang-xunyiai",term:"熏之以艾",pinyin:"xūn zhī yǐ ài",meaning:"用燃艾产生的烟逼他出来。"},{id:"rangwang-wangyu",term:"王舆",pinyin:"wáng yú",meaning:"君王所乘的车。"},{id:"rangwang-yuansui",term:"援绥",pinyin:"yuán suí",meaning:"拉住登车用的绳索；绥是登车之索。"},{id:"rangwang-shewo",term:"舍我",pinyin:"shě wǒ",meaning:"放过我，不再强求我。"},{id:"rangwang-wuweijun",term:"恶为君",pinyin:"wù wéi jūn",meaning:"厌恶做君主；恶在此读 wù。"},{id:"rangwang-weijunzhihuan",term:"为君之患",pinyin:"wéi jūn zhī huàn",meaning:"做君主所带来的忧患、危险。"},{id:"rangwang-xiangyu",term:"相与",pinyin:"xiāng yǔ",meaning:"互相、共同参与。"},{id:"rangwang-zhengqindi",term:"争侵地",pinyin:"zhēng qīn dì",meaning:"争夺被侵占或涉及侵占的土地。"},{id:"rangwang-zihuazi",term:"子华子",pinyin:"zǐ huá zǐ",meaning:"人物称名。另：不据此直接认定与后世同名著作的关系。"},{id:"rangwang-shuming",term:"书铭",pinyin:"shū míng",meaning:"写下、铭记文字；此处用于设定得到天下的条件。另：“天下书铭”等句较简约，宜着眼于假设情境的论证作用。"},{id:"rangwang-jue",term:"攫",pinyin:"jué",meaning:"抓取、攫取。"},{id:"rangwang-fei",term:"废",pinyin:"fèi",meaning:"损坏、失去作用；此处指手臂残废。"},{id:"rangwang-youtianxia",term:"有天下",pinyin:"yǒu tiān xià",meaning:"取得天下的统治权。"},{id:"rangwang-zishiguanzhi",term:"自是观之",pinyin:"zì shì guān zhī",meaning:"从这一选择来看。"},{id:"rangwang-choushenshangsheng",term:"愁身伤生",pinyin:"chóu shēn shāng shēng",meaning:"使自身陷于忧愁，损害生命。"},{id:"rangwang-youqi",term:"忧戚",pinyin:"yōu qī",meaning:"忧愁、悲苦。"},{id:"rangwang-bude",term:"不得",pinyin:"bù dé",meaning:"未能取得所争求的东西。"},{id:"rangwang-zhiqingzhong",term:"知轻重",pinyin:"zhī qīng zhòng",meaning:"能辨认所求与所付代价的相对分量。另：不是给所有复杂处境制定一张固定的价值数值表。"},{id:"rangwang-yanhe",term:"颜阖",pinyin:"yán hé",meaning:"人物名，在《庄子》中多次出现。"},{id:"rangwang-dedaozhiren",term:"得道之人",pinyin:"dé dào zhī rén",meaning:"被认为体道、有道的人。"},{id:"rangwang-bi",term:"币",pinyin:"bì",meaning:"礼物、聘礼，常涉及帛等。另：不限于现代货币。"},{id:"rangwang-loulv",term:"陋闾",pinyin:"lòu lǘ",meaning:"简陋的里巷、居处；闾本指里门，也可代指里巷。"},{id:"rangwang-jubu",term:"苴布",pinyin:"jū bù",meaning:"粗麻布。"},{id:"rangwang-fanniu",term:"饭牛",pinyin:"fàn niú",meaning:"喂牛；饭在此作动词。"},{id:"rangwang-ziduizhi",term:"自对之",pinyin:"zì duì zhī",meaning:"亲自出来应答使者。"},{id:"rangwang-yu-question",term:"与",pinyin:"yú",meaning:"句末疑问语气词。"},{id:"rangwang-zhibi",term:"致币",pinyin:"zhì bì",meaning:"送上礼物。"},{id:"rangwang-tingmiu",term:"听谬",pinyin:"tīng miù",meaning:"听错，传达或理解有误。"},{id:"rangwang-yishizhezui",term:"遗使者罪",pinyin:"yí shǐ zhě zuì",meaning:"给使者留下罪责，使使者可能因办错事获罪。另：这里的“遗”与赠粮之“遗”意义、读音不同。"},{id:"rangwang-shenzhi",term:"审之",pinyin:"shěn zhī",meaning:"核实这件事。"},{id:"rangwang-huan",term:"还",pinyin:"huán",meaning:"返回。另：“反”的返回义参见已有词条。"},{id:"rangwang-wufugui",term:"恶富贵",pinyin:"wù fù guì",meaning:"厌恶富贵；恶在此读 wù。另：是叙述者对颜阖的明确评价，不能作为所有辞受故事的统一理由。"},{id:"rangwang-daozhizhen",term:"道之真",pinyin:"dào zhī zhēn",meaning:"道的真粹、根本。另：此处强调其用于治身的首要地位。"},{id:"rangwang-zhishen",term:"治身",pinyin:"zhì shēn",meaning:"调养、安顿自身。另：不宜只按现代疾病治疗理解。"},{id:"rangwang-xuyu",term:"绪余",pinyin:"xù yú",meaning:"剩余、余绪，引申为根本之外的余用。"},{id:"rangwang-weiguojia",term:"为国家",pinyin:"wéi guó jiā",meaning:"治理国家。"},{id:"rangwang-tuju",term:"土苴",pinyin:"tǔ jū",meaning:"糟粕、粗末等余弃之物。另：语气比“绪余”更轻，具体字义训释有差异。"},{id:"rangwang-diwangzhigong",term:"帝王之功",pinyin:"dì wáng zhī gōng",meaning:"帝王治理、经营天下的功业。"},{id:"rangwang-yushi",term:"余事",pinyin:"yú shì",meaning:"根本之外的事务。另：不等于完全没有意义的事务。"},{id:"rangwang-wanshen",term:"完身",pinyin:"wán shēn",meaning:"保全自身，使自身不因外物而残损。"},{id:"rangwang-yangsheng",term:"养生",pinyin:"yǎng shēng",meaning:"养护生命。另：此处不能只缩成延寿技巧。"},{id:"rangwang-weishenqisheng",term:"危身弃生",pinyin:"wēi shēn qì shēng",meaning:"使自身陷于危险，轻弃生命。"},{id:"rangwang-xunwu",term:"殉物",pinyin:"xùn wù",meaning:"为外在事物牺牲、耗损自身。"},{id:"rangwang-suoyizhi",term:"所以之",pinyin:"suǒ yǐ zhī",meaning:"行动所趋向之处、所要达到的目标。另：宜与“所以为”及下文所用、所要的比较合看。"},{id:"rangwang-suoyiwei",term:"所以为",pinyin:"suǒ yǐ wéi",meaning:"行动的缘由、凭借或所用手段。另：具体解释存在差异，不强定为唯一现代术语。"},{id:"rangwang-suihouzhizhu",term:"随侯之珠",pinyin:"suí hóu zhī zhū",meaning:"传说中的珍贵宝珠。"},{id:"rangwang-tanque",term:"弹雀",pinyin:"tán què",meaning:"用弹丸击鸟；此处把宝珠当作弹丸。"},{id:"rangwang-qianren",term:"千仞",pinyin:"qiān rèn",meaning:"极高、极远的夸张表述；仞为古代长度单位。另：不必强换算成确定距离。"},{id:"rangwang-suoyong",term:"所用",pinyin:"suǒ yòng",meaning:"所使用、所付出的东西。"},{id:"rangwang-suoyao",term:"所要",pinyin:"suǒ yào",meaning:"所求取的东西；要在此是求取之义。"},{id:"rangwang-qite",term:"岂特",pinyin:"qǐ tè",meaning:"岂止、难道仅仅。"},{id:"rangwang-ziliezi",term:"子列子",pinyin:"zǐ liè zǐ",meaning:"对列子的尊称。"},{id:"rangwang-lieyukou",term:"列御寇",pinyin:"liè yù kòu",meaning:"列子之名。"},{id:"rangwang-qiong",term:"穷",pinyin:"qióng",meaning:"此处主要指贫困、生活困窘。"},{id:"rangwang-jise",term:"饥色",pinyin:"jī sè",meaning:"饥饿显露于面容。"},{id:"rangwang-zhengziyang",term:"郑子阳",pinyin:"zhèng zǐ yáng",meaning:"郑国执政人物。"},{id:"rangwang-wunai",term:"无乃……乎",pinyin:"wú nǎi",meaning:"恐怕……吧，带有反问、提醒意味。"},{id:"rangwang-haoshi",term:"好士",pinyin:"hào shì",meaning:"喜爱、礼遇士人。"},{id:"rangwang-weizhisu",term:"遗之粟",pinyin:"wèi zhī sù",meaning:"赠送粮食给他；遗在此读 wèi。"},{id:"rangwang-zaibai",term:"再拜",pinyin:"zài bài",meaning:"拜两次，表示敬意。"},{id:"rangwang-fuxin",term:"拊心",pinyin:"fǔ xīn",meaning:"拍胸、抚胸，表现忧愁或痛惜。"},{id:"rangwang-qizi",term:"妻子",pinyin:"qī zǐ",meaning:"妻子与子女、家属。另：不只指现代意义的配偶。"},{id:"rangwang-yile",term:"佚乐",pinyin:"yì lè",meaning:"安逸、快乐。"},{id:"rangwang-junguo",term:"君过",pinyin:"jūn guò",meaning:"君主过访、眷顾。另：此处通过遣使赠粮表现，不补成亲自到访。"},{id:"rangwang-qibumingye",term:"岂不命邪",pinyin:"qǐ bù mìng yé",meaning:"大意为“这难道不是命吗”，带有对困苦难解的感叹。另：联系妻子的言说处境理解，不据此建立完整的命运理论。"},{id:"rangwang-zizhiwo",term:"自知我",pinyin:"zì zhī wǒ",meaning:"自己真正了解我，不只是听别人评价。"},{id:"rangwang-zuiwo",term:"罪我",pinyin:"zuì wǒ",meaning:"加罪于我、认为我有罪。"},{id:"rangwang-qizu",term:"其卒",pinyin:"qí zú",meaning:"后来、最终。"},{id:"rangwang-zuonan",term:"作难",pinyin:"zuò nàn",meaning:"发动变乱、起事。"},{id:"rangwang-chuzhaowang",term:"楚昭王",pinyin:"chǔ zhāo wáng",meaning:"楚国君主。另：故事置于吴军入楚、昭王出奔而后返回的背景中。"},{id:"rangwang-tuyangyue",term:"屠羊说",pinyin:"tú yáng yuè",meaning:"屠羊者，名说；说在人名中通常读 yuè。"},{id:"rangwang-shiguo",term:"失国",pinyin:"shī guó",meaning:"失去国都与原有统治处境、出奔。另：不必径释为国家从此彻底灭亡。"},{id:"rangwang-zou",term:"走",pinyin:"zǒu",meaning:"逃跑、出奔。另：不是现代日常“走路”。"},{id:"rangwang-congyzhaowang",term:"从于昭王",pinyin:"cóng yú zhāo wáng",meaning:"跟随昭王出奔。另：具体动机由屠羊说后面的自述进一步说明。"},{id:"rangwang-fanguo",term:"反国",pinyin:"fǎn guó",meaning:"返回本国，恢复原有处境；反通“返”。"},{id:"rangwang-congzhe",term:"从者",pinyin:"cóng zhě",meaning:"跟随出奔的人。"},{id:"rangwang-dawang-chu",term:"大王",pinyin:"dà wáng",meaning:"对君王的尊称，此处称楚昭王。另：与太王迁岐故事中按“太王”理解的“大王”不同。"},{id:"rangwang-fantuyang",term:"反屠羊",pinyin:"fǎn tú yáng",meaning:"回到屠羊的原业。"},{id:"rangwang-juelu",term:"爵禄",pinyin:"jué lù",meaning:"爵位与俸禄。另：首次出现时，屠羊说借此称自己原有的营生；后文则指高位厚禄。"},{id:"rangwang-youheshang",term:"又何赏之有",pinyin:"yòu hé shǎng zhī yǒu",meaning:"还需要什么赏赐？。另：“何赏”为前置的宾语。"},{id:"rangwang-qiangzhi",term:"强之",pinyin:"qiǎng zhī",meaning:"坚持让他接受、强使其受赏。"},{id:"rangwang-fuqizhu",term:"伏其诛",pinyin:"fú qí zhū",meaning:"伏罪受罚。"},{id:"rangwang-dangqishang",term:"当其赏",pinyin:"dāng qí shǎng",meaning:"承当、接受这份赏赐。另：“当”也含是否配得之意。"},{id:"rangwang-jianzhi",term:"见之",pinyin:"jiàn zhī",meaning:"召见他，让他来见君主。"},{id:"rangwang-zhongshangdagong",term:"重赏大功",pinyin:"zhòng shǎng dà gōng",meaning:"受到重赏、建立大功一类资格。另：具体语法层次可有不同理解；不将故事中的陈述直接当作完整制度史。"},{id:"rangwang-zhi",term:"知",pinyin:"zhì",meaning:"通“智”，才智。"},{id:"rangwang-cunguo",term:"存国",pinyin:"cún guó",meaning:"保全国政、国家。"},{id:"rangwang-sikou",term:"死寇",pinyin:"sǐ kòu",meaning:"为抵御敌寇而死。"},{id:"rangwang-ying",term:"郢",pinyin:"yǐng",meaning:"楚国都城。"},{id:"rangwang-feigusui",term:"非故随大王",pinyin:"fēi gù suí dà wáng",meaning:"不是特意以追随君主为目的而出奔。"},{id:"rangwang-feifahuiyue",term:"废法毁约",pinyin:"fèi fǎ huǐ yuē",meaning:"废弃既有法度，破坏约定、规范。"},{id:"rangwang-wenyutianxia",term:"闻于天下",pinyin:"wén yú tiān xià",meaning:"为天下所知、传闻于天下。另：本段关注以什么事实、通过什么方式为天下所知，不能直接等同于完全忘名。"},{id:"rangwang-simaziqi",term:"司马子綦",pinyin:"sī mǎ zǐ qí",meaning:"故事中的楚国司马。另：不因称名相近就与其他篇章人物混同。"},{id:"rangwang-yanzhi",term:"延之",pinyin:"yán zhī",meaning:"延请、招请他。"},{id:"rangwang-sanjing",term:"三旌之位",pinyin:"sān jīng zhī wèi",meaning:"高贵的官位、等级。另：常联系卿位等解释，具体制度不强定为某一唯一官职。"},{id:"rangwang-wanzhong",term:"万锺之禄",pinyin:"wàn zhōng zhī lù",meaning:"极为丰厚的俸禄；锺为古代容量单位。另：此处不必精确换算。"},{id:"rangwang-si",term:"肆",pinyin:"sì",meaning:"店铺、经营场所。"},{id:"rangwang-wangshi",term:"妄施",pinyin:"wàng shī",meaning:"没有合宜根据地施予、赏赐。另：此处是屠羊说对受赏、受位的判断，不能据此断言所有特别延请都不当。"},{id:"rangwang-fufan",term:"复反",pinyin:"fù fǎn",meaning:"重新返回。"},{id:"rangwang-yuanxian",term:"原宪",pinyin:"yuán xiàn",meaning:"孔子弟子。"},{id:"rangwang-huandu",term:"环堵之室",pinyin:"huán dǔ zhī shì",meaning:"狭小简陋的居室。另：堵为墙及相关计量称谓，不必精确换算面积。"},{id:"rangwang-ci",term:"茨",pinyin:"cí",meaning:"用草覆盖屋顶。"},{id:"rangwang-shengcao",term:"生草",pinyin:"shēng cǎo",meaning:"此处为盖屋所用的草。另：不宜仅按现代“新鲜青草”理解。"},{id:"rangwang-penghu",term:"蓬户",pinyin:"péng hù",meaning:"用蓬草等编成的门。"},{id:"rangwang-buwan",term:"不完",pinyin:"bù wán",meaning:"不完整、破损。"},{id:"rangwang-shu",term:"枢",pinyin:"shū",meaning:"门轴。"},{id:"rangwang-wengyou",term:"瓮牖",pinyin:"wèng yǒu",meaning:"用破瓮口等作窗，表现居处简陋。"},{id:"rangwang-ershi",term:"二室",pinyin:"断句、训释待辨",meaning:"相关位置存在断句与解释疑难。另：不强定为现代建筑意义的“两间卧室”。"},{id:"rangwang-he",term:"褐",pinyin:"hè",meaning:"粗布、粗衣，此处用于遮塞。"},{id:"rangwang-kuangzuo",term:"匡坐",pinyin:"kuāng zuò",meaning:"端正地坐着；匡联系正理解。"},{id:"rangwang-xiange",term:"弦歌",pinyin:"xián gē",meaning:"弹奏弦乐并歌唱。"},{id:"rangwang-zhonggan",term:"中绀而表素",pinyin:"zhōng gàn ér biǎo sù",meaning:"通常联系衣着内外的颜色理解。另：绀为深青带赤之色，素为白色；具体衣饰形制不强定。"},{id:"rangwang-xuanche",term:"轩车",pinyin:"xuān chē",meaning:"高大的车。"},{id:"rangwang-huaguan",term:"华冠",pinyin:"华通常按通“桦”理解",meaning:"通常解释为桦树皮制成的帽子。另：不直接译为华丽的冠帽。"},{id:"rangwang-lvyi",term:"𫄳履",pinyin:"字形、音读待辨",meaning:"通常联系简陋、破旧的鞋履理解。另：保留所供字形，不强定音读。"},{id:"rangwang-zhangli",term:"杖藜",pinyin:"zhàng lí",meaning:"拄着藜杖；杖用作动词。"},{id:"rangwang-bing-yuanxian",term:"病",pinyin:"bìng",meaning:"子贡问话与原宪回答中的意义发生转折；后者明确指学而不能行的困病。另：“非病”不是身体检查结论。"},{id:"rangwang-qunxun",term:"逡巡",pinyin:"qūn xún",meaning:"迟疑、退却的样子。"},{id:"rangwang-xishi",term:"希世",pinyin:"xī shì",meaning:"迎合世俗、求合于世。"},{id:"rangwang-bizhou",term:"比周",pinyin:"bǐ zhōu",meaning:"结党、偏私地相互依附。"},{id:"rangwang-xueyiweiren",term:"学以为人",pinyin:"xué yǐ wéi rén",meaning:"此处通常指学习以求他人观感、显示于人。另：不是现代正面意义的“为他人服务”。"},{id:"rangwang-jiaoyiweiji",term:"教以为己",pinyin:"jiào yǐ wéi jǐ",meaning:"教人以谋取自己的利益、名声等。另：不据此认定一切教学报酬都不正当。"},{id:"rangwang-te",term:"慝",pinyin:"tè",meaning:"邪恶、隐蔽的不正。"},{id:"rangwang-yumazhishi",term:"舆马之饰",pinyin:"yú mǎ zhī shì",meaning:"车马等外在装饰、排场。"},{id:"rangwang-zengzi",term:"曾子",pinyin:"zēng zǐ",meaning:"曾参，孔子弟子。"},{id:"rangwang-yunpao",term:"緼袍",pinyin:"yùn páo",meaning:"用旧絮等填充的袍子。另：原文保留所供“緼（ｙｕｎ４）袍”的形式。"},{id:"rangwang-wubiao",term:"无表",pinyin:"wú biǎo",meaning:"没有完整的外层、面料。"},{id:"rangwang-yanse",term:"颜色",pinyin:"yán sè",meaning:"面容、气色。"},{id:"rangwang-zhongkuai",term:"肿哙",pinyin:"zhǒng kuài",meaning:"通常联系浮肿、不健康的面貌理解。"},{id:"rangwang-pianzhi",term:"胼胝",pinyin:"pián zhī",meaning:"手足因劳作、摩擦形成的厚皮、老茧。"},{id:"rangwang-bujuhuo",term:"不举火",pinyin:"bù jǔ huǒ",meaning:"没有生火做饭，表现食物缺乏。"},{id:"rangwang-zhiyi",term:"制衣",pinyin:"zhì yī",meaning:"制作衣服。"},{id:"rangwang-ying-band",term:"缨",pinyin:"yīng",meaning:"冠帽的系带。"},{id:"rangwang-zhuojin",term:"捉襟",pinyin:"zhuō jīn",meaning:"拉拢衣襟。"},{id:"rangwang-zhouxian",term:"肘见",pinyin:"zhǒu xiàn",meaning:"手肘露出；见通“现”。"},{id:"rangwang-naju",term:"纳屦",pinyin:"nà jù",meaning:"穿鞋、把脚放进鞋中。"},{id:"rangwang-zhongjue",term:"踵决",pinyin:"zhǒng jué",meaning:"鞋后跟处破裂，脚跟露出。"},{id:"rangwang-yezong",term:"曳纵",pinyin:"字形、训释待辨",meaning:"常联系拖着鞋履而行、歌唱理解。另：不按现代“纵情”直接拆解。"},{id:"rangwang-shangsong",term:"《商颂》",pinyin:"shāng sòng",meaning:"《诗经》中的诗篇类别。另：原文未标明具体篇目。"},{id:"rangwang-jinshi",term:"金石",pinyin:"jīn shí",meaning:"钟磬等乐器，此处比喻歌声铿锵。"},{id:"rangwang-budechen",term:"不得臣",pinyin:"bù dé chén",meaning:"不能使他成为臣属；臣用作动词。"},{id:"rangwang-budeyou",term:"不得友",pinyin:"bù dé yǒu",meaning:"不能使他进入所欲建立的朋友关系；友用作动词。另：不等于拒绝所有友谊。"},{id:"rangwang-yangzhi",term:"养志",pinyin:"yǎng zhì",meaning:"养护、持守志向。"},{id:"rangwang-yangxing",term:"养形",pinyin:"yǎng xíng",meaning:"养护身体。"},{id:"rangwang-zhidao",term:"致道",pinyin:"zhì dào",meaning:"达于道、使体道达到深处。"},{id:"rangwang-wangxin",term:"忘心",pinyin:"wàng xīn",meaning:"松开执着计较之心。另：不是失去意识或一切思考能力。"},{id:"rangwang-jiapinjubei",term:"家贫居卑",pinyin:"jiā pín jū bēi",meaning:"家境贫困，居处简陋或处境低下。"},{id:"rangwang-hubushihu",term:"胡不仕乎",pinyin:"hú bù shì hū",meaning:"为什么不出仕呢？"},{id:"rangwang-shi-office",term:"仕",pinyin:"shì",meaning:"做官、进入政治任职关系。"},{id:"rangwang-guoneiwai",term:"郭外·郭内",pinyin:"guō wài · guō nèi",meaning:"外城之外、之内的区域。另：不完全等同现代城市与农村分类。"},{id:"rangwang-zuyiji",term:"足以给",pinyin:"zú yǐ jǐ",meaning:"足够供给。"},{id:"rangwang-zhanzhou",term:"𫗞粥",pinyin:"字形待辨",meaning:"粥食，常联系饘粥一类稠粥理解。另：不强定为精确食谱。"},{id:"rangwang-sima",term:"丝麻",pinyin:"sī má",meaning:"丝与麻，涉及衣着所需。"},{id:"rangwang-guqin",term:"鼓琴",pinyin:"gǔ qín",meaning:"弹琴。"},{id:"rangwang-ziyuzile",term:"自娱·自乐",pinyin:"zì yú · zì lè",meaning:"从自身生活、所学中获得快乐。另：此处不强作互斥定义。"},{id:"rangwang-qiaoran",term:"愀然",pinyin:"qiǎo rán",meaning:"神色改变、受到触动的样子。另：不必只译为悲伤。"},{id:"rangwang-shenzide",term:"审自得",pinyin:"shěn zì dé",meaning:"明确认识自己的自得，有切实的内在把握。"},{id:"rangwang-shizhibuju",term:"失之而不惧",pinyin:"shī zhī ér bù jù",meaning:"遇到外在所得的丧失仍不惧。另：“之”的具体所指不强定，也不等于所有失去都没有痛苦。"},{id:"rangwang-xingxiuyunei",term:"行修于内",pinyin:"xíng xiū yú nèi",meaning:"行为修养落实于自身，不只是求取外在表现。"},{id:"rangwang-zuo",term:"怍",pinyin:"zuò",meaning:"羞愧。"},{id:"rangwang-songzhi",term:"诵之",pinyin:"sòng zhī",meaning:"诵读、熟记这些话。"},{id:"rangwang-shiqiuzhide",term:"是丘之得",pinyin:"shì qiū zhī dé",meaning:"这是我的所得、领会。另：此处不指财物所得。"},{id:"rangwang-gongzimou",term:"中山公子牟·魏牟",pinyin:"人物称名，牟通常读 móu",meaning:"本段对同一人物的称名。另：沿用原文，不据称名强行补定完整生平。"},{id:"rangwang-zhanzi",term:"瞻子",pinyin:"zhān zǐ",meaning:"对话中的人物。"},{id:"rangwang-jianghaizhishang",term:"江海之上",pinyin:"jiāng hǎi zhī shàng",meaning:"远离朝廷的江海之地，联系隐居处境理解。"},{id:"rangwang-weique",term:"魏阙",pinyin:"wèi què",meaning:"宫门高阙，代指朝廷。另：不能仅因“魏”字便拆成魏国宫门。"},{id:"rangwang-zhongsheng",term:"重生",pinyin:"zhòng shēng",meaning:"看重生命。另：不是现代“重新出生”。"},{id:"rangwang-liqing",term:"利轻",pinyin:"lì qīng",meaning:"利益相较之下变轻，不再占据最高位置。"},{id:"rangwang-zisheng",term:"自胜",pinyin:"zì shèng",meaning:"克服自身仍受利禄牵引的欲求。"},{id:"rangwang-zecong",term:"则从",pinyin:"zé cóng",meaning:"暂顺其所欲，不强行逆拒。另：原文未展开具体实行方式，不推广为任何欲望都应实行。"},{id:"rangwang-shenwuehu",term:"神无恶乎",pinyin:"语意、音读待辨",meaning:"通常联系避免心神厌苦、不安理解。另：神指精神、心神；不把“恶”直接解释为道德邪恶。"},{id:"rangwang-qiangbucong",term:"强不从",pinyin:"qiǎng bù cóng",meaning:"强行使自己不顺从所欲。"},{id:"rangwang-chongshang",term:"重伤",pinyin:"通常读 chóng shāng",meaning:"再伤、双重损伤。另：不只按现代“伤势严重”理解。"},{id:"rangwang-wushoulei",term:"无寿类",pinyin:"训释待辨",meaning:"大意为难以长寿、不能保全寿命。"},{id:"rangwang-wansheng",term:"万乘",pinyin:"wàn shèng",meaning:"大国的称谓。另：不机械理解为实有一万辆战车。"},{id:"rangwang-buyizhishi",term:"布衣之士",pinyin:"bù yī zhī shì",meaning:"无贵族身份、官位的普通士人。"},{id:"rangwang-youqiyi",term:"有其意",pinyin:"yǒu qí yì",meaning:"已有向道、重生的意向。另：不等于已经达到。"},{id:"rangwang-qiongyuchencai",term:"穷于陈蔡",pinyin:"qióng yú chén cài",meaning:"在陈、蔡之间陷入困境。"},{id:"rangwang-buhuoshi",term:"不火食",pinyin:"bù huǒ shí",meaning:"不能生火做饭、不得熟食，表现食物匮乏。"},{id:"rangwang-ligeng",term:"藜羹",pinyin:"lí gēng",meaning:"用藜等野菜做成的汤。"},{id:"rangwang-busan",term:"不糁",pinyin:"bù sǎn",meaning:"没有掺入米粒等粮食。"},{id:"rangwang-yanseshenbei",term:"颜色甚惫",pinyin:"yán sè shèn bèi",meaning:"面容十分疲惫。"},{id:"rangwang-xiangyuyan",term:"相与言",pinyin:"xiāng yǔ yán",meaning:"一起议论。"},{id:"rangwang-zaizhu",term:"再逐",pinyin:"zài zhú",meaning:"再次或两次被逐。另：不据此强编精确年表。"},{id:"rangwang-xueji",term:"削迹",pinyin:"xuē jì",meaning:"通常联系驱逐、不得留居或行迹受阻理解。"},{id:"rangwang-jiefuzi",term:"藉夫子",pinyin:"训释待辨",meaning:"通常联系凌辱、践踏孔子理解。另：不作现代“借用”义。"},{id:"rangwang-kuiran",term:"喟然",pinyin:"kuì rán",meaning:"叹息的样子。"},{id:"rangwang-youci",term:"由·赐",pinyin:"yóu · cì",meaning:"子路、子贡的名。"},{id:"rangwang-xiren",term:"细人",pinyin:"xì rén",meaning:"识见狭小的人，此处批评二人的判断。另：不据此将二人的全部人格与理解能力固定化。"},{id:"rangwang-tongyudao",term:"通于道",pinyin:"tōng yú dào",meaning:"在道上贯通、通达。"},{id:"rangwang-qiongyudao",term:"穷于道",pinyin:"qióng yú dào",meaning:"在道上受阻、困窘。"},{id:"rangwang-neixing",term:"内省",pinyin:"nèi xǐng",meaning:"反观、检验自身。"},{id:"rangwang-ai",term:"隘",pinyin:"ài",meaning:"困厄、窘迫处境。"},{id:"rangwang-xiaoran",term:"削然",pinyin:"异文、音读待辨",meaning:"常联系从容、洒然的神态理解。另：不直接按削减之义拆译。"},{id:"rangwang-fanqin",term:"反琴",pinyin:"fǎn qín",meaning:"重新拿起、回到弹琴之事。"},{id:"rangwang-geran",term:"扢然",pinyin:"音读、训释待辨",meaning:"此处联系振奋、兴起的样子理解。另：原文保留所附“音ｘｉ４”，不将该音注视为唯一读法。"},{id:"rangwang-gan",term:"干",pinyin:"gān",meaning:"盾牌，舞蹈中所执之物。"},{id:"rangwang-suolefeiqiongtong",term:"所乐非穷通",pinyin:"suǒ lè fēi qióng tōng",meaning:"快乐的根源不在外在困窘或显达本身。"},{id:"rangwang-daodeyuci",term:"道德于此",pinyin:"句义、训释待辨",meaning:"可联系于此得道、体道理解；德常联系得义解释。另：不直接按现代名词“道德”拆译。"},{id:"rangwang-yingyang",term:"颖阳·颍阳",pinyin:"yǐng yáng",meaning:"通常联系颍水之阳理解，为故事中许由自得之地。另：原文保留“颖阳”；常见写法为“颍阳”。"},{id:"rangwang-gongbo",term:"共伯",pinyin:"gòng bó",meaning:"传说人物，通常联系共伯和理解。另：历史身份与相关叙事存在争议。"},{id:"rangwang-qiushou",term:"丘首",pinyin:"qiū shǒu",meaning:"地名、隐居处称谓。另：具体地望不强定。"},{id:"rangwang-beirenwuze",term:"北人无择",pinyin:"běi rén wú zé",meaning:"人物称名。另：不按字面解释为“北方没有选择的人”。"},{id:"rangwang-quanmu",term:"畎亩",pinyin:"quǎn mǔ",meaning:"田间、农耕之地；畎为田间沟渠。"},{id:"rangwang-youyaozhimen",term:"游尧之门",pinyin:"yóu yáo zhī mén",meaning:"往来、交游于尧的门下，涉及进入政治关系。"},{id:"rangwang-buruoshi",term:"不若是而已",pinyin:"句法、训释待辨",meaning:"常联系“不仅如此”理解，即舜的行为不止于往尧之门。"},{id:"rangwang-ruxing",term:"辱行",pinyin:"rǔ xíng",meaning:"被说话者认为可耻、有辱的行为。另：应区分人物的评价与已经得到独立证明的事实。"},{id:"rangwang-manwo",term:"漫我",pinyin:"màn wǒ",meaning:"污及、污辱我。另：不是现代“漫游”之义。"},{id:"rangwang-xiujianzhi",term:"羞见之",pinyin:"xiū jiàn zhī",meaning:"以见到他为羞耻，或不愿再见其行为。另：“之”的指向不强定。"},{id:"rangwang-qingling",term:"清泠",pinyin:"qīng líng",meaning:"水名或深渊名称。另：不凭此句确定地望。"},{id:"rangwang-yin-sequence",term:"因",pinyin:"yīn",meaning:"此处为于是、随后。"},{id:"rangwang-zitou",term:"自投",pinyin:"zì tóu",meaning:"自己投入水中。另：不同于开篇携家“入于海”的远避。"},{id:"rangwang-tangjie",term:"汤·桀",pinyin:"tāng · jié",meaning:"商汤、夏桀，故事中的征伐双方。"},{id:"rangwang-yinermou",term:"因……而谋",pinyin:"按句义理解",meaning:"就某人询问、商议此事。"},{id:"rangwang-biansui",term:"卞随",pinyin:"biàn suí",meaning:"人物名。"},{id:"rangwang-maoguang",term:"瞀光",pinyin:"mào guāng",meaning:"人物名。另：可与其他文本的“务光”等称名参照，不直接混写。"},{id:"rangwang-feiwushi",term:"非吾事也",pinyin:"fēi wú shì yě",meaning:"这不是我的事，我不参与。"},{id:"rangwang-shuke",term:"孰可",pinyin:"shú kě",meaning:"谁可以承担、参与此事？"},{id:"rangwang-qianglirengou",term:"强力忍垢",pinyin:"qiáng lì rěn gòu",meaning:"有强力，能够忍受污垢、屈辱。另：须结合拒谋背景理解，不直接当作全面推荐。"},{id:"rangwang-kezhi",term:"克之",pinyin:"kè zhī",meaning:"战胜桀。"},{id:"rangwang-zei",term:"贼",pinyin:"zéi",meaning:"此处联系乱臣、参与攻杀之人理解。另：不只是现代偷窃者。"},{id:"rangwang-tan",term:"贪",pinyin:"tān",meaning:"贪求权位、利益。"},{id:"rangwang-zailai",term:"再来",pinyin:"zài lái",meaning:"又来、两度来；承接询谋与让位。"},{id:"rangwang-shuowen",term:"数闻",pinyin:"shuò wén",meaning:"屡次听到。"},{id:"rangwang-choushui",term:"椆水",pinyin:"水名字形、音读待核",meaning:"故事中卞随投水之处。另：保留所供写法，不强定地望。"},{id:"rangwang-zhizhe",term:"知者",pinyin:"zhì zhě",meaning:"有智谋者；知通“智”。"},{id:"rangwang-suizhi",term:"遂之",pinyin:"suì zhī",meaning:"完成这件事。"},{id:"rangwang-juzhi",term:"居之",pinyin:"jū zhī",meaning:"居于君位，接受所得天下。"},{id:"rangwang-li-enthrone",term:"立",pinyin:"lì",meaning:"立为君主、即位。"},{id:"rangwang-feishang",term:"废上",pinyin:"fèi shàng",meaning:"废黜原有君主。"},{id:"rangwang-fanqinan",term:"犯其难",pinyin:"fàn qí nàn",meaning:"冒其危险，承担征伐的艰难。"},{id:"rangwang-lian",term:"廉",pinyin:"lián",meaning:"不苟取、不以不合宜方式取得利益。"},{id:"rangwang-feiqiyi",term:"非其义者",pinyin:"fēi qí yì zhě",meaning:"不合于义的授受或对象。另：具体指向结合上下文理解。"},{id:"rangwang-bujianqitu",term:"不践其土",pinyin:"bù jiàn qí tǔ",meaning:"不踏其土地，表达拒绝置身其中的立场。"},{id:"rangwang-zunwo",term:"尊我",pinyin:"zūn wǒ",meaning:"使我居于尊位。"},{id:"rangwang-zichen",term:"自沈",pinyin:"zì chén",meaning:"自沉于水；沈在此同“沉”。"},{id:"rangwang-lushui",term:"庐水",pinyin:"lú shuǐ",meaning:"故事中瞀光自沉之处。另：保留所供写法，不强定地望。"},{id:"rangwang-zhouzhixing",term:"周之兴",pinyin:"zhōu zhī xīng",meaning:"周兴起、取得天下的背景。"},{id:"rangwang-guzhu",term:"孤竹",pinyin:"gū zhú",meaning:"古国名，故事中二人原居之地。"},{id:"rangwang-boyishuqi",term:"伯夷·叔齐",pinyin:"bó yí · shū qí",meaning:"传说中的兄弟，在多种先秦文献中出现。"},{id:"rangwang-siyoudaozhe",term:"似有道者",pinyin:"sì yǒu dào zhě",meaning:"仿佛、可能是有道者，尚未作最终确认。"},{id:"rangwang-shiwangguan",term:"试往观焉",pinyin:"shì wǎng guān yān",meaning:"姑且前往观察、了解。"},{id:"rangwang-qiyang",term:"岐阳",pinyin:"qí yáng",meaning:"岐山之阳、南面一带。"},{id:"rangwang-shudan",term:"叔旦",pinyin:"shū dàn",meaning:"通常理解为周公旦。"},{id:"rangwang-yumeng",term:"与盟",pinyin:"yǔ méng",meaning:"与二人订立盟约。"},{id:"rangwang-jiafu",term:"加富二等",pinyin:"jiā fù èr děng",meaning:"增加财富待遇，按等级给予。另：具体制度不强定。"},{id:"rangwang-jiuguan",term:"就官一列",pinyin:"jiù guān yī liè",meaning:"安排官位、列于官职之中。另：具体官阶不强定。"},{id:"rangwang-xuesheng",term:"血牲而埋之",pinyin:"按句义理解",meaning:"杀牲取血并埋牲，作为盟誓仪式。"},{id:"rangwang-shennong",term:"神农",pinyin:"shén nóng",meaning:"古代传说人物，此处作为理想治理的参照。"},{id:"rangwang-shisi",term:"时祀",pinyin:"shí sì",meaning:"按时举行祭祀。"},{id:"rangwang-buqixi",term:"不祈喜",pinyin:"bù qí xǐ",meaning:"不以祭祀求取福庆、好处。"},{id:"rangwang-zhongxinjinzhi",term:"忠信尽治",pinyin:"zhōng xìn jìn zhì",meaning:"以忠信尽其治理、照料之责。"},{id:"rangwang-leyuzheng",term:"乐与政为政，乐与治为治",pinyin:"训释待辨",meaning:"可联系顺应人们乐于接受的政、治而施行理解。另：不作唯一逐字定解，也不补成现代制度。"},{id:"rangwang-zaoshi",term:"遭时",pinyin:"zāo shí",meaning:"遇到时机、时势。"},{id:"rangwang-ju",term:"遽",pinyin:"jù",meaning:"急速、急切。"},{id:"rangwang-xinghuo",term:"行货",pinyin:"xíng huò",meaning:"以财货施行笼络、收买等安排。另：不按现代商品流通理解。"},{id:"rangwang-zubing",term:"阻兵",pinyin:"zǔ bīng",meaning:"凭恃、依仗兵力。"},{id:"rangwang-yangxing-display",term:"扬行",pinyin:"yáng xíng",meaning:"宣扬自己的行为、功绩。"},{id:"rangwang-yuezhong",term:"说众",pinyin:"yuè zhòng",meaning:"使众人悦服；说通“悦”。"},{id:"rangwang-yaoli",term:"要利",pinyin:"yāo lì",meaning:"求取利益。"},{id:"rangwang-tuiluanyibao",term:"推乱以易暴",pinyin:"语义、训释待辨",meaning:"大意涉及以新的乱或暴取代旧的乱暴。另：不强定每一字的对应关系。"},{id:"rangwang-buweigoucun",term:"不为苟存",pinyin:"bù wéi gǒu cún",meaning:"不以苟且存活为唯一目的。"},{id:"rangwang-an",term:"闇",pinyin:"àn",meaning:"昏暗、不明。"},{id:"rangwang-binghuzhou",term:"并乎周",pinyin:"bìng hū zhōu",meaning:"与周合流、依附于周。"},{id:"rangwang-tuwushen",term:"涂吾身",pinyin:"tú wú shēn",meaning:"污染自身；涂联系污涂理解。"},{id:"rangwang-jiewuxing",term:"洁吾行",pinyin:"jié wú xíng",meaning:"使自己的行为保持洁净。"},{id:"rangwang-shouyang",term:"首阳之山",pinyin:"shǒu yáng zhī shān",meaning:"故事中的隐居、死亡之地。另：具体地望存在不同说法。"},{id:"rangwang-goukedeyi",term:"苟可得已",pinyin:"训释待辨",meaning:"通常联系“如果可以止、可以不取”理解。另：不径译为“如果能够得到富贵”。"},{id:"rangwang-bulaigaojie",term:"不赖高节戾行",pinyin:"训释待辨",meaning:"可联系不凭恃、标榜高节与异行理解。另：需与“独乐其志”合看，不将贯通解释当作唯一字义。"}],w=[{id:"rangwang-01",label:"辞让天下：不以权位伤生",sentences:[["尧以",{text:"天下",glossary:"rangwang-tianxia"},{text:"让",glossary:"rangwang-rang"},"许由，",{text:"许由",glossary:"rangwang-xuyou"},"不受。"],["又让于",{text:"子州支父",glossary:"rangwang-zizhou"},"，",{text:"子州之父",glossary:"rangwang-zizhou"},"曰：“以我为天子，",{text:"犹之可也",glossary:"rangwang-youzhike"},"。",{text:"虽然",glossary:"rangwang-suiran"},"，我",{text:"适",glossary:"rangwang-shi"},"有",{text:"幽忧之病",glossary:"rangwang-youyou"},"，",{text:"方且治之",glossary:"rangwang-fangqiezhi"},"，",{text:"未暇",glossary:"rangwang-weixia"},"治天下也。”"],["夫天下",{text:"至重",glossary:"rangwang-zhizhong"},"也，而不以害其生，又况他物乎！唯",{text:"无以天下为",glossary:"rangwang-wuyitianxia"},"者可以",{text:"托天下",glossary:"rangwang-tuotianxia"},"也。"],["舜让天下于",{text:"子州之伯",glossary:"rangwang-zizhou"},"，子州之伯曰：“予适有",{text:"幽忧之病",glossary:"rangwang-youyou"},"，",{text:"方且治之",glossary:"rangwang-fangqiezhi"},"，",{text:"未暇",glossary:"rangwang-weixia"},"治天下也。”故天下",{text:"大器",glossary:"rangwang-daqi"},"也，而不以",{text:"易生",glossary:"rangwang-yisheng"},"。此有道者之所以异乎俗者也。"],["舜以天下让善卷，善卷曰：“余立于宇宙之中，冬日",{text:"衣皮毛",glossary:"rangwang-yipimao"},"，夏日衣",{text:"葛絺",glossary:"rangwang-gechi"},"。春耕种，形足以劳动；秋",{text:"收敛",glossary:"rangwang-shoulian"},"，身足以",{text:"休食",glossary:"rangwang-xiushi"},"。日出而作，日入而息，逍遥于天地之间，而",{text:"心意自得",glossary:"rangwang-zide"},"。吾何以天下为哉！悲夫，子之不知余也。”遂不受。于是去而入深山，莫知其处。"],["舜以天下让其友石户之农。石户之农曰：“",{text:"捲捲",glossary:"rangwang-quanquan"},"乎，",{text:"后",glossary:"rangwang-hou"},"之为人，",{text:"葆力之士",glossary:"rangwang-baoli"},"也。”以舜之德为未至也。于是",{text:"夫负妻戴",glossary:"rangwang-fufu-qidai"},"，携子以",{text:"入于海",glossary:"rangwang-ruhai"},"，终身不",{text:"反",glossary:"rangwang-fan"},"也。"]]},{id:"rangwang-02",label:"太王迁岐：不以所用养害所养",sentences:[[{text:"大王",glossary:"rangwang-taiwang"},{text:"亶父",glossary:"rangwang-danfu"},"居",{text:"豳",glossary:"rangwang-bin"},"，",{text:"狄人",glossary:"rangwang-diren"},"攻之。",{text:"事之以",glossary:"rangwang-shizhiyi"},{text:"皮帛",glossary:"rangwang-pibo"},"而不受，事之以犬马而不受，事之以珠玉而不受。狄人之所求者土地也。"],[{text:"大王囗父",glossary:"rangwang-danfu"},"曰：“",{text:"与人之兄居而杀其弟",glossary:"rangwang-yuren"},"，与人之父居而杀其子，吾不忍也。",{text:"子皆勉居矣",glossary:"rangwang-mianju"},"！为吾臣与为狄人臣",{text:"奚以异",glossary:"rangwang-xiyiyi"},"。且吾闻之：不以",{text:"所用养",glossary:"rangwang-suoyongyang"},"害",{text:"所养",glossary:"rangwang-suoyang"},"。”"],["因",{text:"杖生䇲",glossary:"rangwang-zhangshengce"},"而去之。民",{text:"相连而从",glossary:"rangwang-xianglian"},"之。遂成国于岐山之下。"],["夫",{text:"大王囗父",glossary:"rangwang-danfu"},"可谓能",{text:"尊生",glossary:"rangwang-zunsheng"},"矣。能尊生者，虽贵富不",{text:"以养伤身",glossary:"rangwang-yiyangshangshen"},"，虽贫贱不",{text:"以利累形",glossary:"rangwang-yilileixing"},"。"],["今世之人居高官尊爵者，皆",{text:"重失之",glossary:"rangwang-zhongshizhi"},"。见利",{text:"轻亡其身",glossary:"rangwang-qingwang"},"，岂不惑哉！"]]},{id:"rangwang-03",label:"王子搜避位：君位与为君之患",sentences:[["越人",{text:"三世弑其君",glossary:"rangwang-sanshishi"},"，",{text:"王子搜",glossary:"rangwang-wangzisou"},{text:"患之",glossary:"rangwang-huanzhi"},"，逃乎",{text:"丹穴",glossary:"rangwang-danxue"},"，而越国无君。"],["求王子搜不得，",{text:"从之丹穴",glossary:"rangwang-congzhidanxue"},"。王子搜不肯出，越人",{text:"熏之以艾",glossary:"rangwang-xunyiai"},"。乘以",{text:"王舆",glossary:"rangwang-wangyu"},"。"],["王子搜",{text:"援绥",glossary:"rangwang-yuansui"},"登车，仰天而呼曰：“君乎，君乎，独不可以",{text:"舍我",glossary:"rangwang-shewo"},"乎！”"],["王子搜非",{text:"恶为君",glossary:"rangwang-wuweijun"},"也，恶",{text:"为君之患",glossary:"rangwang-weijunzhihuan"},"也。若王子搜者，可谓不以国伤生矣！此固越人之所欲得为君也。"]]},{id:"rangwang-04",label:"子华子辨轻重：所求与所付的代价",sentences:[["韩魏",{text:"相与",glossary:"rangwang-xiangyu"},{text:"争侵地",glossary:"rangwang-zhengqindi"},"，",{text:"子华子",glossary:"rangwang-zihuazi"},"见昭僖侯，昭僖侯有忧色。"],["子华子曰：“今使天下",{text:"书铭",glossary:"rangwang-shuming"},"于君之前，书之言曰：‘左手",{text:"攫",glossary:"rangwang-jue"},"之则右手",{text:"废",glossary:"rangwang-fei"},"，右手攫之则左手废。然而攫之者必",{text:"有天下",glossary:"rangwang-youtianxia"},"。’君能攫之乎？”昭僖侯曰：“寡人不攫也。”"],["子华子曰：“甚善！",{text:"自是观之",glossary:"rangwang-zishiguanzhi"},"，两臂重于天下也。身亦重于两臂。韩之轻于天下亦远矣！今之所争者，其轻于韩又远。君固",{text:"愁身伤生",glossary:"rangwang-choushenshangsheng"},"以",{text:"忧戚",glossary:"rangwang-youqi"},{text:"不得",glossary:"rangwang-bude"},"也。”"],["僖侯曰：“善哉！教寡人者众矣，未尝得闻此言也。”子华子可谓",{text:"知轻重",glossary:"rangwang-zhiqingzhong"},"矣！"]]},{id:"rangwang-05",label:"颜阖避聘：认可未必是自己所需",sentences:[["鲁君闻",{text:"颜阖",glossary:"rangwang-yanhe"},{text:"得道之人",glossary:"rangwang-dedaozhiren"},"也，使人以",{text:"币",glossary:"rangwang-bi"},"先焉。"],["颜阖守",{text:"陋闾",glossary:"rangwang-loulv"},"，",{text:"苴布",glossary:"rangwang-jubu"},"之衣而自",{text:"饭牛",glossary:"rangwang-fanniu"},"。"],["鲁君之使者至，颜阖",{text:"自对之",glossary:"rangwang-ziduizhi"},"。"],["使者曰：「此颜阖之家",{text:"与",glossary:"rangwang-yu-question"},"？」"],["颜阖对曰：「此阖之家也。」使者",{text:"致币",glossary:"rangwang-zhibi"},"，"],["颜阖曰：「恐",{text:"听者谬",glossary:"rangwang-tingmiu"},"而",{text:"遗使者罪",glossary:"rangwang-yishizhezui"},"，不若",{text:"审之",glossary:"rangwang-shenzhi"},"。」"],["使者",{text:"还",glossary:"rangwang-huan"},{text:"反",glossary:"rangwang-fan"},"审之，复来求之，则不得已。"],["故若颜阖者，真",{text:"恶富贵",glossary:"rangwang-wufugui"},"也。"]]},{id:"rangwang-06",label:"治身与殉物：所用不可重于所求",sentences:[["故曰：",{text:"道之真",glossary:"rangwang-daozhizhen"},"以",{text:"治身",glossary:"rangwang-zhishen"},"，其",{text:"绪余",glossary:"rangwang-xuyu"},"以",{text:"为国家",glossary:"rangwang-weiguojia"},"，其",{text:"土苴",glossary:"rangwang-tuju"},"以治天下。"],["由此观之，",{text:"帝王之功",glossary:"rangwang-diwangzhigong"},"，圣人之",{text:"余事",glossary:"rangwang-yushi"},"也，非所以",{text:"完身",glossary:"rangwang-wanshen"},{text:"养生",glossary:"rangwang-yangsheng"},"也。"],["今世俗之君子，多",{text:"危身弃生",glossary:"rangwang-weishenqisheng"},"以",{text:"殉物",glossary:"rangwang-xunwu"},"，岂不悲哉！"],["凡圣人之动作也，必察其",{text:"所以之",glossary:"rangwang-suoyizhi"},"与其",{text:"所以为",glossary:"rangwang-suoyiwei"},"。"],["今且有人于此，以",{text:"随侯之珠",glossary:"rangwang-suihouzhizhu"},"，",{text:"弹",glossary:"rangwang-tanque"},{text:"千仞",glossary:"rangwang-qianren"},"之雀，世必笑之。"],["是何也？则其",{text:"所用",glossary:"rangwang-suoyong"},"者重而",{text:"所要",glossary:"rangwang-suoyao"},"者轻也。夫生者",{text:"岂特",glossary:"rangwang-qite"},"随侯之重哉！"]]},{id:"rangwang-07",label:"列子辞粟：给予的依据与关系风险",sentences:[[{text:"子列子",glossary:"rangwang-ziliezi"},{text:"穷",glossary:"rangwang-qiong"},"，容貌有",{text:"饥色",glossary:"rangwang-jise"},"。"],["客有言之于",{text:"郑子阳",glossary:"rangwang-zhengziyang"},"者，曰：“",{text:"列御寇",glossary:"rangwang-lieyukou"},"，盖有道之士也，居君之国而穷，君",{text:"无乃",glossary:"rangwang-wunai"},"为不",{text:"好士",glossary:"rangwang-haoshi"},"乎？”"],["郑子阳即令官",{text:"遗之粟",glossary:"rangwang-weizhisu"},"。子列子见使者，",{text:"再拜",glossary:"rangwang-zaibai"},"而辞。"],["使者去，子列子入，其妻望之而",{text:"拊心",glossary:"rangwang-fuxin"},"曰：“妾闻为有道者之",{text:"妻子",glossary:"rangwang-qizi"},"，皆得",{text:"佚乐",glossary:"rangwang-yile"},"。今有饥色，",{text:"君过",glossary:"rangwang-junguo"},"而遗先生食，先生不受，",{text:"岂不命邪",glossary:"rangwang-qibumingye"},"？”"],["子列子笑，谓之曰：“君非",{text:"自知我",glossary:"rangwang-zizhiwo"},"也，以人之言而遗我粟；至其",{text:"罪我",glossary:"rangwang-zuiwo"},"也，又且以人之言，此吾所以不受也。”"],[{text:"其卒",glossary:"rangwang-qizu"},"，民果",{text:"作难",glossary:"rangwang-zuonan"},"而杀子阳。"]]},{id:"rangwang-08",label:"屠羊说辞赏：功罪、法约与辞受之义",sentences:[[{text:"楚昭王",glossary:"rangwang-chuzhaowang"},{text:"失国",glossary:"rangwang-shiguo"},"，",{text:"屠羊说",glossary:"rangwang-tuyangyue"},{text:"走",glossary:"rangwang-zou"},"而",{text:"从于昭王",glossary:"rangwang-congyzhaowang"},"。"],["昭王",{text:"反国",glossary:"rangwang-fanguo"},"，将赏",{text:"从者",glossary:"rangwang-congzhe"},"。及屠羊说。"],["屠羊说曰：“",{text:"大王",glossary:"rangwang-dawang-chu"},"失国，说失屠羊。大王反国，说亦",{text:"反屠羊",glossary:"rangwang-fantuyang"},"。臣之",{text:"爵禄",glossary:"rangwang-juelu"},"已复矣，",{text:"又何赏之有",glossary:"rangwang-youheshang"},"。”"],["王曰：“",{text:"强之",glossary:"rangwang-qiangzhi"},"。”屠羊说曰：“大王失国，非臣之罪，故不敢",{text:"伏其诛",glossary:"rangwang-fuqizhu"},"；大王反国，非臣之功，故不敢",{text:"当其赏",glossary:"rangwang-dangqishang"},"。”"],["王曰：“",{text:"见之",glossary:"rangwang-jianzhi"},"。”屠羊说曰：“楚国之法，必有",{text:"重赏大功",glossary:"rangwang-zhongshangdagong"},"而后得见。今臣之",{text:"知",glossary:"rangwang-zhi"},"不足以",{text:"存国",glossary:"rangwang-cunguo"},"，而勇不足以",{text:"死寇",glossary:"rangwang-sikou"},"。"],["吴军入",{text:"郢",glossary:"rangwang-ying"},"，说畏难而避寇，",{text:"非故随大王",glossary:"rangwang-feigusui"},"也。今大王欲",{text:"废法毁约",glossary:"rangwang-feifahuiyue"},"而见说，此非臣之所以",{text:"闻于天下",glossary:"rangwang-wenyutianxia"},"也。”"],["王谓",{text:"司马子綦",glossary:"rangwang-simaziqi"},"曰：“屠羊说居处卑贱而陈义甚高，子綦为我",{text:"延之",glossary:"rangwang-yanzhi"},"以",{text:"三旌之位",glossary:"rangwang-sanjing"},"。”"],["屠羊说曰：“夫",{text:"三旌之位",glossary:"rangwang-sanjing"},"，吾知其贵于屠羊之",{text:"肆",glossary:"rangwang-si"},"也；",{text:"万锺之禄",glossary:"rangwang-wanzhong"},"，吾知其富于屠羊之利也。"],["然岂可以贪",{text:"爵禄",glossary:"rangwang-juelu"},"而使吾君有",{text:"妄施",glossary:"rangwang-wangshi"},"之名乎？说不敢当，愿",{text:"复反",glossary:"rangwang-fufan"},"吾屠羊之",{text:"肆",glossary:"rangwang-si"},"。”遂不受也。"]]},{id:"rangwang-09",label:"原宪贫而非病：财物与实践的区别",sentences:[[{text:"原宪",glossary:"rangwang-yuanxian"},"居鲁，",{text:"环堵之室",glossary:"rangwang-huandu"},"，",{text:"茨",glossary:"rangwang-ci"},"以",{text:"生草",glossary:"rangwang-shengcao"},"，",{text:"蓬户",glossary:"rangwang-penghu"},{text:"不完",glossary:"rangwang-buwan"},"，桑以为",{text:"枢",glossary:"rangwang-shu"},"而",{text:"瓮牖",glossary:"rangwang-wengyou"},"，",{text:"二室",glossary:"rangwang-ershi"},"，",{text:"褐",glossary:"rangwang-he"},"以为塞，上漏下湿，",{text:"匡坐",glossary:"rangwang-kuangzuo"},"而",{text:"弦歌",glossary:"rangwang-xiange"},"。"],["子贡乘大马，",{text:"中绀而表素",glossary:"rangwang-zhonggan"},"，",{text:"轩车",glossary:"rangwang-xuanche"},"不容巷，往见原宪。原宪",{text:"华冠",glossary:"rangwang-huaguan"},{text:"𫄳履",glossary:"rangwang-lvyi"},"，",{text:"杖藜",glossary:"rangwang-zhangli"},"而应门。"],["子贡曰：“嘻！先生何",{text:"病",glossary:"rangwang-bing-yuanxian"},"？”原宪应之曰：“宪闻之，无财谓之贫，学而不能行谓之病。今宪贫也，非病也。”"],["子贡",{text:"逡巡",glossary:"rangwang-qunxun"},"而有愧色。原宪笑曰：“夫",{text:"希世",glossary:"rangwang-xishi"},"而行，",{text:"比周",glossary:"rangwang-bizhou"},"而友，",{text:"学以为人",glossary:"rangwang-xueyiweiren"},"，",{text:"教以为己",glossary:"rangwang-jiaoyiweiji"},"，仁义之",{text:"慝",glossary:"rangwang-te"},"，",{text:"舆马之饰",glossary:"rangwang-yumazhishi"},"，宪不忍为也。”"]]},{id:"rangwang-10",label:"曾子贫居：困苦、独立与三种忘",sentences:[[{text:"曾子",glossary:"rangwang-zengzi"},"居卫，",{text:"緼（ｙｕｎ４）袍",glossary:"rangwang-yunpao"},{text:"无表",glossary:"rangwang-wubiao"},"，",{text:"颜色",glossary:"rangwang-yanse"},{text:"肿哙",glossary:"rangwang-zhongkuai"},"，手足",{text:"胼胝",glossary:"rangwang-pianzhi"},"，三日",{text:"不举火",glossary:"rangwang-bujuhuo"},"，十年不",{text:"制衣",glossary:"rangwang-zhiyi"},"。"],["正冠而",{text:"缨",glossary:"rangwang-ying-band"},"绝，",{text:"捉襟",glossary:"rangwang-zhuojin"},"而",{text:"肘见",glossary:"rangwang-zhouxian"},"，",{text:"纳屦",glossary:"rangwang-naju"},"而",{text:"踵决",glossary:"rangwang-zhongjue"},"。"],[{text:"曳纵",glossary:"rangwang-yezong"},"而歌《",{text:"商颂",glossary:"rangwang-shangsong"},"》，声满天地，若出",{text:"金石",glossary:"rangwang-jinshi"},"。天子",{text:"不得臣",glossary:"rangwang-budechen"},"，诸侯",{text:"不得友",glossary:"rangwang-budeyou"},"。"],["故",{text:"养志",glossary:"rangwang-yangzhi"},"者忘形，",{text:"养形",glossary:"rangwang-yangxing"},"者忘利，",{text:"致道",glossary:"rangwang-zhidao"},"者",{text:"忘心",glossary:"rangwang-wangxin"},"矣。"]]},{id:"rangwang-11",label:"颜回不仕：知足、自得与行修于内",sentences:[["孔子谓颜回曰：“回，来！",{text:"家贫居卑",glossary:"rangwang-jiapinjubei"},"，",{text:"胡不仕乎",glossary:"rangwang-hubushihu"},"？”"],["颜回对曰：“不愿",{text:"仕",glossary:"rangwang-shi-office"},"。回有",{text:"郭外",glossary:"rangwang-guoneiwai"},"之田五十亩，",{text:"足以给",glossary:"rangwang-zuyiji"},{text:"𫗞粥",glossary:"rangwang-zhanzhou"},"；",{text:"郭内",glossary:"rangwang-guoneiwai"},"之田十亩，足以为",{text:"丝麻",glossary:"rangwang-sima"},"；鼓琴足以",{text:"自娱",glossary:"rangwang-ziyuzile"},"；所学夫子之道者足以自乐也。回不愿仕。”"],["孔子",{text:"愀然",glossary:"rangwang-qiaoran"},"变容，曰：“善哉，回之意！丘闻之：‘知足者，不以利自累也；",{text:"审自得",glossary:"rangwang-shenzide"},"者，",{text:"失之而不惧",glossary:"rangwang-shizhibuju"},"；",{text:"行修于内",glossary:"rangwang-xingxiuyunei"},"者，无位而不",{text:"怍",glossary:"rangwang-zuo"},"。’丘",{text:"诵之",glossary:"rangwang-songzhi"},"久矣，今于回而后见之，",{text:"是丘之得",glossary:"rangwang-shiqiuzhide"},"也。”"]]},{id:"rangwang-12",label:"公子牟身隐心仕：未能自胜与重伤",sentences:[[{text:"中山公子牟",glossary:"rangwang-gongzimou"},"谓",{text:"瞻子",glossary:"rangwang-zhanzi"},"曰：“身在",{text:"江海之上",glossary:"rangwang-jianghaizhishang"},"，心居乎",{text:"魏阙",glossary:"rangwang-weique"},"之下，奈何？”"],["瞻子曰：“",{text:"重生",glossary:"rangwang-zhongsheng"},"。重生则",{text:"利轻",glossary:"rangwang-liqing"},"。”中山公子牟曰：“虽知之，未能",{text:"自胜",glossary:"rangwang-zisheng"},"也。”"],["瞻子曰：“不能自胜",{text:"则从",glossary:"rangwang-zecong"},"，",{text:"神无恶乎",glossary:"rangwang-shenwuehu"},"！不能自胜而",{text:"强不从",glossary:"rangwang-qiangbucong"},"者，此之谓",{text:"重伤",glossary:"rangwang-chongshang"},"。重伤之人，",{text:"无寿类",glossary:"rangwang-wushoulei"},"矣！”"],[{text:"魏牟",glossary:"rangwang-gongzimou"},"，",{text:"万乘",glossary:"rangwang-wansheng"},"之公子也，其隐岩穴也，难为于",{text:"布衣之士",glossary:"rangwang-buyizhishi"},"，虽未至乎道，可谓",{text:"有其意",glossary:"rangwang-youqiyi"},"矣！"]]},{id:"rangwang-13",label:"孔子困于陈蔡：穷通于道与临难不失德",sentences:[["孔子",{text:"穷于陈蔡",glossary:"rangwang-qiongyuchencai"},"之间，七日",{text:"不火食",glossary:"rangwang-buhuoshi"},"，",{text:"藜羹",glossary:"rangwang-ligeng"},{text:"不糁",glossary:"rangwang-busan"},"，",{text:"颜色甚惫",glossary:"rangwang-yanseshenbei"},"，而",{text:"弦歌",glossary:"rangwang-xiange"},"于室。"],["颜回择菜，子路、子贡",{text:"相与言",glossary:"rangwang-xiangyuyan"},"曰：“夫子",{text:"再逐",glossary:"rangwang-zaizhu"},"于鲁，",{text:"削迹",glossary:"rangwang-xueji"},"于卫，伐树于宋，穷于商周，围于陈蔡。杀夫子者无罪，",{text:"藉夫子",glossary:"rangwang-jiefuzi"},"者无禁。弦歌",{text:"鼓琴",glossary:"rangwang-guqin"},"，未尝绝音，君子之无耻也若此乎？”"],["颜回无以应，入告孔子。孔子推琴，",{text:"喟然",glossary:"rangwang-kuiran"},"而叹曰：“",{text:"由",glossary:"rangwang-youci"},"与",{text:"赐",glossary:"rangwang-youci"},"，",{text:"细人",glossary:"rangwang-xiren"},"也。召而来，吾语之。”"],["子路、子贡入。子路曰：“如此者，可谓穷矣！”孔子曰：“是何言也！君子",{text:"通于道",glossary:"rangwang-tongyudao"},"之谓通，",{text:"穷于道",glossary:"rangwang-qiongyudao"},"之谓穷。"],["今丘抱仁义之道以遭乱世之患，其何穷之为？故",{text:"内省",glossary:"rangwang-neixing"},"而不穷于道，临难而不失其德。天寒既至，霜雪既降，吾是以知松柏之茂也。陈蔡之",{text:"隘",glossary:"rangwang-ai"},"，于丘其幸乎。”"],["孔子",{text:"削然",glossary:"rangwang-xiaoran"},{text:"反琴",glossary:"rangwang-fanqin"},"而弦歌，子路",{text:"扢（音ｘｉ４）然",glossary:"rangwang-geran"},"执",{text:"干",glossary:"rangwang-gan"},"而舞。子贡曰：“吾不知天之高也，地之下也。”"],["古之得道者，穷亦乐，通亦乐，",{text:"所乐非穷通",glossary:"rangwang-suolefeiqiongtong"},"也。",{text:"道德于此",glossary:"rangwang-daodeyuci"},"，则穷通为寒暑风雨之序矣。故许由娱于",{text:"颖阳",glossary:"rangwang-yingyang"},"，而",{text:"共伯",glossary:"rangwang-gongbo"},"得乎",{text:"丘首",glossary:"rangwang-qiushou"},"。"]]},{id:"rangwang-14",label:"北人无择：拒辱与生命损失",sentences:[["舜以天下让其友",{text:"北人无择",glossary:"rangwang-beirenwuze"},"，"],["北人无择曰：「异哉！",{text:"后",glossary:"rangwang-hou"},"之为人也，"],["居于",{text:"畎亩",glossary:"rangwang-quanmu"},"之中，而",{text:"游尧之门",glossary:"rangwang-youyaozhimen"},"。"],[{text:"不若是而已",glossary:"rangwang-buruoshi"},"，又欲以其",{text:"辱行",glossary:"rangwang-ruxing"},{text:"漫我",glossary:"rangwang-manwo"},"，吾",{text:"羞见之",glossary:"rangwang-xiujianzhi"},"。」"],[{text:"因",glossary:"rangwang-yin-sequence"},{text:"自投",glossary:"rangwang-zitou"},{text:"清泠",glossary:"rangwang-qingling"},"之渊。"]]},{id:"rangwang-15",label:"卞随、瞀光拒位：所得来源与拒绝的生命代价",sentences:[[{text:"汤",glossary:"rangwang-tangjie"},"将伐",{text:"桀",glossary:"rangwang-tangjie"},"，",{text:"因卞随而谋",glossary:"rangwang-yinermou"},"，",{text:"卞随",glossary:"rangwang-biansui"},"曰：“",{text:"非吾事也",glossary:"rangwang-feiwushi"},"。”汤曰：“",{text:"孰可",glossary:"rangwang-shuke"},"？”曰：“吾不知也。”"],["汤又因",{text:"瞀光",glossary:"rangwang-maoguang"},"而谋，瞀光曰：“非吾事也。”汤曰：“孰可？”曰：“吾不知也。”汤曰：“伊尹何如？”曰：“",{text:"强力忍垢",glossary:"rangwang-qianglirengou"},"，吾不知其他也。”"],["汤遂与伊尹谋伐桀，",{text:"克之",glossary:"rangwang-kezhi"},"。以让卞随，卞随辞曰：“",{text:"后",glossary:"rangwang-hou"},"之伐桀也谋乎我，必以我为",{text:"贼",glossary:"rangwang-zei"},"也；胜桀而让我，必以我为",{text:"贪",glossary:"rangwang-tan"},"也。"],["吾生乎乱世，而无道之人",{text:"再来",glossary:"rangwang-zailai"},{text:"漫我",glossary:"rangwang-manwo"},"以其",{text:"辱行",glossary:"rangwang-ruxing"},"，吾不忍",{text:"数闻",glossary:"rangwang-shuowen"},"也！”乃",{text:"自投",glossary:"rangwang-zitou"},{text:"椆水",glossary:"rangwang-choushui"},"而死。"],["汤又让瞀光，曰：“",{text:"知者",glossary:"rangwang-zhizhe"},"谋之，武者",{text:"遂之",glossary:"rangwang-suizhi"},"，仁者",{text:"居之",glossary:"rangwang-juzhi"},"，古之道也。吾子胡不",{text:"立",glossary:"rangwang-li-enthrone"},"乎？”"],["瞀光辞曰：“",{text:"废上",glossary:"rangwang-feishang"},"，非义也；杀民，非仁也；人",{text:"犯其难",glossary:"rangwang-fanqinan"},"，我享其利，非",{text:"廉",glossary:"rangwang-lian"},"也。"],["吾闻之曰：‘",{text:"非其义者",glossary:"rangwang-feiqiyi"},"，不受其禄；无道之世，",{text:"不践其土",glossary:"rangwang-bujianqitu"},"。’况",{text:"尊我",glossary:"rangwang-zunwo"},"乎！吾不忍久见也。”乃负石而",{text:"自沈",glossary:"rangwang-zichen"},"于",{text:"庐水",glossary:"rangwang-lushui"},"。"]]},{id:"rangwang-16",label:"伯夷叔齐：观周、拒盟与首阳之节",sentences:[["昔",{text:"周之兴",glossary:"rangwang-zhouzhixing"},"，有士二人处于",{text:"孤竹",glossary:"rangwang-guzhu"},"，曰",{text:"伯夷",glossary:"rangwang-boyishuqi"},"、",{text:"叔齐",glossary:"rangwang-boyishuqi"},"。二人相谓曰：“吾闻西方有人，",{text:"似有道者",glossary:"rangwang-siyoudaozhe"},"，",{text:"试往观焉",glossary:"rangwang-shiwangguan"},"。”"],["至于",{text:"岐阳",glossary:"rangwang-qiyang"},"，武王闻之，使",{text:"叔旦",glossary:"rangwang-shudan"},"往见之。",{text:"与盟",glossary:"rangwang-yumeng"},"曰：“",{text:"加富二等",glossary:"rangwang-jiafu"},"，",{text:"就官一列",glossary:"rangwang-jiuguan"},"。”",{text:"血牲而埋之",glossary:"rangwang-xuesheng"},"。"],["二人相视而笑，曰：“嘻，异哉！此非吾所谓道也。昔者",{text:"神农",glossary:"rangwang-shennong"},"之有天下也，",{text:"时祀",glossary:"rangwang-shisi"},"尽敬而",{text:"不祈喜",glossary:"rangwang-buqixi"},"；其于人也，",{text:"忠信尽治",glossary:"rangwang-zhongxinjinzhi"},"而无求焉。"],[{text:"乐与政为政，乐与治为治",glossary:"rangwang-leyuzheng"},"。不以人之坏自成也，不以人之卑自高也，不以",{text:"遭时",glossary:"rangwang-zaoshi"},"自利也。"],["今周见殷之乱而",{text:"遽",glossary:"rangwang-ju"},"为政，上谋而下",{text:"行货",glossary:"rangwang-xinghuo"},"，",{text:"阻兵",glossary:"rangwang-zubing"},"而保威，割牲而盟以为信，",{text:"扬行",glossary:"rangwang-yangxing-display"},"以",{text:"说众",glossary:"rangwang-yuezhong"},"，杀伐以",{text:"要利",glossary:"rangwang-yaoli"},"。是",{text:"推乱以易暴",glossary:"rangwang-tuiluanyibao"},"也。"],["吾闻古之士，遭治世不避其任，遇乱世",{text:"不为苟存",glossary:"rangwang-buweigoucun"},"。今天下",{text:"闇",glossary:"rangwang-an"},"，周德衰，其",{text:"并乎周",glossary:"rangwang-binghuzhou"},"以",{text:"涂吾身",glossary:"rangwang-tuwushen"},"也，不如避之，以",{text:"洁吾行",glossary:"rangwang-jiewuxing"},"。”"],["二子北至于",{text:"首阳之山",glossary:"rangwang-shouyang"},"，遂饿而死焉。"],["若伯夷、叔齐者，其于富贵也，",{text:"苟可得已",glossary:"rangwang-goukedeyi"},"，则必",{text:"不赖高节戾行",glossary:"rangwang-bulaigaojie"},"，独乐其志，不事于世。此二士之节也。"]]}],b=[{id:"rangwang-guide-01-01",text:"尧以天下让许由，许由不受。",guide:"先写辞让的动作，不在这里展开许由的完整理由。天下被郑重给予，也不意味着受让者必须接受。",note:"《逍遥游》的许由故事可作对读，但不能把那里的解释全部当作本段明说。"},{id:"rangwang-guide-01-02",text:"方且治之，未暇治天下也。",guide:"子州二人的回答将注意力从君位的荣耀转向承担者的实际处境：眼下有病苦，需要先治疗。",note:"不直接诊断其疾病，也不无据断言是假托病名。"},{id:"rangwang-guide-01-03",text:"夫天下至重也，而不以害其生，又况他物乎！",guide:"先承认天下极重，再说明它不能自动成为伤生的理由。关键不是贬低天下，而是检验取得、承担它的代价。",note:"不等于天下毫无价值，也不等于所有公共事务都应拒绝。"},{id:"rangwang-guide-01-04",text:"唯无以天下为者可以托天下也。",guide:"不把天下当作自身欲求的人，反而被认为值得托付；可联系不以公共事务满足私欲来理解。",note:"不争求不是现实治理能力的充分条件，更不能被变成争取权位的表演策略。"},{id:"rangwang-guide-01-05",text:"逍遥于天地之间，而心意自得。",guide:"善卷的自在与耕种、收获、休息相连。他并不认为必须取得天下，自己的生活才算成立。",note:"逍遥不是不劳动，也不是要求所有人复制同一种隐居生活。"},{id:"rangwang-guide-01-06",text:"吾何以天下为哉！悲夫，子之不知余也。",guide:"给予者认为最贵重的东西，未必是受让者所需。了解他人，还包括了解其生活、满足与意愿。",note:"这里批评的是“不知余”，不能据此断言舜必定虚伪或怀有恶意。"},{id:"rangwang-guide-01-07",text:"以舜之德为未至也。",guide:"石户之农不把舜的勤勤用力直接等同于至德，因而携家远避。",note:"不是否定一切努力；“入于海”也不能仅凭字面认作投海。"},{id:"rangwang-guide-02-01",text:"狄人之所求者土地也。",guide:"接连馈赠无效，叙事明确了冲突的对象，随后才转向土地与生命的比较。",note:"原文没有提供完整军事条件，不能据此制定普遍退让策略。"},{id:"rangwang-guide-02-02",text:"与人之兄居而杀其弟，与人之父居而杀其子，吾不忍也。",guide:"战争代价落到具体的家庭关系中。太王所关切的生命包括民众，而不只是自己。",note:"结合上下文理解，不必认作太王已经亲手杀死这些人。"},{id:"rangwang-guide-02-03",text:"不以所用养害所养。",guide:"土地等条件原本用来供养生命，不能为了保住条件，反而毁伤其所服务的人。",note:"这是用途与目的的辨析，不是说土地毫无价值。"},{id:"rangwang-guide-02-04",text:"民相连而从之。遂成国于岐山之下。",guide:"放下原有土地后，民众跟随并重新成国，故事并未止于个人远走。",note:"不能把这一结果当作所有退让必获成功的规律。"},{id:"rangwang-guide-02-05",text:"虽贵富不以养伤身，虽贫贱不以利累形。",guide:"富贵者可能被已有之物牵累，贫贱者也可能被未得之利牵累；两种处境都需要辨认伤生的代价。",note:"不是否定一切谋生劳动或物质需要。"},{id:"rangwang-guide-03-01",text:"越人三世弑其君，王子搜患之。",guide:"王子搜的逃避有具体的危险背景，不是泛泛厌世或无理由地拒绝君位。"},{id:"rangwang-guide-03-02",text:"王子搜不肯出，越人熏之以艾。",guide:"迎立越过了明确拒绝。“被需要”在这里也表现为强迫。",note:"结尾对其适任的肯定，不能抹去过程中的不愿与被迫。"},{id:"rangwang-guide-03-03",text:"王子搜非恶为君也，恶为君之患也。",guide:"区分职位本身与具体处境中的承担代价，不以君位贵重便忽略伤生的危险。",note:"不能概括为所有君位都应拒绝，或有道者必定厌恶领导。"},{id:"rangwang-guide-03-04",text:"此固越人之所欲得为君也。",guide:"不轻生、不急于取得君位的人，反而被认为值得托付。",note:"原文没有证明其完整治理能力，也不能用适任评价取消其拒绝。"},{id:"rangwang-guide-04-01",text:"左手攫之则右手废，右手攫之则左手废。然而攫之者必有天下。",guide:"以极端假设使代价显现：即使能够得到天下，君主是否愿意付出手臂残废的损失？",note:"这是论证情境，不是描述真实交易。"},{id:"rangwang-guide-04-02",text:"两臂重于天下也。身亦重于两臂。",guide:"子华子从君主已承认的选择出发，再把身体整体与两臂、天下作比较。",note:"应留意“自是观之”，这是从眼前选择推出的轻重关系。"},{id:"rangwang-guide-04-03",text:"今之所争者，其轻于韩又远。",guide:"所争土地远小于天下，君主却正在为它忧愁伤生，与先前不肯以臂换天下的判断形成反差。"},{id:"rangwang-guide-04-04",text:"子华子可谓知轻重矣！",guide:"知轻重不只是少求一点，还要同时看清所得与所失，并将口头认可的尺度落实到实际用心中。",note:"这段不能单独解决公共责任、他人安全与个人生命之间的所有冲突。"},{id:"rangwang-guide-05-01",text:"使人以币先焉。",guide:"礼物是延请的先导，既带来资源与认可，也可能将受礼者引入新的身份与事务。",note:"原文未细列后续责任，不补成确定的政治契约，也不先断言鲁君怀有恶意。"},{id:"rangwang-guide-05-02",text:"颜阖守陋闾，苴布之衣，而自饭牛。",guide:"先写已有的简朴生活，再写外来的富贵机会。是否接受，不能只按资源多少判断。",note:"不是赞美贫困本身，也不是证明他没有任何生活困难。"},{id:"rangwang-guide-05-03",text:"恐听谬而遗使者罪，不若审之。",guide:"颜阖承认身份，却请使者核实送礼之事，使当场受聘的进程中断。",note:"不强定其全部心理，既不断言完全出于关怀，也不断言纯属虚伪。"},{id:"rangwang-guide-05-04",text:"故若颜阖者，真恶富贵也。",guide:"叙述者以实际离去说明他的拒绝，不只是等待更高礼遇的口头辞让。",note:"不能推广为凡受聘者都无道，或所有拒绝都应以离去完成。"},{id:"rangwang-guide-06-01",text:"道之真以治身，其绪余以为国家，其土苴以治天下。",guide:"原文鲜明地把治身置于根本位置，把治理国家、天下置于余用位置。",note:"不能淡化为三者同等重要，也不能解释成依次毕业的三阶段课程。"},{id:"rangwang-guide-06-02",text:"帝王之功，圣人之余事也，非所以完身养生也。",guide:"外在功业不能自动保证自身得到保全与养护。",note:"余事不等于绝对无用，但功业也不能被当作生命安顿的根本保证。"},{id:"rangwang-guide-06-03",text:"多危身弃生以殉物。",guide:"批评外物由服务生命的条件，变成要求生命为之牺牲的对象。",note:"批评的是轻重倒置，不是要求停止所有行动。"},{id:"rangwang-guide-06-04",text:"必察其所以之与其所以为。",guide:"行动需要检验趋向、缘由与凭借；下文进一步落实为拿什么去求什么。",note:"相关训释存在差异，不强定为唯一现代术语。"},{id:"rangwang-guide-06-05",text:"所用者重而所要者轻也。",guide:"以宝珠弹雀，使所付远重于所得的失衡显现。",note:"不是说雀毫无价值，也不是全面鄙视小事。"},{id:"rangwang-guide-06-06",text:"夫生者岂特随侯之重哉！",guide:"世人看得见宝珠贵重，却可能轻忽更重的生命，反问揭露这种判断失效。",note:"不是证明一切价值都能以同一单位精确计算。"},{id:"rangwang-guide-07-01",text:"居君之国而穷，君无乃为不好士乎？",guide:"客人把列子的贫困转成子阳是否礼士的声誉问题，推动赠粮发生。",note:"不能仅凭这一点断言子阳绝无善意。"},{id:"rangwang-guide-07-02",text:"子列子见使者，再拜而辞。",guide:"列子先致敬，再明确辞谢，拒绝并未表现为侮辱使者或鄙视粮食。"},{id:"rangwang-guide-07-03",text:"其妻望之而拊心。",guide:"妻子的痛惜使饥饿与拒绝的真实代价进入故事，粮食确实能够缓解困苦。",note:"不把她简化为贪图钱粮的反面角色。"},{id:"rangwang-guide-07-04",text:"以人之言而遗我粟；至其罪我也，又且以人之言。",guide:"列子检验的是奖惩依赖的判断方式：未经实际了解的传言，既可能带来恩惠，也可能带来危险。",note:"不等于所有推荐都不可信，也不是确定的未来预言。"},{id:"rangwang-guide-07-05",text:"其卒，民果作难而杀子阳。",guide:"结尾带有印证风险顾虑的叙事意味，但实际写的是子阳遭变乱被杀。",note:"没有写子阳后来处罚列子，也没有证明列子受粟便必遭灾难。"},{id:"rangwang-guide-08-01",text:"臣之爵禄已复矣，又何赏之有。",guide:"屠羊说把恢复原业视为自身生活的恢复，不以更高爵禄为必需。",note:"不能据此说战争造成的所有损失都已消除。"},{id:"rangwang-guide-08-02",text:"非臣之罪……非臣之功。",guide:"不承担不属于自己的罪，也不认领不属于自己的功，拒赏建立在事实辨认上。",note:"这是复国论功行赏的语境，不是所有赠予都必须以功劳为条件。"},{id:"rangwang-guide-08-03",text:"说畏难而避寇，非故随大王也。",guide:"屠羊说不把自己的避难行动事后美化为特意从王的功业。",note:"不能扩大为所有兼有避难动机的随从都毫无贡献。"},{id:"rangwang-guide-08-04",text:"今大王欲废法毁约而见说。",guide:"即使破例有利于自己，也不应省略对资格、法度与约定的检验。",note:"故事中的法度陈述不直接等于已经核实的完整楚国制度史。"},{id:"rangwang-guide-08-05",text:"居处卑贱而陈义甚高。",guide:"君主看见身份之外的价值，随后改以高位延请，理由由赏随从转向认可其义理。",note:"原文未充分讨论新任用理由是否合宜，不能假定所有制度问题都已解决。"},{id:"rangwang-guide-08-06",text:"吾知其贵……吾知其富。",guide:"屠羊说承认高位厚禄的价值，却不因此认为自己应当接受。",note:"他的拒绝不是不知道富贵好处，也不是一概厌恶所有富贵。"},{id:"rangwang-guide-08-07",text:"岂可以贪爵禄而使吾君有妄施之名乎？",guide:"不仅考虑自己所得，也考虑施予是否有根据，以及由此造成的君名。",note:"妄施是屠羊说在故事中的判断，不据此裁定所有特别延请。"},{id:"rangwang-guide-08-08",text:"愿复反吾屠羊之肆。遂不受也。",guide:"赏赐、召见、高位厚禄逐次加重，他仍把辞受判断落实为不受。",note:"不解释成争取更高奖励的策略，也不无据断言其内心已经毫无欲求。"},{id:"rangwang-guide-09-01",text:"上漏下湿，匡坐而弦歌。",guide:"原宪的居处破漏与弦歌并置，困窘真实，却未成为其全部生活的定义。",note:"不把贫困本身当作德性的原因。"},{id:"rangwang-guide-09-02",text:"无财谓之贫，学而不能行谓之病。",guide:"将财物缺乏与不能实践所学分开，改正以外在困窘概括内在失败的分类。",note:"“非病”不等于身体完全健康，也不取消贫困的身体代价。"},{id:"rangwang-guide-09-03",text:"希世而行，比周而友，学以为人，教以为己。",guide:"反省行事、交友、学习与教学被迎合和私利主导的偏转。",note:"并非否定这些活动本身，也不要求所有教学无偿。"},{id:"rangwang-guide-09-04",text:"仁义之慝，舆马之饰，宪不忍为也。",guide:"仁义名号与外在排场不能自动证明行为正当。",note:"不能据此逐项裁定子贡确实犯了所列全部过错。"},{id:"rangwang-guide-10-01",text:"三日不举火，十年不制衣。",guide:"集中写出严重的衣食困窘，后面的歌声不能抹去这些需要。",note:"数字具有叙事强化作用，不当作已经核验的生活统计。"},{id:"rangwang-guide-10-02",text:"声满天地，若出金石。",guide:"衣履破损与声音铿锵形成反差，表现困苦未能完全支配其志。",note:"弦歌不是现实中替代食物与照料的方法。"},{id:"rangwang-guide-10-03",text:"天子不得臣，诸侯不得友。",guide:"权位不能自动取得他的臣属、交往与认同。",note:"不补造具体聘请史实，也不解释成拒绝所有友谊。"},{id:"rangwang-guide-10-04",text:"养志者忘形，养形者忘利，致道者忘心矣。",guide:"分别指出志、形与道的不同侧重，以及需要松开的执着。",note:"忘形不等于精心保养身体，也不等于故意伤身；忘心不等于停止思考。"},{id:"rangwang-guide-11-01",text:"足以给𫗞粥……足以为丝麻。",guide:"颜回的自得包含衣食供给的物质基础，不是完全无资源而凭精神生活。",note:"古代亩制不同，不按现代市亩直接换算。"},{id:"rangwang-guide-11-02",text:"鼓琴足以自娱；所学夫子之道者足以自乐也。",guide:"衣食之外，琴与所学支持其生活之乐，使出仕并非补足生活的唯一途径。",note:"不推导为所有出仕者都不知足。"},{id:"rangwang-guide-11-03",text:"知足者，不以利自累也；审自得者，失之而不惧；行修于内者，无位而不怍。",guide:"分别从欲求尺度、内在把握与行为修养说明不受利位完全支配。",note:"不将其变成对所有受苦者立即做到的要求。"},{id:"rangwang-guide-11-04",text:"丘诵之久矣，今于回而后见之。",guide:"熟记道理与看见实践不是同一件事，学生的生活也能使老师获得领会。"},{id:"rangwang-guide-12-01",text:"身在江海之上，心居乎魏阙之下。",guide:"外在退隐与内在放下没有同步发生，改变位置不自动改变欲求。"},{id:"rangwang-guide-12-02",text:"重生。重生则利轻。",guide:"重新安排生命与利禄的分量，而不只是命令自己停止想要。",note:"利轻不必等于彻底消除所有利益需求。"},{id:"rangwang-guide-12-03",text:"虽知之，未能自胜也。",guide:"知道轻重尚未转化为真实的内在状态，不能只用一句道理代替调整。"},{id:"rangwang-guide-12-04",text:"不能自胜而强不从者，此之谓重伤。",guide:"欲求未解，又强行逆拒，可能再添一层心神损伤。",note:"不是所有约束都应取消，也不是难以克服的欲望都应实行。"},{id:"rangwang-guide-12-05",text:"虽未至乎道，可谓有其意矣！",guide:"原文既保留未达到的判断，也承认其退隐与求问已有向道意向。",note:"不因出身贵重便判境界更高，也不以有意代替继续改变。"},{id:"rangwang-guide-13-01",text:"颜色甚惫，而弦歌于室。",guide:"饥饿与疲惫真实存在，弦歌并不取消身体困苦。"},{id:"rangwang-guide-13-02",text:"君子之无耻也若此乎？",guide:"弟子把外在受挫后的弦歌理解为不知羞愧，故事随后检验这种评价。",note:"这是此时的判断局限，不是二人永远没有理解能力。"},{id:"rangwang-guide-13-03",text:"君子通于道之谓通，穷于道之谓穷。",guide:"区分外在遭遇与于道失守，前者不能单独裁定后者。",note:"不是外在条件毫无意义，也不是自称有道便免于批评。"},{id:"rangwang-guide-13-04",text:"内省而不穷于道，临难而不失其德。",guide:"坚持与自我检验并行，并非不论事实都宣告自己正确。"},{id:"rangwang-guide-13-05",text:"天寒既至，霜雪既降，吾是以知松柏之茂也。",guide:"困境使所守显现，可以在已经发生的困难中重新领会价值。",note:"不推出应主动制造饥饿、危险来证明德性。"},{id:"rangwang-guide-13-06",text:"穷亦乐，通亦乐，所乐非穷通也。",guide:"快乐的根源不在贫困或显达本身，而在不完全依外境维持的体道。",note:"不是越穷越快乐，也不应用来责备受苦者的悲伤。"},{id:"rangwang-guide-13-07",text:"则穷通为寒暑风雨之序矣。",guide:"境遇仍有变化，却不再独占一个人的内在评价。",note:"比喻不取消战争等境遇的人为原因与责任。"},{id:"rangwang-guide-14-01",text:"居于畎亩之中，而游尧之门。",guide:"北人无择质疑舜由农耕生活进入政治中心的道路，而非先说明自身承担能力。",note:"不据此证明舜一开始就蓄谋夺取天下，也不当作全书对舜的唯一评价。"},{id:"rangwang-guide-14-02",text:"又欲以其辱行漫我。",guide:"授位在他看来不是荣耀，而是使自己卷入不认可的行为与关系。",note:"这是人物对邀请的理解，应与授位者的实际动机分开。"},{id:"rangwang-guide-14-03",text:"因自投清泠之渊。",guide:"拒绝走向明确投水，与远避后仍保留生活的故事不同。",note:"保全操守的引申不能代替实际生命损失，结局也不自动证明这是最高境界。"},{id:"rangwang-guide-15-01",text:"非吾事也。",guide:"卞随、瞀光先退出伐桀谋议，也没有主动推荐参与者。",note:"“吾不知”不等于对所有世事完全无知。"},{id:"rangwang-guide-15-02",text:"强力忍垢，吾不知其他也。",guide:"瞀光只说明有限认识，不愿对伊尹作全面评价。",note:"不直接当作热情推荐，也不据此审判伊尹全部人格。"},{id:"rangwang-guide-15-03",text:"必以我为贼也；必以我为贪也。",guide:"卞随拒绝被邀请定义为自己不愿成为的参与攻杀者或贪求天下者。",note:"“必以我为”是他的推断，不是已经证实的汤之内心判断。"},{id:"rangwang-guide-15-04",text:"知者谋之，武者遂之，仁者居之，古之道也。",guide:"汤以谋划、完成与治理的分工，说明未参与征伐者也可以接受君位。",note:"“古之道”是对话中的主张，不使瞀光必须接受。"},{id:"rangwang-guide-15-05",text:"废上，非义也；杀民，非仁也；人犯其难，我享其利，非廉也。",guide:"瞀光分别从义、仁、廉检验征伐及其受利关系，不以成功自动证明正当。",note:"不扩大为所有更替、战争与分工受益的统一判决。"},{id:"rangwang-guide-15-06",text:"非其义者，不受其禄；无道之世，不践其土。",guide:"拒绝由不受禄利扩展到不愿置身其中，进一步追问所得来源。"},{id:"rangwang-guide-15-07",text:"自投椆水而死……自沈于庐水。",guide:"两人的拒绝都走向死亡，与前文不以天下易生形成张力。",note:"不能用“全生”抹去死亡，也不能仅凭结局定为全然赞扬或讽刺。"},{id:"rangwang-guide-16-01",text:"似有道者，试往观焉。",guide:"伯夷叔齐起初带着期待前往观察，不只凭传闻确认，也不预先否定一切政治参与。"},{id:"rangwang-guide-16-02",text:"加富二等，就官一列。",guide:"待遇、官位与盟誓共同构成政治安排，但没有自动回答其是否有道。",note:"不认定所有官位、礼遇与盟约都不当。"},{id:"rangwang-guide-16-03",text:"忠信尽治而无求焉。",guide:"以尽责而不索求回报的神农之治作为理想参照。",note:"有道不是不行动，理想参照也不直接当作已核验的制度史。"},{id:"rangwang-guide-16-04",text:"不以人之坏自成也，不以人之卑自高也，不以遭时自利也。",guide:"不把他人的毁败、低下与时势机会变成自我成就和私利的资本。",note:"不因此否定危机中的救助、修复与任事。"},{id:"rangwang-guide-16-05",text:"割牲而盟以为信。",guide:"前面的盟誓成为被检验的对象，仪式上的保证不能代替实际可信。"},{id:"rangwang-guide-16-06",text:"遭治世不避其任，遇乱世不为苟存。",guide:"任事与退出都有条件，不以退隐为唯一理想，也不以生存为唯一尺度。",note:"不能推广为所有人都应放弃求生与求助。"},{id:"rangwang-guide-16-07",text:"遂饿而死焉。",guide:"原文写离去后最终饿死，生命未得保全。",note:"不倒推为预先以死亡为目标，也不补入“不食周粟”等未在此明写的情节。"},{id:"rangwang-guide-16-08",text:"独乐其志……此二士之节也。",guide:"结尾具有肯定操守的语气，可联系不以辞富贵经营声名理解。",note:"肯定其节不自动等于肯定死亡本身，更不要求所有人复制结局。"}];function o(p){return w.filter(a=>a.id===`rangwang-${p}`)}function l(p){return b.filter(a=>a.id.startsWith(`rangwang-guide-${p}-`))}function s(p){const a=new Set;for(const y of o(p))for(const g of y.sentences)for(const r of g)typeof r!="string"&&r.glossary&&a.add(r.glossary);return d.filter(y=>a.has(y.id)&&Array.from(y.term).length<=5)}const x=o("01"),q=s("01"),c=l("01"),k=o("02"),f=s("02"),z=l("02"),P=o("03"),j=s("03"),_=l("03"),T=o("04"),S=s("04"),A=l("04"),C=o("05"),V=s("05"),I=l("05"),D=o("06"),N=s("06"),R=l("06"),G=o("07"),E=s("07"),K=l("07"),v=o("08"),O=s("08"),B=l("08"),L=o("09"),$=s("09"),J=l("09"),U=o("10"),W=s("10"),F=l("10"),H=o("11"),M=s("11"),Q=l("11"),X=o("12"),Y=s("12"),Z=l("12"),aa=o("13"),na=s("13"),ta=l("13"),ia=o("14"),ea=s("14"),ra=l("14"),ga=o("15"),da=s("15"),oa=l("15"),la=o("16"),sa=s("16"),ha=l("16");return(p,a)=>{const y=m("DaoReadingPrelude"),g=m("DaoTextReading"),r=m("DaoKeywordCards"),h=m("DaoLineGuide");return pa(),ya("div",null,[a[0]||(a[0]=n("h1",{id:"庄子·让王",tabindex:"-1"},[e("庄子·让王 "),n("a",{class:"header-anchor",href:"#庄子·让王","aria-label":'Permalink to "庄子·让王"'},"​")],-1)),t(y,{title:"先读十六段：天下、土地与生命的分量",summary:"《让王》从辞让天下展开，把权位的贵重与承担者的生命处境放在一起考察；其后各段依次考察聘请、施予、辞受、贫居、困穷与拒辱，末以伯夷叔齐守节作结。",points:[{label:"所求",text:"天下、君位、土地，究竟被看重在哪里？"},{label:"所养",text:"这些外物原本服务于谁的生命与生活？"},{label:"代价",text:"接受、争守或维持它们，会损伤什么，又由谁承担？"}],hint:"阅读这些故事，不宜先将「不受」统一解释为怯懦、清高或某种固定的修行等级，而应分别辨认：人物面对什么，为什么拒绝，又以怎样的方式回应。"}),a[1]||(a[1]=n("h2",{id:"一、辞让天下·不以权位伤生",tabindex:"-1"},[e("一、辞让天下·不以权位伤生 "),n("a",{class:"header-anchor",href:"#一、辞让天下·不以权位伤生","aria-label":'Permalink to "一、辞让天下·不以权位伤生"'},"​")],-1)),a[2]||(a[2]=n("h3",{id:"原文",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),t(g,{sections:i(x),glossary:d,"default-mode":"classic","aria-label":"让王·first 原文"},null,8,["sections"]),a[3]||(a[3]=n("blockquote",null,[n("p",null,[n("strong",null,"文字说明")]),n("p",null,"保留所供文本中的“子州支父”“子州之父”“子州之伯”等写法。常见文本另有“子州支伯”等称名；这里不擅自统一，也不将“之父”直接解释为“他的父亲”。"),n("p",null,"本段包含多则故事，但原文仍作为一个完整单元呈现，以下分层仅用于解读。")],-1)),a[4]||(a[4]=n("h3",{id:"字词释义",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(q)},null,8,["items"]),a[5]||(a[5]=n("h3",{id:"逐句导读",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(c)},null,8,["lines"]),a[6]||(a[6]=u('<h3 id="深入解读" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、许由不受-先给动作-不重述全部理由" tabindex="-1">一、许由不受：先给动作，不重述全部理由 <a class="header-anchor" href="#一、许由不受-先给动作-不重述全部理由" aria-label="Permalink to &quot;一、许由不受：先给动作，不重述全部理由&quot;">​</a></h4><blockquote><p>尧以天下让许由，许由不受。</p></blockquote><p>开篇极为简短，只说明尧让天下、许由不受，没有在这里展开许由的完整理由。</p><p>《逍遥游》的许由故事可以帮助比较，但不能把那里的每一句解释都当作本段已经说出的内容。</p><p>这里首先打破一个预设：**天下被郑重给予，也不意味着受让者必须接受。**随后的故事，才逐渐展开不同的拒绝理由。</p><h4 id="二、子州二人-先辨认眼下应当照料什么" tabindex="-1">二、子州二人：先辨认眼下应当照料什么 <a class="header-anchor" href="#二、子州二人-先辨认眼下应当照料什么" aria-label="Permalink to &quot;二、子州二人：先辨认眼下应当照料什么&quot;">​</a></h4><blockquote><p>以我为天子，犹之可也。虽然，我适有幽忧之病，方且治之，未暇治天下也。</p></blockquote><p>子州支父并未首先否认自己有资格。他的回答有一个转折：做天子尚可，但眼下有病，要先治疗，因此没有余力治理天下。</p><p>问题由身份与荣耀，移向具体处境：</p><p><strong>一件事再重要，也需要由具体的人承担；事务的重要，不能使承担者的病苦与生命需要消失。</strong></p><p>子州之伯对舜的回答与此相近，主要强化同一种轻重关系，不必被解释成新的修炼等级。</p><p>原文没有交代病情、治疗方法或最终结果。“幽忧之病”不宜直接诊断为现代某种疾病，也不能因为它被用作拒绝理由，就断言是假托。</p><h4 id="三、天下至重-而不以害生-承认贵重-仍检验代价" tabindex="-1">三、天下至重，而不以害生：承认贵重，仍检验代价 <a class="header-anchor" href="#三、天下至重-而不以害生-承认贵重-仍检验代价" aria-label="Permalink to &quot;三、天下至重，而不以害生：承认贵重，仍检验代价&quot;">​</a></h4><blockquote><p>夫天下至重也，而不以害其生，又况他物乎！<br> 故天下大器也，而不以易生。</p></blockquote><p>叙述者不是先说天下毫无价值，而是承认它“至重”“大器”，再说明不能因此损害生命，或拿生命与之交换。</p><p>这一区别很重要：<strong>不是因为天下不值一提才拒绝，而是即使它极为贵重，也仍须检验承担它的代价。</strong></p><p>“此有道者之所以异乎俗者也”则指出尺度的不同。常见趋向容易先看权位的贵重，有道者还会看见承担者的处境、生命的损伤，以及所得与所失是否倒置。</p><p>这不是要求所有人拒绝公共事务，而是说权位不能自动压倒对生命处境的判断。</p><h4 id="四、无以天下为者-可以托天下-不争求与可托付的反差" tabindex="-1">四、无以天下为者，可以托天下：不争求与可托付的反差 <a class="header-anchor" href="#四、无以天下为者-可以托天下-不争求与可托付的反差" aria-label="Permalink to &quot;四、无以天下为者，可以托天下：不争求与可托付的反差&quot;">​</a></h4><blockquote><p>唯无以天下为者可以托天下也。</p></blockquote><p>前面写拒绝天下，这里却说不以天下为所求的人可以托付天下。</p><p>一种合理理解是：不急于从天下取得荣耀、利益与自我证明的人，较不容易把所托付的事务变成私人欲望的工具。</p><p>但这不是现实中的充分条件。声称不想掌权，不等于必定有能力、了解条件或适合承担。</p><p>本句突出不争求的价值，不是在提供完整的选任程序；更不能把“不想要”变成争取权位的表演策略。</p><h4 id="五、善卷-自得不是没有劳动-而是不需权位补足生活" tabindex="-1">五、善卷：自得不是没有劳动，而是不需权位补足生活 <a class="header-anchor" href="#五、善卷-自得不是没有劳动-而是不需权位补足生活" aria-label="Permalink to &quot;五、善卷：自得不是没有劳动，而是不需权位补足生活&quot;">​</a></h4><p>善卷没有以疾病作答，而是描述自己的生活：</p><ul><li>冬衣皮毛，夏衣葛絺；</li><li>春耕种，秋收敛；</li><li>日出而作，日入而息。</li></ul><p>衣着随季节，耕收随时令，劳动与休息随日夜展开。他的自得并非完全脱离劳动，而是所需与所得、劳作与休息之间有所相应。</p><p>原文没有说这种生活毫无艰难，也没有提供完整的物质条件记录。但它明确表现：<strong>善卷不认为必须取得天下，自己的生活才能成立。</strong></p><p>因而，“逍遥”不能径释为不做任何事情，也不能变成人人必须务农、住深山或采用同一生活需求的固定模板。</p><p>重要的不是复制他的衣食形式，而是理解他为何不需要以天下补足自身。</p><h4 id="六、子之不知余-贵重的给予-不等于适合对方" tabindex="-1">六、子之不知余：贵重的给予，不等于适合对方 <a class="header-anchor" href="#六、子之不知余-贵重的给予-不等于适合对方" aria-label="Permalink to &quot;六、子之不知余：贵重的给予，不等于适合对方&quot;">​</a></h4><blockquote><p>吾何以天下为哉！悲夫，子之不知余也。</p></blockquote><p>对舜而言，让天下可能是极郑重的认可；对善卷而言，却不是自己所需要的东西。</p><p>“知余”不只是知道此人有名、有德，还涉及了解他怎样生活、满足于什么，以及是否愿意承担这份安排。</p><p>由此可以引出一个关系提醒：<strong>承认一个人的价值，不必等于把他放进自己认为最好的位置。</strong></p><p>这是引申解读。原文批评的是“不知余”，不能据此断言舜必定虚伪，或让位必有恶意。</p><p>善卷随后入深山、使人不知其处，将拒绝落实为远避。这个动作强化了他不愿继续被寻找、被安排的态度，但不意味着所有拒绝都必须以隐居告终。</p><h4 id="七、石户之农-不把勤勤用力直接等同于至德" tabindex="-1">七、石户之农：不把勤勤用力直接等同于至德 <a class="header-anchor" href="#七、石户之农-不把勤勤用力直接等同于至德" aria-label="Permalink to &quot;七、石户之农：不把勤勤用力直接等同于至德&quot;">​</a></h4><blockquote><p>捲捲乎，后之为人，葆力之士也。<br> 以舜之德为未至也。</p></blockquote><p>石户之农既不先说自身有病，也不先陈述生活自足，而是直接评价舜之德尚未达到自己认可的境地。</p><p>“捲捲”“葆力”训释存在差异，结合叙述者说明，可以把握其批评方向：舜仍显得勤勤用力，不能仅凭这种经营状态就认作至德。</p><p>这不是说勤勉必定错误、所有治理都无意义，或能力与努力一概不值得尊重。它质疑的是：<strong>不断用力经营，是否就已经是最高的德性状态。</strong></p><p>石户之农携家“入于海”，通常联系远入海滨或海上隐居理解。不能只凭一个“海”字，便解释为一家投海自尽。</p><p>原文没有使用明确写自杀的动作。远避与毁身必须分清，不能因都表现拒绝便混为一谈。</p><h3 id="思想参照" tabindex="-1">思想参照 <a class="header-anchor" href="#思想参照" aria-label="Permalink to &quot;思想参照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>本段内容</th><th>可参照篇章</th><th>联系与区别</th></tr></thead><tbody><tr><td>尧让天下，许由不受</td><td>《逍遥游》</td><td>同一题材可对读；本段未重述许由的详细理由</td></tr><tr><td>天下虽重，不以害生</td><td>《外物》</td><td>可比较外在所求与伤生的关系，不等于否定一切外物</td></tr><tr><td>善卷自得于日常</td><td>本篇颜回不仕的故事</td><td>都由自身所需与自得说明不求权位，生活形式不同</td></tr><tr><td>子之不知余</td><td>《寓言》</td><td>可比较既有尺度与理解他人的困难，不强定为同义</td></tr><tr><td>石户之农批评用力经营</td><td>《寓言》勤志服知与谢之</td><td>可比较经营与自然的张力，仍须分别理解语境</td></tr><tr><td>辞让与远避</td><td>《外物》有关辞让、毁身的故事</td><td>题材相似，评价与后果不同，不应直接套用</td></tr></tbody></table><h2 id="二、太王迁岐·不以所用养害所养" tabindex="-1">二、太王迁岐·不以所用养害所养 <a class="header-anchor" href="#二、太王迁岐·不以所用养害所养" aria-label="Permalink to &quot;二、太王迁岐·不以所用养害所养&quot;">​</a></h2><h3 id="原文-1" tabindex="-1">原文 <a class="header-anchor" href="#原文-1" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',50)),t(g,{sections:i(k),glossary:d,"default-mode":"classic","aria-label":"让王·second 原文"},null,8,["sections"]),a[7]||(a[7]=n("blockquote",null,[n("p",null,[n("strong",null,"文字说明")]),n("p",null,"“大王囗父”中的“囗”为所供文本的缺字，应结合前文“亶父”理解；这里保留原文，不默改。"),n("p",null,"“生䇲”涉及字形与训释，以下采用常见解释帮助理解，不擅自替换字形。")],-1)),a[8]||(a[8]=n("h3",{id:"字词释义-1",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-1","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(f)},null,8,["items"]),a[9]||(a[9]=n("h3",{id:"逐句导读-1",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-1","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(z)},null,8,["lines"]),a[10]||(a[10]=u('<h3 id="深入解读-1" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-1" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、馈赠无效-先辨认争夺的对象" tabindex="-1">一、馈赠无效：先辨认争夺的对象 <a class="header-anchor" href="#一、馈赠无效-先辨认争夺的对象" aria-label="Permalink to &quot;一、馈赠无效：先辨认争夺的对象&quot;">​</a></h4><p>太王先后以皮帛、犬马、珠玉馈赠，对方都不接受，因为所求的是土地。</p><p>叙事先说明：不断增加馈赠，并没有解决实际冲突。太王是在几次尝试无效、明确争夺对象之后，作出离去的选择。</p><p>但原文没有提供双方力量、战争条件等完整信息。故事重点是土地与生命的轻重，不能据此证明任何冲突都应立即退让。</p><h4 id="二、吾不忍-尊生也关乎民众" tabindex="-1">二、吾不忍：尊生也关乎民众 <a class="header-anchor" href="#二、吾不忍-尊生也关乎民众" aria-label="Permalink to &quot;二、吾不忍：尊生也关乎民众&quot;">​</a></h4><blockquote><p>与人之兄居而杀其弟，与人之父居而杀其子，吾不忍也。</p></blockquote><p>太王想到的是具体的人伦关系：活着的兄长与失去的弟弟，活着的父亲与失去的儿子。</p><p>争守土地的代价不只是抽象数字，而会落到家庭与人与人的关系之中。</p><p>因而，此处尊生不能缩成太王只想保护自己。他明确说“不忍”，关切别人因争战而失去亲人。</p><p>结合上下文，这些句子更适合联系争战造成的死亡理解，不必认作太王亲手杀人。</p><h4 id="三、奚以异-不以自己的统治身份压倒生存" tabindex="-1">三、奚以异：不以自己的统治身份压倒生存 <a class="header-anchor" href="#三、奚以异-不以自己的统治身份压倒生存" aria-label="Permalink to &quot;三、奚以异：不以自己的统治身份压倒生存&quot;">​</a></h4><blockquote><p>子皆勉居矣！为吾臣与为狄人臣奚以异。</p></blockquote><p>太王让众人继续安居，并暂时放轻臣属于自己或狄人的差别。</p><p>在故事中，这句话松动的是统治者对自身地位的执着：<strong>不能只为了保住“他们是我的臣民”，就让他们承担死亡。</strong></p><p>但不能由此认定所有统治者、统治方式事实上都一样。不同统治可能造成不同后果，原文没有展开这些条件。</p><h4 id="四、所用养与所养-用途不能反过来毁伤目的" tabindex="-1">四、所用养与所养：用途不能反过来毁伤目的 <a class="header-anchor" href="#四、所用养与所养-用途不能反过来毁伤目的" aria-label="Permalink to &quot;四、所用养与所养：用途不能反过来毁伤目的&quot;">​</a></h4><blockquote><p>不以所用养害所养。</p></blockquote><table tabindex="0"><thead><tr><th>层次</th><th>本故事中的主要所指</th></tr></thead><tbody><tr><td>所用养</td><td>土地等维持生活的条件</td></tr><tr><td>所养</td><td>人的生命与生活</td></tr></tbody></table><p>土地有价值，因为它能使人生活。如果为了守住土地而使人死亡，供养之物便反过来伤害了所养者。</p><p>这不是否认土地的重要，而是提醒：<strong>工具与条件再重要，也不能使其原本服务的对象被遗忘。</strong></p><p>若引申到财富、项目或组织，可以追问它们是否正在因被绝对化而损伤人。这属于现代参照，不是原文已经讨论了现代组织治理。</p><h4 id="五、迁而成国-放下土地-不等于失去共同生活" tabindex="-1">五、迁而成国：放下土地，不等于失去共同生活 <a class="header-anchor" href="#五、迁而成国-放下土地-不等于失去共同生活" aria-label="Permalink to &quot;五、迁而成国：放下土地，不等于失去共同生活&quot;">​</a></h4><blockquote><p>民相连而从之。遂成国于岐山之下。</p></blockquote><p>太王离去，民众接连跟随，在岐山之下重新成国。叙事没有止于个人远走，而写出了共同生活的重建。</p><p>但这一结果不能变成“放弃利益必得更大成功”的规律。</p><p>太王被称为能尊生，也不应只因为后来成国。更直接的根据，是他不愿以生命守住供养之物。</p><h4 id="六、富贵与贫贱-已有、未得-都可能使轻重倒置" tabindex="-1">六、富贵与贫贱：已有、未得，都可能使轻重倒置 <a class="header-anchor" href="#六、富贵与贫贱-已有、未得-都可能使轻重倒置" aria-label="Permalink to &quot;六、富贵与贫贱：已有、未得，都可能使轻重倒置&quot;">​</a></h4><blockquote><p>虽贵富不以养伤身，虽贫贱不以利累形。</p></blockquote><p>富贵者可能因享用或维护已有之物而伤身，贫贱者也可能因追求未得之利而累形。</p><p>问题不只属于拥有很多的人：已有之物可能使人不敢失去，未得之物也可能使人不断透支自己。</p><p>“重失之”与“轻亡其身”形成反差：对官爵之失极为敏感，对生命之失却轻忽。</p><p>这不是否定谋生劳动，而是要求辨认所得是否正在以不可承受的伤损为代价。</p><h3 id="本段要点" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p><strong>土地原本供养生命，不能为了土地反过来毁伤生命。</strong></p><p>太王的尊生包含对民众的关切；他的离去，也不能被简单归为自保或消极放弃。</p><h2 id="三、王子搜避位·君位与为君之患" tabindex="-1">三、王子搜避位·君位与为君之患 <a class="header-anchor" href="#三、王子搜避位·君位与为君之患" aria-label="Permalink to &quot;三、王子搜避位·君位与为君之患&quot;">​</a></h2><h3 id="原文-2" tabindex="-1">原文 <a class="header-anchor" href="#原文-2" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',38)),t(g,{sections:i(P),glossary:d,"default-mode":"classic","aria-label":"让王·third 原文"},null,8,["sections"]),a[11]||(a[11]=n("h3",{id:"字词释义-2",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-2","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(j)},null,8,["items"]),a[12]||(a[12]=n("h3",{id:"逐句导读-2",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-2","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(_)},null,8,["lines"]),a[13]||(a[13]=u('<h3 id="深入解读-2" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-2" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、逃避有具体背景-不是泛泛厌世" tabindex="-1">一、逃避有具体背景，不是泛泛厌世 <a class="header-anchor" href="#一、逃避有具体背景-不是泛泛厌世" aria-label="Permalink to &quot;一、逃避有具体背景，不是泛泛厌世&quot;">​</a></h4><blockquote><p>越人三世弑其君，王子搜患之。</p></blockquote><p>原文先交代接连弑君的危险，再写王子搜逃往丹穴。他所忧惧的有具体根据：君位不只是荣耀，也可能是高风险处境。</p><p>这与子州二人的治病回答不同：</p><ul><li>子州二人先照料已有的病苦；</li><li>王子搜不愿进入可能伤生的职位。</li></ul><p>同样是不愿承担，面对的生命条件却不同。</p><h4 id="二、被需要-也可能意味着被强迫" tabindex="-1">二、被需要，也可能意味着被强迫 <a class="header-anchor" href="#二、被需要-也可能意味着被强迫" aria-label="Permalink to &quot;二、被需要，也可能意味着被强迫&quot;">​</a></h4><p>王子搜不肯出，越人却用燃艾之烟逼他出来，再让他登王车。</p><p>“迎立”在这里不只是郑重认可，也越过了受任者的明确拒绝。他呼喊“独不可以舍我乎”，表明仍不愿承担。</p><p>结尾虽肯定这是越人想得到的君主，也不能抹去过程中的强迫。</p><p>从故事可以引出：**认为一个人适合承担，不等于可以忽略他的意愿与承受能力。**这属于关系层面的引申，不直接套作现代任职制度。</p><h4 id="三、职位与代价必须分开" tabindex="-1">三、职位与代价必须分开 <a class="header-anchor" href="#三、职位与代价必须分开" aria-label="Permalink to &quot;三、职位与代价必须分开&quot;">​</a></h4><blockquote><p>王子搜非恶为君也，恶为君之患也。</p></blockquote><p>叙述者明确区分君位本身与君位在此处境中带来的危险。</p><p>王子搜拒绝的，不一定是身份的全部价值，而是承担它的实际代价。因此不能概括为有道者都厌恶领导，或所有君位都应拒绝。</p><p>更准确的理解是：<strong>职位是否值得承担，要与具体风险一起判断。</strong></p><h4 id="四、不轻生者值得托付-却仍可能不愿受任" tabindex="-1">四、不轻生者值得托付，却仍可能不愿受任 <a class="header-anchor" href="#四、不轻生者值得托付-却仍可能不愿受任" aria-label="Permalink to &quot;四、不轻生者值得托付，却仍可能不愿受任&quot;">​</a></h4><blockquote><p>若王子搜者，可谓不以国伤生矣！此固越人之所欲得为君也。</p></blockquote><p>这与开篇“无以天下为者可以托天下”形成呼应：不急于取得君位、不轻忽生命的人，反而被认为值得托付。</p><p>但原文没有证明王子搜具有完整治国能力，也没有明说他将如何保护民众。</p><p>较直接的肯定是，他没有因为国家与君位的贵重，就轻忽生命。</p><p><strong>值得托付的评价，与不愿受任的事实同时存在，不能用前者取消后者。</strong></p><h3 id="本段要点-1" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-1" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p>君位的贵重，不会使为君的危险消失；一个人被认为适任，也不会因此失去拒绝的意愿。</p><h2 id="四、子华子辨轻重·所求与所付的代价" tabindex="-1">四、子华子辨轻重·所求与所付的代价 <a class="header-anchor" href="#四、子华子辨轻重·所求与所付的代价" aria-label="Permalink to &quot;四、子华子辨轻重·所求与所付的代价&quot;">​</a></h2><h3 id="原文-3" tabindex="-1">原文 <a class="header-anchor" href="#原文-3" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',27)),t(g,{sections:i(T),glossary:d,"default-mode":"classic","aria-label":"让王·fourth 原文"},null,8,["sections"]),a[14]||(a[14]=n("blockquote",null,[n("p",null,[n("strong",null,"文字说明")]),n("p",null,"“昭僖侯”沿用所供文本，不据称名强行补定完整历史身份。"),n("p",null,"“天下书铭”等句较简约，以下着眼于假设情境的论证作用，不强定每个字句的唯一译法。")],-1)),a[15]||(a[15]=n("h3",{id:"字词释义-3",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-3","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(S)},null,8,["items"]),a[16]||(a[16]=n("h3",{id:"逐句导读-3",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-3","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(A)},null,8,["lines"]),a[17]||(a[17]=u('<h3 id="深入解读-3" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-3" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、两臂换天下-先让代价显现" tabindex="-1">一、两臂换天下：先让代价显现 <a class="header-anchor" href="#一、两臂换天下-先让代价显现" aria-label="Permalink to &quot;一、两臂换天下：先让代价显现&quot;">​</a></h4><p>子华子没有一开始便说不该争土地，而是设定一个极端条件：</p><ul><li>用左手取得天下，右手便残废；</li><li>用右手取得天下，左手便残废；</li><li>攫取者一定能够得到天下。</li></ul><p>昭僖侯回答“不攫”，使讨论立足于他已经承认的选择：即使能得到天下，也不愿付出手臂残废的代价。</p><p>假设不是描述真实交易，而是将通常被荣耀掩盖的损失放到眼前。</p><h4 id="二、所求越来越小-损伤却仍落在生命上" tabindex="-1">二、所求越来越小，损伤却仍落在生命上 <a class="header-anchor" href="#二、所求越来越小-损伤却仍落在生命上" aria-label="Permalink to &quot;二、所求越来越小，损伤却仍落在生命上&quot;">​</a></h4><p>子华子进一步比较：</p><ol><li>按君主的选择，两臂重于天下；</li><li>身体整体又重于两臂；</li><li>韩国远小于天下；</li><li>所争土地又远小于韩国。</li></ol><p>君主却正在为较小的争地忧愁自身、损伤生命。</p><p>由此出现不一致：一方面不肯以身体换天下，另一方面却为远小于天下的土地持续伤生。</p><p>子华子的劝说让他看见：<strong>已经认可的轻重尺度，是否真正落实到眼前的行为中？</strong></p><h4 id="三、知轻重-不只看所得-也看逐渐累积的损耗" tabindex="-1">三、知轻重：不只看所得，也看逐渐累积的损耗 <a class="header-anchor" href="#三、知轻重-不只看所得-也看逐渐累积的损耗" aria-label="Permalink to &quot;三、知轻重：不只看所得，也看逐渐累积的损耗&quot;">​</a></h4><p>本段不只是劝人减少欲望，还要求把两边同时摆出来：</p><ul><li>所要取得的是什么；</li><li>为它正在付出的是什么。</li></ul><p>手臂残废是显眼的代价，忧愁、消耗与伤生则可能逐渐积累。不能因为损伤不是一次发生，就认为没有代价。</p><p>但这一比较也不能被转成适用于所有处境的固定数值表。故事主要针对眼前的争地忧患，揭示君主选择中的倒置。</p><p>它不能单独解决公共责任、他人安全与个人生命之间的所有复杂冲突。</p><h3 id="本段要点-2" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-2" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p><strong>知轻重，不只是口头上承认生命重要，还要检验实际用心是否正在违背这一判断。</strong></p><h2 id="一至四段·阶段性脉络" tabindex="-1">一至四段·阶段性脉络 <a class="header-anchor" href="#一至四段·阶段性脉络" aria-label="Permalink to &quot;一至四段·阶段性脉络&quot;">​</a></h2><h3 id="一、同样尊生-面对的对象与回应并不相同" tabindex="-1">一、同样尊生，面对的对象与回应并不相同 <a class="header-anchor" href="#一、同样尊生-面对的对象与回应并不相同" aria-label="Permalink to &quot;一、同样尊生，面对的对象与回应并不相同&quot;">​</a></h3><table tabindex="0"><thead><tr><th>故事</th><th>所面对的外物或位置</th><th>主要处境或生命代价</th><th>回应</th></tr></thead><tbody><tr><td>子州二人辞让</td><td>天下</td><td>已有病苦，无暇承担</td><td>先治病，不受</td></tr><tr><td>善卷辞让</td><td>天下</td><td>生活已自得，权位并非所需</td><td>拒绝，入深山</td></tr><tr><td>石户之农远避</td><td>天下与舜的邀请</td><td>认为舜用力经营，德尚未至</td><td>携家远避</td></tr><tr><td>太王迁岐</td><td>土地与原有统治</td><td>民众在战争中死亡</td><td>离开，迁而成国</td></tr><tr><td>王子搜避位</td><td>君位</td><td>接连弑君背景下的个人危险</td><td>逃避、拒绝，却被迎立</td></tr><tr><td>子华子劝侯</td><td>所争土地</td><td>忧愁自身、损伤生命</td><td>通过比较重新辨认轻重</td></tr></tbody></table><p>这些故事共同反省：外物不应因为被看重，就自动获得伤生的正当性。</p><p>但尊生不能被统一成一种动作。它可以表现为拒绝、离去、重新安排共同生活，也可以表现为改变判断、停止轻重倒置。</p><h3 id="二、实践参照-守住成果之前-先看它在供养谁" tabindex="-1">二、实践参照：守住成果之前，先看它在供养谁 <a class="header-anchor" href="#二、实践参照-守住成果之前-先看它在供养谁" aria-label="Permalink to &quot;二、实践参照：守住成果之前，先看它在供养谁&quot;">​</a></h3><p>以下是由文本引出的现代参照，不是原文直接制定的治理规则。</p><p><strong>不把供养条件变成最终目的。</strong><br> 财富、岗位、项目与组织有其价值，但若为了维持它们，持续损害原本要服务的人，就需要重新检验。</p><p><strong>把位置与承担条件分开。</strong><br> 一份位置受到认可，不代表眼下就适合接受。还应考察实际风险、个人意愿与可承担的条件。</p><p><strong>辨认逐渐发生的损耗。</strong><br> 不能只看目标的好处，而忽略持续忧惧、身体损伤与关系代价。</p><p>这些提醒不等于凡有压力便应退出。关键是辨认代价、寻找替代方式，而不是把“尊生”变成未经判断的统一答案。</p><h3 id="三、思想参照" tabindex="-1">三、思想参照 <a class="header-anchor" href="#三、思想参照" aria-label="Permalink to &quot;三、思想参照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>内容</th><th>可参照篇章或段落</th><th>联系与区别</th></tr></thead><tbody><tr><td>不以所用养害所养</td><td>《外物》无用之用</td><td>都可用于检验“有用”是否挤压生命条件，具体论述不同</td></tr><tr><td>不以国伤生</td><td>本篇开篇不以天下害生</td><td>从天下的一般判断，进入君位的具体风险</td></tr><tr><td>不争求者被认为可托付</td><td>本篇无以天下为者可以托天下</td><td>相似反差，不代表已证明完整治理能力</td></tr><tr><td>因未得之物而忧戚</td><td>《外物》利害相摩、心火焚和</td><td>可比较外在所求怎样转为内在损伤</td></tr><tr><td>检验已认可的尺度</td><td>《寓言》对判断与固执的反省</td><td>理解不能只停在口头认可，还需检验实际用心</td></tr></tbody></table><blockquote><p>以上参照用于比较阅读，不将相似题材当作直接写作关系，也不强行整理成各篇完全一致的思想体系。</p></blockquote><h3 id="四、核心句对照" tabindex="-1">四、核心句对照 <a class="header-anchor" href="#四、核心句对照" aria-label="Permalink to &quot;四、核心句对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>核心句</th><th>阅读重点</th><th>应避免的误读</th></tr></thead><tbody><tr><td>许由不受</td><td>郑重给予不意味着必须接受</td><td>将其他篇章的理由全部当作本段明说</td></tr><tr><td>方且治之，未暇治天下</td><td>从病苦辨认承担条件与优先次序</td><td>疾病必是假托；治病只是怯懦</td></tr><tr><td>不以害其生；不以易生</td><td>天下再重，也不自动成为伤生理由</td><td>天下毫无价值；公共事务都应拒绝</td></tr><tr><td>无以天下为者可以托天下</td><td>不争求与可托付之间的反差</td><td>自称不想掌权便必定适任</td></tr><tr><td>心意自得</td><td>自得不必依赖权位</td><td>自在等于不劳动；人人必须务农隐居</td></tr><tr><td>子之不知余</td><td>贵重赠予未必适合对方</td><td>给予者必定虚伪或怀有恶意</td></tr><tr><td>以舜之德为未至</td><td>不把用力经营直接等同于至德</td><td>一切努力都错误</td></tr><tr><td>携子以入于海</td><td>携家远避</td><td>入海就是投海自尽</td></tr><tr><td>不以所用养害所养</td><td>供养条件不能反伤生命</td><td>土地毫无价值；任何冲突都应退让</td></tr><tr><td>虽贫贱不以利累形</td><td>未得之利也可能使生命受累</td><td>所有谋生劳动都应停止</td></tr><tr><td>非恶为君也，恶为君之患也</td><td>区分职位与具体危险</td><td>所有君位都应拒绝</td></tr><tr><td>独不可以舍我乎</td><td>被需要与不愿受任之间的张力</td><td>适任评价可以取消个人意愿</td></tr><tr><td>两臂重于天下也</td><td>从已承认的选择出发辨轻重</td><td>所有复杂责任都可按固定数值排序</td></tr><tr><td>愁身伤生以忧戚不得</td><td>看见未得之物造成的实际损耗</td><td>损伤未一次发生，就没有代价</td></tr><tr><td>知轻重</td><td>同时辨认所求与所付</td><td>口头承认生命重要便已完成判断</td></tr></tbody></table><h2 id="五、颜阖避聘·认可未必是自己所需" tabindex="-1">五、颜阖避聘·认可未必是自己所需 <a class="header-anchor" href="#五、颜阖避聘·认可未必是自己所需" aria-label="Permalink to &quot;五、颜阖避聘·认可未必是自己所需&quot;">​</a></h2><h3 id="原文-4" tabindex="-1">原文 <a class="header-anchor" href="#原文-4" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',38)),t(g,{sections:i(C),glossary:d,"default-mode":"classic","aria-label":"让王·颜阖避聘 原文"},null,8,["sections"]),a[18]||(a[18]=n("h3",{id:"字词释义-4",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-4","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(V)},null,8,["items"]),a[19]||(a[19]=n("h3",{id:"语句导读",tabindex:"-1"},[e("语句导读 "),n("a",{class:"header-anchor",href:"#语句导读","aria-label":'Permalink to "语句导读"'},"​")],-1)),t(h,{lines:i(I)},null,8,["lines"]),a[20]||(a[20]=u('<h3 id="深入解读-4" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-4" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、闻其得道-先送聘礼-认可也带来新的安排" tabindex="-1">一、闻其得道，先送聘礼：认可也带来新的安排 <a class="header-anchor" href="#一、闻其得道-先送聘礼-认可也带来新的安排" aria-label="Permalink to &quot;一、闻其得道，先送聘礼：认可也带来新的安排&quot;">​</a></h4><blockquote><p>鲁君闻颜阖得道之人也，使人以币先焉。</p></blockquote><p>鲁君听闻颜阖有道，派人先送礼物。故事没有先写鲁君怀有恶意；从他的立场看，这可能是礼贤、延请有道者的举动。</p><p>但聘礼不只是可供使用的财物，也意味着颜阖可能被引入君主所设定的身份与事务。</p><p>原文未细列后续责任，不能补成确定的政治契约。不过，“以币先焉”表明礼物是延请的先导，并非与后续关系毫无联系。</p><h4 id="二、陋居饭牛-富贵来到之前-他已有自己的生活" tabindex="-1">二、陋居饭牛：富贵来到之前，他已有自己的生活 <a class="header-anchor" href="#二、陋居饭牛-富贵来到之前-他已有自己的生活" aria-label="Permalink to &quot;二、陋居饭牛：富贵来到之前，他已有自己的生活&quot;">​</a></h4><blockquote><p>颜阖守陋闾，苴布之衣，而自饭牛。</p></blockquote><p>陋居、粗衣、亲自喂牛，与外来的聘礼形成对照。</p><p>原文没有因生活简陋，就把颜阖写成急待富贵救援的人。但也不能反过来说贫困本身值得赞美。</p><p>这些细节主要表明：<strong>富贵到来之前，他已经在过自己的生活；是否接受，不能只按外在资源的多少判断。</strong></p><h4 id="三、承认身份-再请核实-让受聘进程暂时中断" tabindex="-1">三、承认身份，再请核实：让受聘进程暂时中断 <a class="header-anchor" href="#三、承认身份-再请核实-让受聘进程暂时中断" aria-label="Permalink to &quot;三、承认身份，再请核实：让受聘进程暂时中断&quot;">​</a></h4><blockquote><p>此阖之家也。<br> 恐听谬而遗使者罪，不若审之。</p></blockquote><p>颜阖没有简单说使者找错了人。他先承认这是自己的家，再将是否确应送礼的问题交还使者核实。</p><p>这段言辞既不正面接受聘礼，也给使者一个返回复核的理由。</p><p>他口头上顾及使者可能获罪，但原文未充分展开其全部心理。不必断言完全出于关怀，也不必断言只是虚伪托词。</p><p>较明确的是：当场受聘的进程因此中断。</p><h4 id="四、离去完成拒绝-不是等待更高的礼遇" tabindex="-1">四、离去完成拒绝：不是等待更高的礼遇 <a class="header-anchor" href="#四、离去完成拒绝-不是等待更高的礼遇" aria-label="Permalink to &quot;四、离去完成拒绝：不是等待更高的礼遇&quot;">​</a></h4><p>使者返回核实，再来寻找时，颜阖已经不在。故事没有以长篇辞聘演说收束，而是用离去完成拒绝。</p><blockquote><p>故若颜阖者，真恶富贵也。</p></blockquote><p>“真”强调实际退出，而非口头辞让之后仍等待更高礼遇。</p><p>但不能据此规定：</p><ul><li>凡接受聘请者都无道；</li><li>真正拒绝就必须使人找不到；</li><li>不辞而去适用于所有关系。</li></ul><p><strong>原文描写的是颜阖的选择，不是在制定统一的沟通规则。</strong></p><h3 id="本段要点-3" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-3" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p>外在认可与富贵机会，不会自动成为受让者的需要。颜阖的拒绝落实为行动，但他的方式不必成为所有人的固定模板。</p><h2 id="六、治身与殉物·所用不可重于所求" tabindex="-1">六、治身与殉物·所用不可重于所求 <a class="header-anchor" href="#六、治身与殉物·所用不可重于所求" aria-label="Permalink to &quot;六、治身与殉物·所用不可重于所求&quot;">​</a></h2><h3 id="原文-5" tabindex="-1">原文 <a class="header-anchor" href="#原文-5" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',28)),t(g,{sections:i(D),glossary:d,"default-mode":"classic","aria-label":"让王·sixth 原文"},null,8,["sections"]),a[21]||(a[21]=n("h3",{id:"字词释义-5",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-5","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(N)},null,8,["items"]),a[22]||(a[22]=n("h3",{id:"逐句导读-4",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-4","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(R)},null,8,["lines"]),a[23]||(a[23]=u('<h3 id="深入解读-5" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-5" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、治身、国家、天下-鲜明的本末重排" tabindex="-1">一、治身、国家、天下：鲜明的本末重排 <a class="header-anchor" href="#一、治身、国家、天下-鲜明的本末重排" aria-label="Permalink to &quot;一、治身、国家、天下：鲜明的本末重排&quot;">​</a></h4><blockquote><p>道之真以治身，其绪余以为国家，其土苴以治天下。</p></blockquote><table tabindex="0"><thead><tr><th>层次</th><th>原文表述</th></tr></thead><tbody><tr><td>治身</td><td>道之真</td></tr><tr><td>为国家</td><td>绪余</td></tr><tr><td>治天下</td><td>土苴</td></tr></tbody></table><p>治身被置于根本位置，治理国家与天下被置于余用位置。</p><p>这是一种鲜明的价值重排，不能完全淡化为修身、治国同样重要，只须均衡兼顾。原文的语气比这更强。</p><p>但“绪余”“土苴”首先表达本末与轻重，不是在规定先修身毕业、再治国毕业、最后治理天下的课程顺序。</p><h4 id="二、帝王之功-不自动保证生命已经安顿" tabindex="-1">二、帝王之功：不自动保证生命已经安顿 <a class="header-anchor" href="#二、帝王之功-不自动保证生命已经安顿" aria-label="Permalink to &quot;二、帝王之功：不自动保证生命已经安顿&quot;">​</a></h4><blockquote><p>帝王之功，圣人之余事也，非所以完身养生也。</p></blockquote><p>本句继续将帝王功业从中心移开。取得显赫功业，不自动等于自身得到了保全与养护。</p><p>为帮助理解，可以想到功业伴随身体损伤、生命陷险或持续透支的情形。这些是解读中的展开，不是原文逐项列举。</p><p>“余事”不必等于完全无意义，但本段明确拒绝把外在功业当作完身养生的根本保证。</p><h4 id="三、危身弃生以殉物-批评代价倒置-不是否定行动" tabindex="-1">三、危身弃生以殉物：批评代价倒置，不是否定行动 <a class="header-anchor" href="#三、危身弃生以殉物-批评代价倒置-不是否定行动" aria-label="Permalink to &quot;三、危身弃生以殉物：批评代价倒置，不是否定行动&quot;">​</a></h4><blockquote><p>今世俗之君子，多危身弃生以殉物，岂不悲哉！</p></blockquote><p>“殉物”使外物从服务生命的条件，变成要求生命为之牺牲的对象，与太王故事“不以所用养害所养”直接呼应。</p><p>不过，下文仍谈圣人的“动作”，并没有要求停止所有行动。</p><p>问题在于：<strong>行动时，是否看清目标、缘由、凭借，以及将付出什么。</strong></p><h4 id="四、察所以之与所以为-拿什么去求什么" tabindex="-1">四、察所以之与所以为：拿什么去求什么 <a class="header-anchor" href="#四、察所以之与所以为-拿什么去求什么" aria-label="Permalink to &quot;四、察所以之与所以为：拿什么去求什么&quot;">​</a></h4><blockquote><p>凡圣人之动作也，必察其所以之与其所以为。</p></blockquote><p>“所以之”与“所以为”的训释存在差异。暂可分别联系行动趋向什么，以及行动缘何而起、凭借什么展开。</p><p>下文的珠与雀，则将问题具体化为：拿什么去求什么？</p><p>因而，不仅要问目标是否值得，还要问实现目标是否正在付出分量更重的东西。</p><p>**目标受到认可，不会自动使所有手段与代价都合理。**这是联系比喻所作的引申，不作为唯一逐字译法。</p><h4 id="五、宝珠弹雀-以明显失衡揭露隐蔽失衡" tabindex="-1">五、宝珠弹雀：以明显失衡揭露隐蔽失衡 <a class="header-anchor" href="#五、宝珠弹雀-以明显失衡揭露隐蔽失衡" aria-label="Permalink to &quot;五、宝珠弹雀：以明显失衡揭露隐蔽失衡&quot;">​</a></h4><blockquote><p>以随侯之珠，弹千仞之雀，世必笑之。<br> 所用者重而所要者轻也。</p></blockquote><p>宝珠贵重，雀相对轻小。即使能够得到雀，用宝珠作弹丸仍显得得不偿失。</p><p>关键不是雀毫无价值，而是为它付出的东西远比所得贵重。因此不必把比喻解释成对小事的全面鄙视。</p><blockquote><p>夫生者岂特随侯之重哉！</p></blockquote><p>世人容易看见宝珠的损失，却可能轻忽比宝珠更重的生命。</p><p>反问的锋利处在于：<strong>为什么对珍宝的损失如此敏感，对自身生命的损耗却如此轻忽？</strong></p><p>这不是证明所有价值都能精确换算，而是让读者反省，已经认可的轻重判断是否在自身追求中失效。</p><h3 id="本段要点-4" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-4" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p>治身被置于根本位置，外在功业不能代替生命安顿。行动并未被取消，但所用与所求之间的轻重关系必须接受检验。</p><h2 id="七、列子辞粟·给予的依据与关系风险" tabindex="-1">七、列子辞粟·给予的依据与关系风险 <a class="header-anchor" href="#七、列子辞粟·给予的依据与关系风险" aria-label="Permalink to &quot;七、列子辞粟·给予的依据与关系风险&quot;">​</a></h2><h3 id="原文-6" tabindex="-1">原文 <a class="header-anchor" href="#原文-6" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',35)),t(g,{sections:i(G),glossary:d,"default-mode":"classic","aria-label":"让王·seventh 原文"},null,8,["sections"]),a[24]||(a[24]=n("h3",{id:"字词释义-6",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-6","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(E)},null,8,["items"]),a[25]||(a[25]=n("h3",{id:"逐句导读-5",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-5","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(K)},null,8,["lines"]),a[26]||(a[26]=u('<h3 id="深入解读-6" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-6" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、客人的劝说-贫困成为执政者的声誉问题" tabindex="-1">一、客人的劝说：贫困成为执政者的声誉问题 <a class="header-anchor" href="#一、客人的劝说-贫困成为执政者的声誉问题" aria-label="Permalink to &quot;一、客人的劝说：贫困成为执政者的声誉问题&quot;">​</a></h4><blockquote><p>居君之国而穷，君无乃为不好士乎？</p></blockquote><p>客人先说列子是有道之士，再将其贫困与子阳是否礼贤联系起来。子阳随即派官员送粟，赠粮是在他人评价的推动下发生的。</p><p>但不能仅凭这一点断言子阳绝无善意。</p><p>列子较明确的顾虑是：子阳并非出于对自己的实际了解而作出判断。</p><h4 id="二、再拜而辞-拒绝不等于傲慢" tabindex="-1">二、再拜而辞：拒绝不等于傲慢 <a class="header-anchor" href="#二、再拜而辞-拒绝不等于傲慢" aria-label="Permalink to &quot;二、再拜而辞：拒绝不等于傲慢&quot;">​</a></h4><blockquote><p>子列子见使者，再拜而辞。</p></blockquote><p>列子先行礼，再辞谢。原文没有把他写成辱骂使者、鄙视粮食的人。</p><p>这与颜阖不同：颜阖请使者核实，随后离去；列子当面致敬，然后明确不受。</p><p><strong>同样拒绝外来给予，不必采用同一种表达方式。</strong></p><h4 id="三、妻子的痛惜-不能忽略拒绝的真实代价" tabindex="-1">三、妻子的痛惜：不能忽略拒绝的真实代价 <a class="header-anchor" href="#三、妻子的痛惜-不能忽略拒绝的真实代价" aria-label="Permalink to &quot;三、妻子的痛惜：不能忽略拒绝的真实代价&quot;">​</a></h4><p>列子的妻子看见他不受，拊心感叹。她的反应提醒读者：粮食确实能缓解困苦，列子的饥饿也不是抽象考验。</p><p>家属同样承受缺乏，希望得到安逸并非不可理解。</p><p>不宜将她简化为只认钱粮、完全不懂有道者的反面角色。她使拒绝的代价进入故事：</p><p><strong>不受可能保全关系上的独立，也意味着继续承受眼前的缺乏。</strong></p><h4 id="四、赏罚依赖同一种方式-恩惠也可能伴随危险" tabindex="-1">四、赏罚依赖同一种方式：恩惠也可能伴随危险 <a class="header-anchor" href="#四、赏罚依赖同一种方式-恩惠也可能伴随危险" aria-label="Permalink to &quot;四、赏罚依赖同一种方式：恩惠也可能伴随危险&quot;">​</a></h4><blockquote><p>君非自知我也，以人之言而遗我粟；至其罪我也，又且以人之言。</p></blockquote><p>列子关注的，不只是此次得到什么，而是奖惩所依赖的判断方式。</p><p>今天别人称赞，子阳便赠粟；将来别人指责，也可能加罪。未经充分了解的判断方式，既能产生恩惠，也能产生危险。</p><p>这不等于否定所有推荐。需要区分的是：推荐之后是否还有实际了解与检验，还是一句传言就足以决定赏罚？</p><p>列子说明的是风险判断，不是证明子阳未来必会处罚自己的确定预言。</p><h4 id="五、子阳被杀-叙事印证不能扩大为完整因果证明" tabindex="-1">五、子阳被杀：叙事印证不能扩大为完整因果证明 <a class="header-anchor" href="#五、子阳被杀-叙事印证不能扩大为完整因果证明" aria-label="Permalink to &quot;五、子阳被杀：叙事印证不能扩大为完整因果证明&quot;">​</a></h4><blockquote><p>其卒，民果作难而杀子阳。</p></blockquote><p>“果”使结尾带有印证顾虑的语气：列子没有进入的那份关系，其所依附的执政者后来遭遇变乱。</p><p>但实际写出的只是子阳被杀，并未写：</p><ul><li>子阳后来听信谗言处罚列子；</li><li>列子受粟便一定同遭灾难；</li><li>列子的每一项可能判断都已得到验证。</li></ul><p><strong>结尾强化了风险顾虑，却没有完整证明所有可能的因果链。</strong></p><h3 id="本段要点-5" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-5" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p>粮食有用，饥饿真实，但是否接受仍需考察施予者的判断依据与关系风险。对拒绝的赞许，也不能抹去家属继续承受困苦的代价。</p><h2 id="八、屠羊说辞赏·功罪、法约与辞受之义" tabindex="-1">八、屠羊说辞赏·功罪、法约与辞受之义 <a class="header-anchor" href="#八、屠羊说辞赏·功罪、法约与辞受之义" aria-label="Permalink to &quot;八、屠羊说辞赏·功罪、法约与辞受之义&quot;">​</a></h2><h3 id="原文-7" tabindex="-1">原文 <a class="header-anchor" href="#原文-7" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',32)),t(g,{sections:i(v),glossary:d,"default-mode":"classic","aria-label":"让王·eighth 原文"},null,8,["sections"]),a[27]||(a[27]=n("h3",{id:"字词释义-7",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-7","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(O)},null,8,["items"]),a[28]||(a[28]=n("h3",{id:"逐句导读-6",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-6","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(B)},null,8,["lines"]),a[29]||(a[29]=u('<h3 id="深入解读-7" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-7" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、跟随出奔-是否就有从王之功" tabindex="-1">一、跟随出奔，是否就有从王之功？ <a class="header-anchor" href="#一、跟随出奔-是否就有从王之功" aria-label="Permalink to &quot;一、跟随出奔，是否就有从王之功？&quot;">​</a></h4><blockquote><p>屠羊说走而从于昭王。</p></blockquote><p>开篇从外在行动写屠羊说逃难、跟随昭王。昭王返回后赏赐随从，他自然被列入其中。</p><p>但他随后说明：</p><blockquote><p>说畏难而避寇，非故随大王也。</p></blockquote><p>从赏赐的分类看，他属于随从；从自己的动机看，主要是在避难。</p><p>故事要求辨认实际行动、动机与贡献，不能只因表面符合“从者”类别，就省略判断。</p><p>但也不能反推凡兼有避难动机者都无贡献。本故事是屠羊说明确否认自己有足以承赏的功劳，不是对所有随从作统一裁定。</p><h4 id="二、爵禄已复-原业也是有分量的生活" tabindex="-1">二、爵禄已复：原业也是有分量的生活 <a class="header-anchor" href="#二、爵禄已复-原业也是有分量的生活" aria-label="Permalink to &quot;二、爵禄已复：原业也是有分量的生活&quot;">​</a></h4><blockquote><p>大王失国，说失屠羊。大王反国，说亦反屠羊。</p></blockquote><table tabindex="0"><thead><tr><th>楚昭王</th><th>屠羊说</th></tr></thead><tbody><tr><td>失去国中原有处境</td><td>失去屠羊营生</td></tr><tr><td>返回国家</td><td>返回原业</td></tr></tbody></table><p>屠羊说随后将自己的营生称作“爵禄”，形成鲜明对照。他没有把君主身份看作唯一有价值的生活，也没有把自己的原业视为毫无分量。</p><p>对他而言，能够回去屠羊，已经是生活的恢复。</p><p>但原文没有清点战争损失，不能改写成回到原业便意味着一切损失都已补偿。</p><h4 id="三、非臣之罪-非臣之功-不因受益改写事实" tabindex="-1">三、非臣之罪，非臣之功：不因受益改写事实 <a class="header-anchor" href="#三、非臣之罪-非臣之功-不因受益改写事实" aria-label="Permalink to &quot;三、非臣之罪，非臣之功：不因受益改写事实&quot;">​</a></h4><blockquote><p>大王失国，非臣之罪，故不敢伏其诛；大王反国，非臣之功，故不敢当其赏。</p></blockquote><p>这是一组对称判断：</p><ul><li>失国不是自己的罪，不应承受处罚；</li><li>复国不是自己的功，也不应接受赏赐。</li></ul><p><strong>不承担不属于自己的罪，也不认领不属于自己的功。</strong></p><p>拒赏不只是喜不喜欢钱的问题。赏赐对自己有利，也不能因此改变功罪归属。</p><p>不过，这里是复国后论功赏从者的语境，不能推广为所有救济、交往与赠予都必须建立在功劳之上。</p><h4 id="四、拒绝召见-有利于自己的例外也应检验" tabindex="-1">四、拒绝召见：有利于自己的例外也应检验 <a class="header-anchor" href="#四、拒绝召见-有利于自己的例外也应检验" aria-label="Permalink to &quot;四、拒绝召见：有利于自己的例外也应检验&quot;">​</a></h4><p>昭王要召见，屠羊说却提出楚国之法，强调受见需要相应资格。</p><p>这一法度是故事人物的陈述，应按其叙事作用理解，不直接当作已经核实的完整楚国制度史。</p><blockquote><p>今臣之知不足以存国，而勇不足以死寇。</p></blockquote><p>他承认自己没有以才智存国，也没有以勇力死寇，出奔是畏难避寇。不因被列入奖励，就将自保行动美化为忠勇功业。</p><p>这不意味着所有人都必须有存国、死寇之功。他没有因未做到这些而请求处罚，只是据实际所为判断是否符合此次受赏、受见的理由。</p><blockquote><p>今大王欲废法毁约而见说，此非臣之所以闻于天下也。</p></blockquote><p>特别召见可能带来荣耀，但若要破坏既有规范，他不愿以此方式为天下所知。</p><p><strong>受益者也可以检验：使自己得利的例外，是否有合宜根据。</strong></p><h4 id="五、闻于天下-不是完全不在意名声" tabindex="-1">五、闻于天下：不是完全不在意名声 <a class="header-anchor" href="#五、闻于天下-不是完全不在意名声" aria-label="Permalink to &quot;五、闻于天下：不是完全不在意名声&quot;">​</a></h4><p>屠羊说关注自己如何“闻于天下”，后面也关注君主是否有“妄施之名”。</p><p>因而，不能把他解释成完全不在意任何外在评价的人。他在意的是以什么事实、通过什么方式为天下所知。</p><p>本段与“忘名”不能简单画等号。这里主要讨论辞受是否合宜，以及名声是否建立在相应事实上。</p><h4 id="六、陈义甚高-延请理由发生了变化" tabindex="-1">六、陈义甚高：延请理由发生了变化 <a class="header-anchor" href="#六、陈义甚高-延请理由发生了变化" aria-label="Permalink to &quot;六、陈义甚高：延请理由发生了变化&quot;">​</a></h4><blockquote><p>屠羊说居处卑贱而陈义甚高。</p></blockquote><p>昭王看见了身份之外的价值，准备以高位延请。关注点已经由是否从王出奔，转向他所陈述的义理。</p><p>这里也留下一个问题：若从赏从者转为因其义而任用，是否已构成新的合宜理由？</p><p>原文没有充分展开双方对新理由的讨论。屠羊说随后仍认为受位会使君主有妄施之名，应保留这一判断，而不假定任职条件已经充分论证。</p><h4 id="七、知其贵-知其富-拒绝不依赖贬低所得" tabindex="-1">七、知其贵，知其富：拒绝不依赖贬低所得 <a class="header-anchor" href="#七、知其贵-知其富-拒绝不依赖贬低所得" aria-label="Permalink to &quot;七、知其贵，知其富：拒绝不依赖贬低所得&quot;">​</a></h4><blockquote><p>吾知其贵于屠羊之肆也。<br> 吾知其富于屠羊之利也。</p></blockquote><p>屠羊说明确承认高位更贵、厚禄更富，没有为了拒绝而说它们毫无价值。</p><p>因而，他的判断是：</p><p><strong>它确实更富贵，但我仍认为自己不应以这次方式接受。</strong></p><p>不能解释成他不懂爵禄的好处、确信屠羊能赚更多，或一概厌恶所有富贵。</p><p>有价值，与取得方式合宜，是两回事。</p><h4 id="八、妄施之名-自己的获利不是唯一尺度" tabindex="-1">八、妄施之名：自己的获利不是唯一尺度 <a class="header-anchor" href="#八、妄施之名-自己的获利不是唯一尺度" aria-label="Permalink to &quot;八、妄施之名：自己的获利不是唯一尺度&quot;">​</a></h4><blockquote><p>然岂可以贪爵禄而使吾君有妄施之名乎？</p></blockquote><p>屠羊说不仅看自己能得到什么，也看施予是否有根据，以及是否使君主受到不当评价。</p><p>这一判断延续了功罪、法约与资格的辨认。但“妄施”仍是他在故事中的判断，原文没有另立完整制度来裁定一切特别任用。</p><p>可以肯定他坚持辞受之义，不宜将所有制度问题说成已经解决。</p><h4 id="九、返回屠羊之肆-判断落实为行动" tabindex="-1">九、返回屠羊之肆：判断落实为行动 <a class="header-anchor" href="#九、返回屠羊之肆-判断落实为行动" aria-label="Permalink to &quot;九、返回屠羊之肆：判断落实为行动&quot;">​</a></h4><blockquote><p>愿复反吾屠羊之肆。遂不受也。</p></blockquote><p>赏赐、召见、高位厚禄逐次加重，他仍不改变结论。拒绝不是争取更高奖励的谈判姿态，而是落实辞受判断。</p><p>但原文没有像善卷那样详写“心意自得”。可以说他选择原业，不必断言他内心已无任何欲求，达到绝对自在。</p><h3 id="本段要点-6" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-6" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p>不因赏赐有利，就改变对自身所为的认识；不因能够获利，就省略对赏赐根据的判断。</p><p><strong>我参与了这件事、我对结果有这份功劳、我应当接受这份赏赐，三者可能相关，却不能未经辨认便视为同一件事。</strong></p><h2 id="五至八段·阶段性脉络" tabindex="-1">五至八段·阶段性脉络 <a class="header-anchor" href="#五至八段·阶段性脉络" aria-label="Permalink to &quot;五至八段·阶段性脉络&quot;">​</a></h2><h3 id="一、辞受的理由不能混为一种" tabindex="-1">一、辞受的理由不能混为一种 <a class="header-anchor" href="#一、辞受的理由不能混为一种" aria-label="Permalink to &quot;一、辞受的理由不能混为一种&quot;">​</a></h3><table tabindex="0"><thead><tr><th>段落或人物</th><th>面对的事物</th><th>明确的判断重心</th><th>回应</th></tr></thead><tbody><tr><td>颜阖</td><td>聘礼与延请</td><td>不愿接受富贵安排</td><td>请使者核实，随后离去</td></tr><tr><td>集中论说</td><td>帝王功业与一般外物</td><td>不以较重之物求较轻之得，不以外物殉生</td><td>检验目标、凭借与代价</td></tr><tr><td>列子</td><td>能缓解饥饿的粮食</td><td>施予者非自知，赏罚方式不可靠</td><td>再拜而辞，说明风险</td></tr><tr><td>屠羊说</td><td>赏赐、召见、高位厚禄</td><td>不认无功之赏，不因获利省略辞受之义</td><td>逐层说明，最终不受</td></tr></tbody></table><p>四者不能简化成“不喜欢钱”。</p><p>颜阖被明确评价为恶富贵；列子谈的是传言主导赏罚的风险；屠羊说则承认富贵价值，着重辨认功罪、法约与义。</p><h3 id="二、尊生主线有所展开-却不能包办全部解释" tabindex="-1">二、尊生主线有所展开，却不能包办全部解释 <a class="header-anchor" href="#二、尊生主线有所展开-却不能包办全部解释" aria-label="Permalink to &quot;二、尊生主线有所展开，却不能包办全部解释&quot;">​</a></h3><p>第六段直接延续前文不以外物伤生的尺度。</p><p>屠羊说的故事则进一步涉及不认领不属之功、不接受自己认为缺乏合宜根据的施予。</p><p>两者都要求检验外在利益，但不能将屠羊说全部改写成保命策略。他没有像列子那样明确谈受赏后的危险，拒绝重心主要是功罪与辞受之义。</p><p><strong>《让王》的辞受问题，不能只用一种动机解释。</strong></p><h3 id="三、两个轻重比喻的对照" tabindex="-1">三、两个轻重比喻的对照 <a class="header-anchor" href="#三、两个轻重比喻的对照" aria-label="Permalink to &quot;三、两个轻重比喻的对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>比喻</th><th>从什么判断出发</th><th>揭露什么倒置</th></tr></thead><tbody><tr><td>两臂换天下</td><td>君主明确表示不取</td><td>不肯以臂换天下，却为更小的争地忧愁伤生</td></tr><tr><td>宝珠弹雀</td><td>世人通常会嘲笑这种做法</td><td>看重宝珠，却可能轻忽更重的生命</td></tr></tbody></table><p>二者都借容易承认的比较，检验日常追求中的尺度失效，不是在制定能计算所有责任冲突的价值表。</p><h3 id="四、实践参照-分开所得、取得方式与承担代价" tabindex="-1">四、实践参照：分开所得、取得方式与承担代价 <a class="header-anchor" href="#四、实践参照-分开所得、取得方式与承担代价" aria-label="Permalink to &quot;四、实践参照：分开所得、取得方式与承担代价&quot;">​</a></h3><p>以下是现代阅读中的引申，不是原文直接制定的行动守则。</p><ul><li>**辨认给来的究竟是什么。**资源可能同时带来身份、责任、期待与评价，不必一概排斥，但应看清关系。</li><li>**辨认判断依据。**推荐可以提供线索，却不应代替实际了解、明确标准与必要检验。</li><li>**辨认拒绝本身的代价。**不受可能保全独立，也可能使自己与家属继续承受缺乏，不能只赞美姿态。</li><li>**不让奖励改写事实。**在场、随行、实际承担与对结果的贡献，可能重叠，也可能不同。</li><li>**检验对自己有利的例外。**特别认可不一定不当，但仍需合宜、公平的根据。</li><li>**承认吸引力，也可以拒绝。**不必先贬低所得，才能说明自己为何不愿或不宜接受。</li></ul><p>正当所得也不必为了显得高洁而一概拒绝，更不应以反复辞让经营声名。</p><h3 id="五、思想参照" tabindex="-1">五、思想参照 <a class="header-anchor" href="#五、思想参照" aria-label="Permalink to &quot;五、思想参照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>内容</th><th>可参照篇章或故事</th><th>联系与区别</th></tr></thead><tbody><tr><td>颜阖避聘</td><td>本篇善卷“子之不知余”</td><td>外在认可未必符合受让者所需；颜阖未作同样的自得陈述</td></tr><tr><td>治身与治天下的轻重</td><td>本篇太王“不以所用养害所养”</td><td>都警惕外物反过来伤害生命</td></tr><tr><td>宝珠弹雀</td><td>本篇子华子“两臂换天下”</td><td>都以明确比较揭露日常行为的轻重倒置</td></tr><tr><td>功业不保证完身养生</td><td>《外物》有关名利与伤生的论述</td><td>外在所得不自动保证生命安顿</td></tr><tr><td>子阳听客言而赠粟</td><td>《寓言》对接受与权威的反省</td><td>被接受、受认可与判断可靠需要区分</td></tr><tr><td>列子之妻的痛惜</td><td>本篇贫居故事</td><td>内在自得与真实物质困苦应分别看待</td></tr><tr><td>返回屠羊原业</td><td>本篇善卷、颜回的生活选择</td><td>不以更高权位为生活成立的必要条件；屠羊说更强调辞受之义</td></tr><tr><td>屠羊说与列子辞受</td><td>本篇列子辞粟</td><td>都检验给予的根据；列子谈风险，屠羊说谈功与义</td></tr><tr><td>居处卑贱而陈义甚高</td><td>《寓言》对重言分量的检验</td><td>身份不自动等于识见，识见不只来自高位</td></tr><tr><td>不美化自身所为</td><td>《寓言》阳子居去除自矜</td><td>可比较自我形象的松动，本段并未直接讨论平等相处</td></tr><tr><td>辨认自身与君主的名声</td><td>《逍遥游》举世誉非相关论述</td><td>屠羊说仍关注君名与如何闻于天下，不直接等同于不受誉非影响</td></tr></tbody></table><blockquote><p>这些参照用于对读，不将相似内容当作完全同义，也不据此断定各篇具有统一的论证结构。</p></blockquote><h3 id="六、核心句对照" tabindex="-1">六、核心句对照 <a class="header-anchor" href="#六、核心句对照" aria-label="Permalink to &quot;六、核心句对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>核心句</th><th>阅读重点</th><th>应避免的误读</th></tr></thead><tbody><tr><td>真恶富贵也</td><td>以行动退出不愿接受的安排</td><td>凡受聘者都无道；拒绝必须不辞而去</td></tr><tr><td>道之真以治身</td><td>治身被置于根本位置</td><td>三者只是同等重要；这是三阶段课程</td></tr><tr><td>帝王之功，圣人之余事也</td><td>功业不自动保证生命安顿</td><td>功业绝对无用</td></tr><tr><td>必察其所以之与其所以为</td><td>检验行动趋向、缘由与凭借</td><td>所有行动都应停止</td></tr><tr><td>所用者重而所要者轻</td><td>比较所付与所得</td><td>小事都毫无价值</td></tr><tr><td>再拜而辞</td><td>致敬与拒绝可以并存</td><td>拒绝必定傲慢</td></tr><tr><td>以人之言而遗我粟……又且以人之言</td><td>检验奖惩所依赖的方式</td><td>所有推荐都不可信</td></tr><tr><td>民果作难而杀子阳</td><td>结尾强化关系风险</td><td>已证明列子受粟必遭灾难</td></tr><tr><td>臣之爵禄已复矣</td><td>原业恢复也有分量</td><td>战争损失已全部消除</td></tr><tr><td>非臣之罪；非臣之功</td><td>不承虚加之罪，不认不属之功</td><td>所有赠予都须有功劳</td></tr><tr><td>非故随大王也</td><td>不因事后获赏美化实际动机</td><td>有避难动机便绝无贡献</td></tr><tr><td>废法毁约而见说</td><td>对受益的例外也作检验</td><td>所有特别任用都不当</td></tr><tr><td>吾知其贵；吾知其富</td><td>价值与取得是否合宜相分离</td><td>他不懂或一概厌恶富贵</td></tr><tr><td>愿复反吾屠羊之肆</td><td>将辞受判断落实为行动</td><td>拒绝只是索取更高奖励的策略</td></tr></tbody></table><h2 id="九、原宪贫而非病·财物与实践的区别" tabindex="-1">九、原宪贫而非病·财物与实践的区别 <a class="header-anchor" href="#九、原宪贫而非病·财物与实践的区别" aria-label="Permalink to &quot;九、原宪贫而非病·财物与实践的区别&quot;">​</a></h2><h3 id="原文-8" tabindex="-1">原文 <a class="header-anchor" href="#原文-8" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',83)),t(g,{sections:i(L),glossary:d,"default-mode":"classic","aria-label":"让王·ninth 原文"},null,8,["sections"]),a[30]||(a[30]=n("h3",{id:"字词释义-8",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-8","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i($)},null,8,["items"]),a[31]||(a[31]=n("h3",{id:"逐句导读-7",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-7","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(J)},null,8,["lines"]),a[32]||(a[32]=u('<h3 id="深入解读-8" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-8" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、两种生活并置-外在差距先进入视野" tabindex="-1">一、两种生活并置：外在差距先进入视野 <a class="header-anchor" href="#一、两种生活并置-外在差距先进入视野" aria-label="Permalink to &quot;一、两种生活并置：外在差距先进入视野&quot;">​</a></h4><p>原宪居室狭小，门窗简陋，上漏下湿，衣履与手杖也显出困窘；子贡则乘大马、衣着讲究，高车甚至不能进入狭巷。</p><p>这种对照先让读者看见：如果只按车马衣饰判断，原宪很容易被看作失败者。</p><p>但外在差距不能直接证明子贡的钱财都是不义所得，也不能证明原宪的贫困本身就是德性的原因。后面的问答，才是对评价尺度的检验。</p><p>“二室”“𫄳履”涉及断句与字形疑难，具体形制不强定；居处与衣履简陋的叙事方向则较明确。</p><h4 id="二、贫与病-承认缺乏-改正分类" tabindex="-1">二、贫与病：承认缺乏，改正分类 <a class="header-anchor" href="#二、贫与病-承认缺乏-改正分类" aria-label="Permalink to &quot;二、贫与病：承认缺乏，改正分类&quot;">​</a></h4><blockquote><p>无财谓之贫，学而不能行谓之病。今宪贫也，非病也。</p></blockquote><table tabindex="0"><thead><tr><th>状态</th><th>原宪的定义</th></tr></thead><tbody><tr><td>贫</td><td>缺少财物</td></tr><tr><td>病</td><td>有所学，却不能实践</td></tr></tbody></table><p>原宪承认自己贫，没有用精神上的说法否认实际缺乏。但他不接受因为缺少财物，就判定其所学与人生失败。</p><p><strong>物质处境与实践所学的能力，不能直接画等号。</strong></p><p>“非病”也不是身体检查结论，不能译成身体完全健康、贫困没有任何身体代价。</p><h4 id="三、学而能行-内在尺度并非只有自我感觉" tabindex="-1">三、学而能行：内在尺度并非只有自我感觉 <a class="header-anchor" href="#三、学而能行-内在尺度并非只有自我感觉" aria-label="Permalink to &quot;三、学而能行：内在尺度并非只有自我感觉&quot;">​</a></h4><p>原宪不只说自己觉得快乐，而是以“行”作为尺度：所学是否落实于行为，是否因迎合、私利而背离所学。</p><p>因而，本段不是把所有外在评价换成主观满意，而是要求知识与实践之间的相应。</p><p>原文未展示原宪全部所学与日常行为，“非病”仍是对话中的自我说明，不必扩成对其人生每一方面的全面证明。</p><h4 id="四、行、友、学、教-反省动机与方式" tabindex="-1">四、行、友、学、教：反省动机与方式 <a class="header-anchor" href="#四、行、友、学、教-反省动机与方式" aria-label="Permalink to &quot;四、行、友、学、教：反省动机与方式&quot;">​</a></h4><blockquote><p>希世而行，比周而友，学以为人，教以为己。</p></blockquote><table tabindex="0"><thead><tr><th>活动</th><th>所批评的偏转</th></tr></thead><tbody><tr><td>行事</td><td>为迎合世俗而行</td></tr><tr><td>交友</td><td>结党偏私、相互依附</td></tr><tr><td>学习</td><td>为取悦、炫示于人</td></tr><tr><td>教人</td><td>以自己的获利为中心</td></tr></tbody></table><p>行、友、学、教本身没有被否定；被检验的是它们如何受外在评价与私利支配。</p><p>“学以为人”不能按现代正面语义理解为帮助别人；“教以为己”也不能被扩大为所有教学报酬都不正当。</p><h4 id="五、仁义与排场-名号不自动保证正当" tabindex="-1">五、仁义与排场：名号不自动保证正当 <a class="header-anchor" href="#五、仁义与排场-名号不自动保证正当" aria-label="Permalink to &quot;五、仁义与排场：名号不自动保证正当&quot;">​</a></h4><p>“仁义之慝”将美好名号与潜藏的不正并置，“舆马之饰”则指向外在形象与排场。</p><p>两者使人反省：被认可的形象，是否掩盖了实践偏差？</p><p>但不能据此断言原宪在逐项指控子贡确实犯了全部过错。故事写子贡有愧色，形成反省效果；对其完整人生的审判超出了本段。</p><h3 id="本段要点-7" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-7" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p><strong>财物缺乏需要被承认，却不能代替对实践所学的判断。贫困不是德性的保证，富贵也不是不正当的自动证明。</strong></p><h2 id="十、曾子贫居·困苦、独立与三种忘" tabindex="-1">十、曾子贫居·困苦、独立与三种忘 <a class="header-anchor" href="#十、曾子贫居·困苦、独立与三种忘" aria-label="Permalink to &quot;十、曾子贫居·困苦、独立与三种忘&quot;">​</a></h2><h3 id="原文-9" tabindex="-1">原文 <a class="header-anchor" href="#原文-9" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',29)),t(g,{sections:i(U),glossary:d,"default-mode":"classic","aria-label":"让王·tenth 原文"},null,8,["sections"]),a[33]||(a[33]=n("h3",{id:"字词释义-9",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-9","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(W)},null,8,["items"]),a[34]||(a[34]=n("h3",{id:"逐句导读-8",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-8","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(F)},null,8,["lines"]),a[35]||(a[35]=u('<h3 id="深入解读-9" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-9" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、困窘写得具体-不能以精神力量抹掉苦难" tabindex="-1">一、困窘写得具体：不能以精神力量抹掉苦难 <a class="header-anchor" href="#一、困窘写得具体-不能以精神力量抹掉苦难" aria-label="Permalink to &quot;一、困窘写得具体：不能以精神力量抹掉苦难&quot;">​</a></h4><p>曾子的衣袍破旧、面容不佳、手足胼胝，数日不能举火；衣冠鞋履稍加整理，就显出断裂与破损。</p><p>这些描写具有集中强化的效果，不必将“三日”“十年”当作经过核验的生活统计，但严重物质困窘的方向明确。</p><p>后面的歌唱不会使这些需要消失。原文不是说有道者不饥饿、不需衣食，而是表现困苦未能完全支配其志。</p><h4 id="二、声若金石-破损与不屈的反差" tabindex="-1">二、声若金石：破损与不屈的反差 <a class="header-anchor" href="#二、声若金石-破损与不屈的反差" aria-label="Permalink to &quot;二、声若金石：破损与不屈的反差&quot;">​</a></h4><blockquote><p>声满天地，若出金石。</p></blockquote><p>前面写衣物一动便破，后面写声音铿锵有力，形成身体处境与精神力量的反差。</p><p>《商颂》的具体篇目没有标明，不强行补出某首作为唯一解释。</p><p>曾子不只以羞愧、屈服或求取富贵回应贫困，但弦歌也不能成为现实中替代食物与照料的方法。</p><h4 id="三、不得臣、不得友-权位不自动取得认同" tabindex="-1">三、不得臣、不得友：权位不自动取得认同 <a class="header-anchor" href="#三、不得臣、不得友-权位不自动取得认同" aria-label="Permalink to &quot;三、不得臣、不得友：权位不自动取得认同&quot;">​</a></h4><blockquote><p>天子不得臣，诸侯不得友。</p></blockquote><p>曾子虽贫困，却不是谁能提供富贵，就能将他纳入自己设定的关系。</p><p>“不得友”不等于拒绝所有友谊，而是说诸侯身份不自动取得其交往与认同。</p><p>原文没有具体聘请过程，不补成某位天子、诸侯亲自来访而遭拒的史实。</p><h4 id="四、三种忘-各有侧重-也保留张力" tabindex="-1">四、三种忘：各有侧重，也保留张力 <a class="header-anchor" href="#四、三种忘-各有侧重-也保留张力" aria-label="Permalink to &quot;四、三种忘：各有侧重，也保留张力&quot;">​</a></h4><blockquote><p>养志者忘形，养形者忘利，致道者忘心矣。</p></blockquote><table tabindex="0"><thead><tr><th>所养或所达</th><th>所忘</th><th>可把握的方向</th></tr></thead><tbody><tr><td>志</td><td>形</td><td>不让形体处境完全压倒志向</td></tr><tr><td>形</td><td>利</td><td>不为逐利而损伤身体</td></tr><tr><td>道</td><td>心</td><td>松开执着计较之心</td></tr></tbody></table><p>“养志者忘形”与前文“不以利累形”不是完全同义：前者突出志，后者警惕利益伤身。</p><p>不将忘形改写成精心保养身体，也不推成故意毁伤身体；不将忘心解释为失去意识或停止思考。</p><p>三句可以分别理解，不必排列成人人依次完成的修炼阶段。</p><h3 id="本段要点-8" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-8" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p><strong>困窘可以不完全支配志向，却仍然需要现实的衣食与照料。精神独立不等于身体没有代价。</strong></p><h2 id="十一、颜回不仕·知足、自得与行修于内" tabindex="-1">十一、颜回不仕·知足、自得与行修于内 <a class="header-anchor" href="#十一、颜回不仕·知足、自得与行修于内" aria-label="Permalink to &quot;十一、颜回不仕·知足、自得与行修于内&quot;">​</a></h2><h3 id="原文-10" tabindex="-1">原文 <a class="header-anchor" href="#原文-10" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',25)),t(g,{sections:i(H),glossary:d,"default-mode":"classic","aria-label":"让王·eleventh 原文"},null,8,["sections"]),a[36]||(a[36]=n("h3",{id:"字词释义-10",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-10","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(M)},null,8,["items"]),a[37]||(a[37]=n("h3",{id:"逐句导读-9",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-9","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(Q)},null,8,["lines"]),a[38]||(a[38]=u('<h3 id="深入解读-10" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-10" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、四项足以-自得有物质基础" tabindex="-1">一、四项足以：自得有物质基础 <a class="header-anchor" href="#一、四项足以-自得有物质基础" aria-label="Permalink to &quot;一、四项足以：自得有物质基础&quot;">​</a></h4><p>颜回不否认家贫，却说明：</p><ul><li>田地足以供给粥食；</li><li>田地足以供给丝麻；</li><li>弹琴足以自娱；</li><li>所学之道足以自乐。</li></ul><p>他不是一无所有，而是已有条件足以支持自己的所需。这与曾子的极端困窘不同，不能将三人都讲成完全没有资源、只凭精神生活。</p><p>古代亩制与现代不同，不直接按市亩换算其土地规模；“𫗞粥”也不强定为精确食谱。</p><h4 id="二、不愿仕-官位不是生活成立的唯一途径" tabindex="-1">二、不愿仕：官位不是生活成立的唯一途径 <a class="header-anchor" href="#二、不愿仕-官位不是生活成立的唯一途径" aria-label="Permalink to &quot;二、不愿仕：官位不是生活成立的唯一途径&quot;">​</a></h4><p>颜回在回答开头、结尾都说不愿仕。他说明的是自己的需要与愿望，而非首先否定所有仕途。</p><p>衣食有所供给，琴与所学有所自乐，所以不需要以官位补足生活。</p><p>不能据此推出出仕者必不知足、学道者一概不能承担公共事务，或所有人必须采用颜回的生活需求。</p><h4 id="三、知足、自得、行修-三个不同的尺度" tabindex="-1">三、知足、自得、行修：三个不同的尺度 <a class="header-anchor" href="#三、知足、自得、行修-三个不同的尺度" aria-label="Permalink to &quot;三、知足、自得、行修：三个不同的尺度&quot;">​</a></h4><table tabindex="0"><thead><tr><th>表述</th><th>重心</th></tr></thead><tbody><tr><td>知足者，不以利自累</td><td>欲求有其尺度，不被更多利益不断牵引</td></tr><tr><td>审自得者，失之而不惧</td><td>内在把握不完全依外在所得维持</td></tr><tr><td>行修于内者，无位而不怍</td><td>行为修养不以官位作为唯一证明</td></tr></tbody></table><p>三句彼此相连，却不是重复。</p><p>“失之而不惧”表达不完全受得失支配的境地，不等于所有失去都没有痛苦，更不能用来责备遭受灾难者。</p><h4 id="四、诵之久而后见-实践使知识重新获得分量" tabindex="-1">四、诵之久而后见：实践使知识重新获得分量 <a class="header-anchor" href="#四、诵之久而后见-实践使知识重新获得分量" aria-label="Permalink to &quot;四、诵之久而后见：实践使知识重新获得分量&quot;">​</a></h4><blockquote><p>丘诵之久矣，今于回而后见之，是丘之得也。</p></blockquote><p>熟记道理，与看见道理在生活中成立，不是同一件事。</p><p>颜回不仅被老师肯定，也使老师获得新的领会。理解不只是老师传授、学生接受；学生的实际生活也能使已有知识获得新的分量。</p><p>这与原宪“学而不能行谓之病”相互照明，但对话角色与论述重点仍不同。</p><h2 id="十二、公子牟身隐心仕·未能自胜与重伤" tabindex="-1">十二、公子牟身隐心仕·未能自胜与重伤 <a class="header-anchor" href="#十二、公子牟身隐心仕·未能自胜与重伤" aria-label="Permalink to &quot;十二、公子牟身隐心仕·未能自胜与重伤&quot;">​</a></h2><h3 id="原文-11" tabindex="-1">原文 <a class="header-anchor" href="#原文-11" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',21)),t(g,{sections:i(X),glossary:d,"default-mode":"classic","aria-label":"让王·twelfth 原文"},null,8,["sections"]),a[39]||(a[39]=n("h3",{id:"字词释义-11",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-11","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(Y)},null,8,["items"]),a[40]||(a[40]=n("h3",{id:"逐句导读-10",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-10","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(Z)},null,8,["lines"]),a[41]||(a[41]=u('<h3 id="深入解读-11" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-11" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、身隐心未隐-位置改变不等于欲求改变" tabindex="-1">一、身隐心未隐：位置改变不等于欲求改变 <a class="header-anchor" href="#一、身隐心未隐-位置改变不等于欲求改变" aria-label="Permalink to &quot;一、身隐心未隐：位置改变不等于欲求改变&quot;">​</a></h4><blockquote><p>身在江海之上，心居乎魏阙之下，奈何？</p></blockquote><p>公子牟身体离开朝廷，内心却仍向往那里。外在退隐与内在放下没有同步发生。</p><p>这进一步检验前面的辞让与离去：离开位置、拒绝身份、改变生活形式，都不自动意味着心已自得。</p><p>他没有掩饰不一致，而是直接请问。困难不在于不知道自己有欲求，而在于知道之后仍不能化解。</p><h4 id="二、重生则利轻-调整分量-不只命令停止想要" tabindex="-1">二、重生则利轻：调整分量，不只命令停止想要 <a class="header-anchor" href="#二、重生则利轻-调整分量-不只命令停止想要" aria-label="Permalink to &quot;二、重生则利轻：调整分量，不只命令停止想要&quot;">​</a></h4><blockquote><p>重生。重生则利轻。</p></blockquote><p>瞻子首先延续尊生尺度：看重生命，利禄便不再占据同样大的分量。</p><p>这不是先宣布朝廷毫无价值，而是检验是否为了身份与利禄，使生命、心神持续受损。</p><p>相较之下变轻，与彻底消除一切利益需求，是不同的要求。</p><h4 id="三、虽知而未能-认识尚未成为真实状态" tabindex="-1">三、虽知而未能：认识尚未成为真实状态 <a class="header-anchor" href="#三、虽知而未能-认识尚未成为真实状态" aria-label="Permalink to &quot;三、虽知而未能：认识尚未成为真实状态&quot;">​</a></h4><blockquote><p>虽知之，未能自胜也。</p></blockquote><p>知道应当重生，并不自动具有改变欲求的力量。</p><p>如果只是再重复“应该放下”，未必能处理他的困难。原文没有简单责备他不坚定，而是转向讨论尚不能自胜时如何避免再伤。</p><p>尚未自得的人，不宜只靠模仿已自得者的生活形式证明自己。</p><h4 id="四、则从与重伤-不以强制伪装已经做到" tabindex="-1">四、则从与重伤：不以强制伪装已经做到 <a class="header-anchor" href="#四、则从与重伤-不以强制伪装已经做到" aria-label="Permalink to &quot;四、则从与重伤：不以强制伪装已经做到&quot;">​</a></h4><blockquote><p>不能自胜则从，神无恶乎！<br> 不能自胜而强不从者，此之谓重伤。</p></blockquote><p>一种常见理解是：眼下不能克服欲求，就暂顺其所欲，避免心神再陷入厌苦与冲突。</p><p>但原文未说明是否返回朝廷、怎样调整生活，以及哪些欲求可以顺应，不能补成确定行动方案。</p><p>更不能推广为任何难以克服的欲望都应实行。</p><p>“重伤”可联系双重损伤理解：内心仍被利禄牵引，又强迫自己表现得完全不受牵引，欲求未解而再添痛苦。</p><p>这是帮助理解的展开，不是原文列出的现代心理机制，也不等于所有自我约束、行为边界都应取消。</p><h4 id="五、未至道而有其意-承认未完成的努力" tabindex="-1">五、未至道而有其意：承认未完成的努力 <a class="header-anchor" href="#五、未至道而有其意-承认未完成的努力" aria-label="Permalink to &quot;五、未至道而有其意：承认未完成的努力&quot;">​</a></h4><blockquote><p>虽未至乎道，可谓有其意矣！</p></blockquote><p>原文没有说公子牟已经至道，却也不因其放不下，就把退隐与求问全部判为虚伪。</p><p>大国公子离开原有优裕与身份，叙述者认为较布衣更难。理解努力需要看原有处境，不只看最后做到多少。</p><p>这不是出身越贵境界越高，也不是永久免于改变的理由。原文同时保留：<strong>尚未达到，却已有其意。</strong></p><h3 id="本段要点-9" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-9" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p>知道、做到与表现成已经做到，必须分开。重生既警惕逐利伤身，也警惕以强制维持理想形象而再伤自身。</p><h2 id="十三、孔子困于陈蔡·穷通于道与临难不失德" tabindex="-1">十三、孔子困于陈蔡·穷通于道与临难不失德 <a class="header-anchor" href="#十三、孔子困于陈蔡·穷通于道与临难不失德" aria-label="Permalink to &quot;十三、孔子困于陈蔡·穷通于道与临难不失德&quot;">​</a></h2><h3 id="原文-12" tabindex="-1">原文 <a class="header-anchor" href="#原文-12" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',32)),t(g,{sections:i(aa),glossary:d,"default-mode":"classic","aria-label":"让王·thirteenth 原文"},null,8,["sections"]),a[42]||(a[42]=n("h3",{id:"字词释义-12",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-12","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(na)},null,8,["items"]),a[43]||(a[43]=n("h3",{id:"逐句导读-11",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-11","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(ta)},null,8,["lines"]),a[44]||(a[44]=u('<h3 id="深入解读-12" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-12" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、真实困境与弦歌并置" tabindex="-1">一、真实困境与弦歌并置 <a class="header-anchor" href="#一、真实困境与弦歌并置" aria-label="Permalink to &quot;一、真实困境与弦歌并置&quot;">​</a></h4><p>数日不得正常饮食，野菜汤没有粮食，面容疲惫，身处围困：身体困苦先被充分写出。</p><p>弦歌与后面对“穷”的重新解释，都不能被译成没有挨饿、没有疲惫、没有危险。</p><p>故事讨论的是：<strong>这些遭遇是否足以证明道与德已经失败？</strong></p><h4 id="二、弟子的质疑-受挫是否必须羞愧" tabindex="-1">二、弟子的质疑：受挫是否必须羞愧 <a class="header-anchor" href="#二、弟子的质疑-受挫是否必须羞愧" aria-label="Permalink to &quot;二、弟子的质疑：受挫是否必须羞愧&quot;">​</a></h4><blockquote><p>君子之无耻也若此乎？</p></blockquote><p>子路、子贡列举接连受挫，将持续弦歌理解为不知羞耻，而不是不失所守。</p><p>同一个动作因评价尺度不同，得到不同解释。这与“无位而不怍”形成联系：外在受挫，是否必然要求羞愧？</p><p>不必据此断言二人完全不关心老师，或永远不能理解。故事写此时的局限，也写后面的变化。</p><p>颜回“无以应”同样不能被当作全面失道。前一故事中的肯定，不应成为人物永久不变的境界档案。</p><h4 id="三、通穷于道-改变评价尺度-不取消现实" tabindex="-1">三、通穷于道：改变评价尺度，不取消现实 <a class="header-anchor" href="#三、通穷于道-改变评价尺度-不取消现实" aria-label="Permalink to &quot;三、通穷于道：改变评价尺度，不取消现实&quot;">​</a></h4><blockquote><p>君子通于道之谓通，穷于道之谓穷。</p></blockquote><table tabindex="0"><thead><tr><th>层面</th><th>所问的问题</th></tr></thead><tbody><tr><td>外在穷通</td><td>衣食、处境、政治遭遇是否顺利</td></tr><tr><td>于道穷通</td><td>所守是否受阻，行为是否失德</td></tr></tbody></table><p>外在不顺与内在失守，不能直接画等号。</p><p>但这不是外在条件毫无意义，也不是自称通于道，就可以拒绝全部批评。下文“内省”“不失其德”仍保留实践检验。</p><h4 id="四、仁义与内省-坚持并非免于反观" tabindex="-1">四、仁义与内省：坚持并非免于反观 <a class="header-anchor" href="#四、仁义与内省-坚持并非免于反观" aria-label="Permalink to &quot;四、仁义与内省：坚持并非免于反观&quot;">​</a></h4><blockquote><p>今丘抱仁义之道以遭乱世之患，其何穷之为？<br> 故内省而不穷于道，临难而不失其德。</p></blockquote><p>此处明确肯定仁义与守德，不能因其他篇章批评仁义，就将本句强读为必然讽刺；也不能据此认定全书始终只有一种仁义评价。</p><p>遭乱世之患，与自身失道，是不同的问题。成败不是判断所守正当与否的唯一证据。</p><p>“内省”使坚持不止于宣告自己正确。不过，原文未给出检验每项行为的完整标准，这仍是故事中的价值主张，不是对全部行动已完成的外部证明。</p><h4 id="五、松柏与霜雪-在困境中领会-不是追求困境" tabindex="-1">五、松柏与霜雪：在困境中领会，不是追求困境 <a class="header-anchor" href="#五、松柏与霜雪-在困境中领会-不是追求困境" aria-label="Permalink to &quot;五、松柏与霜雪：在困境中领会，不是追求困境&quot;">​</a></h4><blockquote><p>天寒既至，霜雪既降，吾是以知松柏之茂也。</p></blockquote><p>松柏比喻临难不失其德，使已发生的困境成为辨认所守的情境。</p><p>必须区分：在困境中看见价值，不等于为了证明价值而主动制造困境。</p><p>“陈蔡之隘，于丘其幸乎”是在已遭遇的困厄中重新领会自身，不是要求人人以饥饿、围困检验德性。</p><h4 id="六、理解先改变-困境未必立刻解除" tabindex="-1">六、理解先改变，困境未必立刻解除 <a class="header-anchor" href="#六、理解先改变-困境未必立刻解除" aria-label="Permalink to &quot;六、理解先改变，困境未必立刻解除&quot;">​</a></h4><p>对话后，孔子重新弦歌，子路执盾而舞，子贡惊叹此前所知有限。</p><p>原文没有说粮食立即充足、围困立即解除。变化首先发生在对处境的理解与回应中。</p><p>“不知天之高、地之下”可以联系对自身识见的惊叹，不必解释为突然获得新的天文地理知识。</p><h4 id="七、所乐非穷通-不是贫困本身值得喜爱" tabindex="-1">七、所乐非穷通：不是贫困本身值得喜爱 <a class="header-anchor" href="#七、所乐非穷通-不是贫困本身值得喜爱" aria-label="Permalink to &quot;七、所乐非穷通：不是贫困本身值得喜爱&quot;">​</a></h4><blockquote><p>穷亦乐，通亦乐，所乐非穷通也。</p></blockquote><p>三句须合看。只摘“穷亦乐”，容易误成越穷越快乐；原文随即说明快乐根源不在穷通本身。</p><p>可以理解为所守、所得之道不完全依赖外在境遇维持。</p><p>这是理想境地的表达，不能用来要求所有受苦者立即快乐，或责备其悲伤。</p><h4 id="八、寒暑风雨-境遇不再成为全部尺度" tabindex="-1">八、寒暑风雨：境遇不再成为全部尺度 <a class="header-anchor" href="#八、寒暑风雨-境遇不再成为全部尺度" aria-label="Permalink to &quot;八、寒暑风雨：境遇不再成为全部尺度&quot;">​</a></h4><blockquote><p>则穷通为寒暑风雨之序矣。</p></blockquote><p>穷通仍有变化、不适，也不完全受个人意志控制，却不再决定全部内在评价。</p><p>比喻不能抹去战争与围困的人为原因，更不能取消责任辨认。</p><p>末句将视野扩展到许由、共伯，但未展开完整经历，不将相关传说补作本段明说。</p><h2 id="九至十三段·阶段性脉络" tabindex="-1">九至十三段·阶段性脉络 <a class="header-anchor" href="#九至十三段·阶段性脉络" aria-label="Permalink to &quot;九至十三段·阶段性脉络&quot;">​</a></h2><h3 id="思想对读" tabindex="-1">思想对读 <a class="header-anchor" href="#思想对读" aria-label="Permalink to &quot;思想对读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>内容</th><th>可参照篇章或故事</th><th>联系与区别</th></tr></thead><tbody><tr><td>原宪贫而非病</td><td>本篇孔子辨穷通</td><td>外在困窘不自动等于内在受阻，定义不同</td></tr><tr><td>学而不能行</td><td>《寓言》对年齿与识见的检验</td><td>身份、知识积累不自动证明实际理解</td></tr><tr><td>曾子贫居</td><td>《寓言》曾子再仕</td><td>同一人物承担不同问题，不据一则固定永久境界</td></tr><tr><td>颜回知足不仕</td><td>本篇善卷自得</td><td>不以权位补足生活，具体条件不同</td></tr><tr><td>知足、不以利自累</td><td>本篇不以利累形、宝珠弹雀</td><td>限制利益追求对自身的支配</td></tr><tr><td>孔子从颜回获得领会</td><td>《寓言》孔子六十化</td><td>理解不因老师身份而终结</td></tr><tr><td>公子牟身隐心仕</td><td>《寓言》心有所悬</td><td>外在改变不自动解除内在悬系</td></tr><tr><td>重生则利轻</td><td>本篇子华子辨轻重</td><td>重新安排生命与利益的分量</td></tr><tr><td>未能自胜而有其意</td><td>本篇颜回不仕</td><td>尚未做到与已经自得，应分别理解</td></tr><tr><td>陈蔡弦歌</td><td>本篇曾子贫居</td><td>困苦未能完全支配所守</td></tr><tr><td>孔子困于陈蔡</td><td>《山木》等相关叙述</td><td>同题材可有不同侧重，不拼成唯一历史实录</td></tr></tbody></table><blockquote><p>思想参照用于比较，不据相似表达认定完全同义，也不将不同故事编成人人必经的修炼次序。</p></blockquote><h3 id="实践参照" tabindex="-1">实践参照 <a class="header-anchor" href="#实践参照" aria-label="Permalink to &quot;实践参照&quot;">​</a></h3><p>以下属于现代阅读引申，不是原文直接规定的生活标准或心理治疗方案。</p><ul><li>**分开资源与全部价值。**经济条件说明部分处境，不能单独裁定实践、能力与人格。</li><li>**不以懂道理代替行为检验。**知道什么、做到什么，仍需分别辨认。</li><li>**知足可以有个人尺度。**不以同一种消费水平、职业身份定义所有人的成功。</li><li>**尊重精神独立，也承认物质保障。**求助不必羞耻，内在坚持与现实解困可以并行。</li><li>**承认知道却做不到。**这不必立即判为虚伪，也可能意味着需要调整条件与方法。</li><li>**不以理想形象不断攻击自己。**改变需要边界和实际办法，不等于顺从所有欲望。</li><li>**不让外在失败包办评价。**同时检验环境、实际行为、理由与方法，而非只责备自身或只归咎外界。</li><li>**寻找意义，不等于赞美困境。**可以肯定不失其德，同时改善衣食、解除危险、寻求支持。</li></ul><h3 id="核心句对照" tabindex="-1">核心句对照 <a class="header-anchor" href="#核心句对照" aria-label="Permalink to &quot;核心句对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>核心句</th><th>阅读重点</th><th>应避免的误读</th></tr></thead><tbody><tr><td>今宪贫也，非病也</td><td>财物缺乏与不能行所学不同</td><td>贫困没有身体代价；越穷越有德</td></tr><tr><td>学而不能行谓之病</td><td>内在尺度包含实践检验</td><td>自觉快乐便足以证明一切</td></tr><tr><td>养志者忘形，养形者忘利，致道者忘心</td><td>三种忘各有所指</td><td>不需衣食；故意伤身；停止思考</td></tr><tr><td>天子不得臣，诸侯不得友</td><td>权位不自动取得支配与认同</td><td>拒绝所有友谊</td></tr><tr><td>足以给𫗞粥；足以为丝麻</td><td>自得包含生活条件</td><td>完全无资源而凭精神生活</td></tr><tr><td>知足者，不以利自累</td><td>所需有其尺度</td><td>所有出仕者都不知足</td></tr><tr><td>行修于内者，无位而不怍</td><td>官位不是修养的唯一证明</td><td>富贵官位自动等于内在失败</td></tr><tr><td>丘诵之久矣，今于回而后见之</td><td>熟记与实践不同</td><td>老师的理解已经无需变化</td></tr><tr><td>身在江海之上，心居乎魏阙之下</td><td>退隐不自动解除欲求</td><td>隐居形式等于内在自在</td></tr><tr><td>虽知之，未能自胜</td><td>知识尚未落实为状态</td><td>未做到便毫无价值</td></tr><tr><td>不能自胜而强不从，此之谓重伤</td><td>避免以强制再伤自身</td><td>所有约束都伤身；所有欲望都应实行</td></tr><tr><td>通于道之谓通，穷于道之谓穷</td><td>外在遭遇与于道失守不同</td><td>饥饿不真实；外界条件无意义</td></tr><tr><td>内省而不穷于道</td><td>坚持仍须检验</td><td>自称有道便免于批评</td></tr><tr><td>吾是以知松柏之茂也</td><td>已发生的困难使所守显现</td><td>应主动制造困境证明德性</td></tr><tr><td>所乐非穷通也</td><td>快乐根源不在穷通本身</td><td>越穷越快乐；受苦者不应悲伤</td></tr></tbody></table><h2 id="十四、北人无择·拒辱与生命损失" tabindex="-1">十四、北人无择·拒辱与生命损失 <a class="header-anchor" href="#十四、北人无择·拒辱与生命损失" aria-label="Permalink to &quot;十四、北人无择·拒辱与生命损失&quot;">​</a></h2><h3 id="原文-13" tabindex="-1">原文 <a class="header-anchor" href="#原文-13" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',51)),t(g,{sections:i(ia),glossary:d,"default-mode":"classic","aria-label":"让王·北人无择 原文"},null,8,["sections"]),a[45]||(a[45]=n("h3",{id:"字词释义-13",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-13","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(ea)},null,8,["items"]),a[46]||(a[46]=n("h3",{id:"语句导读-1",tabindex:"-1"},[e("语句导读 "),n("a",{class:"header-anchor",href:"#语句导读-1","aria-label":'Permalink to "语句导读"'},"​")],-1)),t(h,{lines:i(ra)},null,8,["lines"]),a[47]||(a[47]=u('<h3 id="深入解读-13" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-13" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、拒绝重心-不是自身能力-而是授位者的行为" tabindex="-1">一、拒绝重心：不是自身能力，而是授位者的行为 <a class="header-anchor" href="#一、拒绝重心-不是自身能力-而是授位者的行为" aria-label="Permalink to &quot;一、拒绝重心：不是自身能力，而是授位者的行为&quot;">​</a></h4><p>北人无择没有先说自己有病、无暇、才智不足，或日常生活已经足够。他直接评价舜的政治道路。</p><blockquote><p>居于畎亩之中，而游尧之门。</p></blockquote><p>在他的判断中，由田间进入尧的政治关系，不是当然值得赞美的升进。</p><p>但原文没有交代舜的全部动机，不能补成舜必定从一开始就蓄谋夺取天下。</p><p><strong>人物不认可一条政治道路，与这条道路的全部动机已经得到证明，是两回事。</strong></p><h4 id="二、让位也可能被理解为污及自身" tabindex="-1">二、让位也可能被理解为污及自身 <a class="header-anchor" href="#二、让位也可能被理解为污及自身" aria-label="Permalink to &quot;二、让位也可能被理解为污及自身&quot;">​</a></h4><blockquote><p>又欲以其辱行漫我。</p></blockquote><p>授位通常可能意味着信任、认可与辞让，北人无择却认为这会使自己与不认可的行为发生关系。</p><p>接受位置，可能同时意味着承认授位者、接续其安排或参与相关政治关系。这些是帮助理解的展开，不是原文逐项列举。</p><p>与善卷“子之不知余”相比，此处更严厉：善卷着重指出所需不被理解，北人无择则认为对方的行为会辱及自己。</p><h4 id="三、自投深渊-不能将毁身改写为肉身保全" tabindex="-1">三、自投深渊：不能将毁身改写为肉身保全 <a class="header-anchor" href="#三、自投深渊-不能将毁身改写为肉身保全" aria-label="Permalink to &quot;三、自投深渊：不能将毁身改写为肉身保全&quot;">​</a></h4><blockquote><p>因自投清泠之渊。</p></blockquote><p>这里明确写投水，不同于石户之农携家远避。拒绝从退出关系推进到生命损失。</p><p>若解释为保全人格或操守，需要说明这是价值意义上的理解，不能代替肉身未得保全的事实。</p><p>本段也没有单独明说这种死亡就是最高的道。人物的羞辱感、拒绝与死亡应当保留，不能用结局代替叙述者明确赞语。</p><h3 id="本段要点-10" tabindex="-1">本段要点 <a class="header-anchor" href="#本段要点-10" aria-label="Permalink to &quot;本段要点&quot;">​</a></h3><p><strong>贵重授位可能被受让者理解为污辱，但拒绝的立场与拒绝的生命后果仍须分开判断。</strong></p><h2 id="十五、卞随、瞀光拒位·所得来源与拒绝的生命代价" tabindex="-1">十五、卞随、瞀光拒位·所得来源与拒绝的生命代价 <a class="header-anchor" href="#十五、卞随、瞀光拒位·所得来源与拒绝的生命代价" aria-label="Permalink to &quot;十五、卞随、瞀光拒位·所得来源与拒绝的生命代价&quot;">​</a></h2><h3 id="原文-14" tabindex="-1">原文 <a class="header-anchor" href="#原文-14" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',21)),t(g,{sections:i(ga),glossary:d,"default-mode":"classic","aria-label":"让王·fifteenth 原文"},null,8,["sections"]),a[48]||(a[48]=n("h3",{id:"字词释义-14",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-14","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(da)},null,8,["items"]),a[49]||(a[49]=n("h3",{id:"逐句导读-12",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-12","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(oa)},null,8,["lines"]),a[50]||(a[50]=u('<h3 id="深入解读-14" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-14" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、非吾事也-先退出谋议" tabindex="-1">一、非吾事也：先退出谋议 <a class="header-anchor" href="#一、非吾事也-先退出谋议" aria-label="Permalink to &quot;一、非吾事也：先退出谋议&quot;">​</a></h4><p>汤询问伐桀，卞随与瞀光都说“非吾事也”；问谁可以参与，又回答“吾不知也”。</p><p>他们不只拒绝亲自行动，也不主动推荐人选。</p><p>“吾不知”在这里至少具有退出谋议的作用，不宜直接解释为对世事完全无知。后面的辞位，才进一步展开价值立场。</p><h4 id="二、伊尹何如-有限评价不是全面推荐" tabindex="-1">二、伊尹何如：有限评价不是全面推荐 <a class="header-anchor" href="#二、伊尹何如-有限评价不是全面推荐" aria-label="Permalink to &quot;二、伊尹何如：有限评价不是全面推荐&quot;">​</a></h4><blockquote><p>强力忍垢，吾不知其他也。</p></blockquote><p>瞀光只说明所知有限，不作全面评价。</p><p>“忍垢”可联系承受屈辱，也可能带有对政治污浊的警惕，解释仍有空间。</p><p>不能把这句话当作热情推荐，也不能据四个字审判伊尹全部人格。汤随后与伊尹谋伐桀，是汤的行动，不应倒推为瞀光已同意参与。</p><h4 id="三、拒谋之后又被让位-拒绝被安排成另一种人" tabindex="-1">三、拒谋之后又被让位：拒绝被安排成另一种人 <a class="header-anchor" href="#三、拒谋之后又被让位-拒绝被安排成另一种人" aria-label="Permalink to &quot;三、拒谋之后又被让位：拒绝被安排成另一种人&quot;">​</a></h4><blockquote><p>后之伐桀也谋乎我，必以我为贼也；胜桀而让我，必以我为贪也。</p></blockquote><p>卞随将询谋与让位连在一起理解：前者使自己被当作愿参与攻杀者，后者使自己被当作贪求胜利之利者。</p><p>他拒绝的不只是君位，也是不愿被安排成自己不认可的角色。</p><p>但“必以我为”是卞随的推断，不是原文另行证明的汤之内心判断。</p><p>前次“不参与”没有使他免于再次邀请，这也显示：<strong>授予者的郑重，不能自动取消受让者的拒绝。</strong></p><h4 id="四、汤的分工理由-古道仍然可以受到检验" tabindex="-1">四、汤的分工理由：古道仍然可以受到检验 <a class="header-anchor" href="#四、汤的分工理由-古道仍然可以受到检验" aria-label="Permalink to &quot;四、汤的分工理由：古道仍然可以受到检验&quot;">​</a></h4><blockquote><p>知者谋之，武者遂之，仁者居之，古之道也。</p></blockquote><p>汤提出谋划、完成与治理可以分工，因此未参与征伐的仁者仍可受位。</p><p>这是为授位合宜提供的一种理由，不是因为引用古道，讨论就必须结束。</p><p>瞀光随后正面检验这一安排。</p><h4 id="五、义、仁、廉-不以成功证明取得正当" tabindex="-1">五、义、仁、廉：不以成功证明取得正当 <a class="header-anchor" href="#五、义、仁、廉-不以成功证明取得正当" aria-label="Permalink to &quot;五、义、仁、廉：不以成功证明取得正当&quot;">​</a></h4><blockquote><p>废上，非义也；杀民，非仁也；人犯其难，我享其利，非廉也。</p></blockquote><table tabindex="0"><thead><tr><th>行为或关系</th><th>瞀光的尺度</th></tr></thead><tbody><tr><td>废黜原有君主</td><td>义</td></tr><tr><td>战争杀伤民众</td><td>仁</td></tr><tr><td>别人冒险，自己享有结果</td><td>廉</td></tr></tbody></table><p>他不因为征伐成功，就承认过程正当；也不因被称为仁者，就接受“仁者居之”。</p><p>但这些首先是人物对眼前征伐及授位关系的判断，不是全书对一切政权更替、战争与分工受益的统一裁定。</p><h4 id="六、所得来源-不只问自己是否配得" tabindex="-1">六、所得来源：不只问自己是否配得 <a class="header-anchor" href="#六、所得来源-不只问自己是否配得" aria-label="Permalink to &quot;六、所得来源：不只问自己是否配得&quot;">​</a></h4><blockquote><p>非其义者，不受其禄；无道之世，不践其土。</p></blockquote><p>瞀光不受一般禄利，更不愿居最高尊位。</p><p>与屠羊说相比，屠羊说主要辨认自己有无复国之功及施赏根据；瞀光还直接否定取得天下的行为与受利关系。</p><p><strong>我是否配得，与这份所得本身来自什么行为，是不同的检验。</strong></p><h4 id="七、投水结局-立场不能掩盖实际后果" tabindex="-1">七、投水结局：立场不能掩盖实际后果 <a class="header-anchor" href="#七、投水结局-立场不能掩盖实际后果" aria-label="Permalink to &quot;七、投水结局：立场不能掩盖实际后果&quot;">​</a></h4><p>卞随自投椆水而死，瞀光负石自沉。原文将死亡与“不忍”继续听闻、继续见到相连。</p><p>但退出关系在这里成为退出生命，不能与颜阖离去、善卷入山、石户之农远避混同。</p><p>若以保全本真或操守解释，应注明其价值意义；不能据此说生命没有损失。</p><h2 id="十六、伯夷叔齐·观周、拒盟与首阳之节" tabindex="-1">十六、伯夷叔齐·观周、拒盟与首阳之节 <a class="header-anchor" href="#十六、伯夷叔齐·观周、拒盟与首阳之节" aria-label="Permalink to &quot;十六、伯夷叔齐·观周、拒盟与首阳之节&quot;">​</a></h2><h3 id="原文-15" tabindex="-1">原文 <a class="header-anchor" href="#原文-15" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',37)),t(g,{sections:i(la),glossary:d,"default-mode":"classic","aria-label":"让王·sixteenth 原文"},null,8,["sections"]),a[51]||(a[51]=n("h3",{id:"字词释义-15",tabindex:"-1"},[e("字词释义 "),n("a",{class:"header-anchor",href:"#字词释义-15","aria-label":'Permalink to "字词释义"'},"​")],-1)),t(r,{items:i(sa)},null,8,["items"]),a[52]||(a[52]=n("h3",{id:"逐句导读-13",tabindex:"-1"},[e("逐句导读 "),n("a",{class:"header-anchor",href:"#逐句导读-13","aria-label":'Permalink to "逐句导读"'},"​")],-1)),t(h,{lines:i(ha)},null,8,["lines"]),a[53]||(a[53]=u('<h3 id="深入解读-15" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-15" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、似有道者-试往观焉-期待需要经过观察" tabindex="-1">一、似有道者，试往观焉：期待需要经过观察 <a class="header-anchor" href="#一、似有道者-试往观焉-期待需要经过观察" aria-label="Permalink to &quot;一、似有道者，试往观焉：期待需要经过观察&quot;">​</a></h4><p>“似”表示尚未确认，“观”表示需要实际了解。</p><p>伯夷叔齐起初对西方可能有道的政治生活抱有期待，并非预先拒绝一切朝廷与治理。后来的拒绝来自对所见的判断。</p><h4 id="二、礼遇、官位与盟誓-不能代替是否有道的判断" tabindex="-1">二、礼遇、官位与盟誓：不能代替是否有道的判断 <a class="header-anchor" href="#二、礼遇、官位与盟誓-不能代替是否有道的判断" aria-label="Permalink to &quot;二、礼遇、官位与盟誓：不能代替是否有道的判断&quot;">​</a></h4><p>武王派叔旦接待，以财富待遇、官职身份与盟约建立关系。</p><p>对周而言，这可能是礼遇与取信；对二人而言，却没有回答治理及取得天下的方式是否有道。</p><blockquote><p>此非吾所谓道也。</p></blockquote><p>受到尊重，不等于必须认同。二人随后说明具体差别，不只诉诸个人好恶。</p><h4 id="三、神农之治-尽责而不以此求利" tabindex="-1">三、神农之治：尽责而不以此求利 <a class="header-anchor" href="#三、神农之治-尽责而不以此求利" aria-label="Permalink to &quot;三、神农之治：尽责而不以此求利&quot;">​</a></h4><blockquote><p>时祀尽敬而不祈喜；其于人也，忠信尽治而无求焉。</p></blockquote><table tabindex="0"><thead><tr><th>关系</th><th>尽其责任</th><th>不以之求取</th></tr></thead><tbody><tr><td>祭祀</td><td>尽敬</td><td>福庆、好处</td></tr><tr><td>治人</td><td>忠信尽治</td><td>自身回报</td></tr></tbody></table><p>理想治理不是不行动，而是认真尽责，不把治理变成求利工具。</p><p>神农在这里是理想参照，不必当作已经核验的历史制度。</p><p>“乐与政为政，乐与治为治”存在训释差异，可与“无求”“不自利”合看，不强定为现代制度或唯一逐字译法。</p><h4 id="四、三个不以-不以他人困境成就自己" tabindex="-1">四、三个不以：不以他人困境成就自己 <a class="header-anchor" href="#四、三个不以-不以他人困境成就自己" aria-label="Permalink to &quot;四、三个不以：不以他人困境成就自己&quot;">​</a></h4><blockquote><p>不以人之坏自成也，不以人之卑自高也，不以遭时自利也。</p></blockquote><p>他人的毁败、低下与时势机会，不应只是自己的上升资本。</p><p>这不否认危机中的救助、修复与任事；所反对的是以他人困境为自我功业与私利服务。</p><h4 id="五、对周的批评-成功不能使过程免于检验" tabindex="-1">五、对周的批评：成功不能使过程免于检验 <a class="header-anchor" href="#五、对周的批评-成功不能使过程免于检验" aria-label="Permalink to &quot;五、对周的批评：成功不能使过程免于检验&quot;">​</a></h4><table tabindex="0"><thead><tr><th>所列行为</th><th>质疑方向</th></tr></thead><tbody><tr><td>上谋、行货</td><td>用谋略、财货推动安排</td></tr><tr><td>阻兵保威</td><td>凭恃武力维持威势</td></tr><tr><td>割牲立盟</td><td>以仪式保证信用</td></tr><tr><td>扬行说众</td><td>以展示取得悦服</td></tr><tr><td>杀伐要利</td><td>通过战争求取利益</td></tr></tbody></table><p>二人不因周已兴起，就免除对取天下过程的追问。</p><p>但这仍是故事中二人的鲜明批评。原文未提供双方完整辩论，也未逐项证明所有行动皆出于私利，应同时保留立场与证据限度。</p><p>前面的盟誓随后成为批评对象，尤其显示：<strong>仪式上的保证，不自动等于实际可信。</strong></p><p>“推乱以易暴”字句有疑难，批评方向则是二人不认可更替本身已经终结乱暴。不能扩大成任何政权更替都不正当。</p><h4 id="六、治世不避其任-参与与退出都有条件" tabindex="-1">六、治世不避其任：参与与退出都有条件 <a class="header-anchor" href="#六、治世不避其任-参与与退出都有条件" aria-label="Permalink to &quot;六、治世不避其任：参与与退出都有条件&quot;">​</a></h4><blockquote><p>遭治世不避其任，遇乱世不为苟存。</p></blockquote><p>前半句留下任事的可能，呼应起初前往观察。二人不拒绝所有共同事务，而是不认同眼前政治处境。</p><p>后半句又使生存不能成为唯一尺度：不因继续存活，就放弃所守、进入认为有辱的关系。</p><p>这与“不以天下易生”相接，却不保证在极端冲突中给出同一答案。</p><h4 id="七、洁吾行-拒绝参与不能认同的关系" tabindex="-1">七、洁吾行：拒绝参与不能认同的关系 <a class="header-anchor" href="#七、洁吾行-拒绝参与不能认同的关系" aria-label="Permalink to &quot;七、洁吾行：拒绝参与不能认同的关系&quot;">​</a></h4><blockquote><p>其并乎周以涂吾身也，不如避之，以洁吾行。</p></blockquote><p>守洁不仅是内心不赞同，还涉及是否接受身份、待遇与参与。</p><p>但不能无限推广为社会中只要存在不正，任何交往都会污染自身。本段讨论的是二人与周的具体政治关系。</p><h4 id="八、首阳饿死-结局不能倒推全部计划" tabindex="-1">八、首阳饿死：结局不能倒推全部计划 <a class="header-anchor" href="#八、首阳饿死-结局不能倒推全部计划" aria-label="Permalink to &quot;八、首阳饿死：结局不能倒推全部计划&quot;">​</a></h4><blockquote><p>二子北至于首阳之山，遂饿而死焉。</p></blockquote><p>原文写离开、至首阳、最终饿死，不像前两段明确写自投、自沉。</p><p>应分开守节离去、离去后死亡与预先以死亡为目标。第三项不能仅凭结局补出。</p><p>本段未详写饥饿原因，也未明写“不食周粟”“叩马而谏”。这些可以另作对读，不能替代这里的原文。</p><p>无论动机如何解释，生命未得保全的事实仍需保留。</p><h4 id="九、结尾疑难-独乐其志-不以高节经营声名" tabindex="-1">九、结尾疑难：独乐其志，不以高节经营声名 <a class="header-anchor" href="#九、结尾疑难-独乐其志-不以高节经营声名" aria-label="Permalink to &quot;九、结尾疑难：独乐其志，不以高节经营声名&quot;">​</a></h4><blockquote><p>苟可得已，则必不赖高节戾行，独乐其志，不事于世。</p></blockquote><p>“苟可得已”通常联系可以止、可以不取理解，不径译为能够得到富贵。</p><p>“不赖高节戾行”可联系不凭恃、标榜高节异行理解，但具体训释仍有分歧。</p><p>与“独乐其志”合看，可以得到一种贯通方向：辞富贵不以赢得更高声名为目的，而在持守所认同的志。这不是每个疑难字都已获得唯一解释。</p><h4 id="十、此二士之节也-肯定操守-不自动要求复制死亡" tabindex="-1">十、此二士之节也：肯定操守，不自动要求复制死亡 <a class="header-anchor" href="#十、此二士之节也-肯定操守-不自动要求复制死亡" aria-label="Permalink to &quot;十、此二士之节也：肯定操守，不自动要求复制死亡&quot;">​</a></h4><p>结尾有肯定二人操守的语气，不能无据将整段一概读为讽刺。</p><p>但须分开：</p><ul><li>肯定不苟取、不苟合；</li><li>肯定其每项具体判断；</li><li>肯定死亡本身；</li><li>要求所有人效仿其结局。</li></ul><p>第一项不能自动证明其余各项。</p><h3 id="开篇与结尾的照应" tabindex="-1">开篇与结尾的照应 <a class="header-anchor" href="#开篇与结尾的照应" aria-label="Permalink to &quot;开篇与结尾的照应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>开篇</th><th>结尾</th></tr></thead><tbody><tr><td>不以天下害生</td><td>不为苟存而弃守</td></tr><tr><td>日常生活已有自得</td><td>独乐其志</td></tr><tr><td>不需天下补足自己</td><td>不认可富贵背后的政治方式</td></tr><tr><td>远避后仍保留生活</td><td>离去后最终饿死</td></tr></tbody></table><p>共同线索是天下、富贵不能自动成为最高尺度；不同处则是生命与操守怎样排序仍有张力。</p><p><strong>全篇由尊生开篇，以二士之节收束，不能只保留其中一端。</strong></p><h2 id="全篇脉络·十六段阅读地图" tabindex="-1">全篇脉络·十六段阅读地图 <a class="header-anchor" href="#全篇脉络·十六段阅读地图" aria-label="Permalink to &quot;全篇脉络·十六段阅读地图&quot;">​</a></h2><p>以下是比较阅读中的结构整理，不是原文明列的章节纲目，也不是统一的修炼等级。</p><p><strong>天下虽重，不应自动伤生</strong><br> → <strong>供养之物不能反害所养</strong><br> → <strong>所得有用，仍需检验给予方式与承受条件</strong><br> → <strong>无功之赏、破例之利，也应辨明根据</strong><br> → <strong>贫困与无位，不自动等于内在失败</strong><br> → <strong>知道道理，不自动等于欲求已经化解</strong><br> → <strong>外在受挫，不自动等于穷于道</strong><br> → <strong>成功与富贵，不使取得过程免于检验</strong><br> → <strong>拒绝不认可的关系，可能保全独立，也可能造成生命损失</strong><br> → <strong>尊生、实践、义与操守需要合看，不能被压成无冲突的一句答案。</strong></p><table tabindex="0"><thead><tr><th>阅读区域</th><th>段落</th><th>主要问题</th></tr></thead><tbody><tr><td>天下与生命</td><td>第一至第四段</td><td>权位、土地值得付出什么生命代价？</td></tr><tr><td>聘请、赠予与赏赐</td><td>第五至第八段</td><td>为什么给，怎样给，我是否应受？</td></tr><tr><td>贫居与内在尺度</td><td>第九至第十一段</td><td>缺少外物是否就意味着失败？</td></tr><tr><td>知道、做到与所守</td><td>第十二至第十三段</td><td>尚未自得怎么办，外在困厄如何评价？</td></tr><tr><td>拒绝关系与守节代价</td><td>第十四至第十六段</td><td>所得来源是否合宜，拒绝又会失去什么？</td></tr></tbody></table><p>后一阅读区域不是对前一尺度的彻底取代。尊生没有因结尾守节而失效，守节也不能被全部改写为保命策略。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问-既然天下与富贵贵重-为什么仍可以不受" tabindex="-1">第一问｜既然天下与富贵贵重，为什么仍可以不受？ <a class="header-anchor" href="#第一问-既然天下与富贵贵重-为什么仍可以不受" aria-label="Permalink to &quot;第一问｜既然天下与富贵贵重，为什么仍可以不受？&quot;">​</a></h3><p>因为有价值，与应由我以这种方式接受，不是同一件事。</p><table tabindex="0"><thead><tr><th>辞受重心</th><th>代表故事</th><th>所检验的内容</th></tr></thead><tbody><tr><td>尊生、辨轻重</td><td>子州二人、子华子</td><td>代价是否伤生，所得与所用是否倒置</td></tr><tr><td>生活已有自得</td><td>善卷、颜回</td><td>是否真需权位补足生活</td></tr><tr><td>判断与关系风险</td><td>列子</td><td>施予者是否自知，赏罚依据是否可靠</td></tr><tr><td>功与辞受之义</td><td>屠羊说</td><td>是否有相应功劳、资格与合宜根据</td></tr><tr><td>行为及所得来源</td><td>北人无择、卞随、瞀光、伯夷叔齐</td><td>接受会进入什么关系，所得来自何种行为</td></tr></tbody></table><p>这是帮助比较的分类，各故事可能兼有多重理由。</p><p>屠羊说明确承认高位更贵、厚禄更富，却仍认为自己不应受。因此，本篇不靠否定富贵的一切价值来完成拒绝。</p><h3 id="第二问-不受、不仕-是否等于一概退出共同事务" tabindex="-1">第二问｜不受、不仕，是否等于一概退出共同事务？ <a class="header-anchor" href="#第二问-不受、不仕-是否等于一概退出共同事务" aria-label="Permalink to &quot;第二问｜不受、不仕，是否等于一概退出共同事务？&quot;">​</a></h3><p>不是。</p><p>“可以托天下”与“遭治世不避其任”都留下任事的可能。不争求位置，与没有能力、不愿承担或认为眼前安排不合宜，是不同的状态。</p><p>应区分：</p><ul><li>为身份、利益争求位置；</li><li>因合宜条件与责任任事；</li><li>不认可眼前安排而拒绝；</li><li>生活已有所需，选择其他道路。</li></ul><p>也不能反过来强迫辞让者接受：正因为不想要，所以必须承担。王子搜被迎立，使适任评价与受任意愿之间的冲突清楚显现。</p><p><strong>给予者的善意、郑重与认可，不能代替受让者的实际判断。</strong></p><h3 id="第三问-尊生与守节怎样相连-又为什么不能完全统一" tabindex="-1">第三问｜尊生与守节怎样相连，又为什么不能完全统一？ <a class="header-anchor" href="#第三问-尊生与守节怎样相连-又为什么不能完全统一" aria-label="Permalink to &quot;第三问｜尊生与守节怎样相连，又为什么不能完全统一？&quot;">​</a></h3><p>二者都反对外物未经检验便占据最高位置，但使用的尺度不完全相同。</p><table tabindex="0"><thead><tr><th>尺度</th><th>所问的问题</th></tr></thead><tbody><tr><td>生命与形体</td><td>是否为外物伤生、累形？</td></tr><tr><td>志向</td><td>是否被困苦完全压倒？</td></tr><tr><td>实践</td><td>所学是否真正落实？</td></tr><tr><td>自得与知足</td><td>是否必须靠更多外物证明生活？</td></tr><tr><td>功与义</td><td>是否配得，来源与方式是否合宜？</td></tr><tr><td>操守</td><td>是否为利益或苟存进入不能认同的关系？</td></tr></tbody></table><p>这些尺度可能相互支持，却不能保证永远一致。</p><p>开篇反对为天下损伤生命，结尾人物却因拒绝政治关系而死亡。保全操守不等于肉身没有损失，肯定其节也不自动要求效仿其死。</p><p>阅读时应分别辨认：谁在说话、作了什么判断、叙述者如何评价，以及实际后果是什么。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><p>以下是由文本引出的现代参照，不是原文制定的固定程序。</p><h3 id="一、把所得、需要与取得方式分开" tabindex="-1">一、把所得、需要与取得方式分开 <a class="header-anchor" href="#一、把所得、需要与取得方式分开" aria-label="Permalink to &quot;一、把所得、需要与取得方式分开&quot;">​</a></h3><p>“这东西有用”“我眼下需要它”“我应当这样接受它”，可能一致，也可能不同。</p><p>面对机会、资源与身份，可以分别问：</p><table tabindex="0"><thead><tr><th>问题</th><th>需要辨认什么</th></tr></thead><tbody><tr><td>所需</td><td>它是否真正符合自己的需要？</td></tr><tr><td>代价</td><td>会怎样影响身体、心神与生活？</td></tr><tr><td>根据</td><td>给予与接受是否有合宜理由？</td></tr><tr><td>来源</td><td>所得来自怎样的行为？</td></tr><tr><td>关系</td><td>接受意味着承认、参与或承担什么？</td></tr><tr><td>意愿</td><td>是自己的选择，还是被迫满足他人安排？</td></tr><tr><td>状态</td><td>有切实把握，还是扮演理想形象？</td></tr><tr><td>退出</td><td>是否有明确、安全的拒绝方式？</td></tr></tbody></table><h3 id="二、不让外在条件包办全部评价" tabindex="-1">二、不让外在条件包办全部评价 <a class="header-anchor" href="#二、不让外在条件包办全部评价" aria-label="Permalink to &quot;二、不让外在条件包办全部评价&quot;">​</a></h3><p>财物多少、有没有官位、遭遇是否顺利，能说明部分处境，不能单独裁定全部实践与价值。</p><p>但重新评价困境，不等于取消困境。可以尊重精神独立，同时改善物质保障；不把求助视为羞耻，也不用高境界要求困苦者停止表达需要。</p><h3 id="三、知道与做到之间-容许真实的调整" tabindex="-1">三、知道与做到之间，容许真实的调整 <a class="header-anchor" href="#三、知道与做到之间-容许真实的调整" aria-label="Permalink to &quot;三、知道与做到之间，容许真实的调整&quot;">​</a></h3><p>公子牟承认“知而未能”，使未完成的努力在篇中有位置。</p><p>不宜用一句道理要求欲求立即消失，也不宜以强行压制维持已经自在的形象。调整可以包含实际方法、条件改善与必要边界，并非顺从所有欲望。</p><h3 id="四、坚持也不能免除自我检验" tabindex="-1">四、坚持也不能免除自我检验 <a class="header-anchor" href="#四、坚持也不能免除自我检验" aria-label="Permalink to &quot;四、坚持也不能免除自我检验&quot;">​</a></h3><p>陈蔡故事同时说内省与不失德。遭遇不顺，不必否定全部价值；已有坚持，也仍须检验理由、行为与方法。</p><p>在困境中寻找意义，不等于赞美或主动制造困境。守住原则与解除危险可以努力并行。</p><h3 id="五、不让奖励反过来改写事实" tabindex="-1">五、不让奖励反过来改写事实 <a class="header-anchor" href="#五、不让奖励反过来改写事实" aria-label="Permalink to &quot;五、不让奖励反过来改写事实&quot;">​</a></h3><p>参与、在场、随行、实际贡献与应得奖励，不能未经辨认就当作同一件事。</p><p>对自己有利的例外也值得检验。承认机会有吸引力，并不妨碍说明为何不愿或不宜接受。</p><h3 id="六、不以困苦与死亡设置道德门槛" tabindex="-1">六、不以困苦与死亡设置道德门槛 <a class="header-anchor" href="#六、不以困苦与死亡设置道德门槛" aria-label="Permalink to &quot;六、不以困苦与死亡设置道德门槛&quot;">​</a></h3><p>阅读守节与投水故事，可以理解价值冲突，但不应要求现实中的人复制极端结局。</p><p>坚定拒绝可以通过明确辞谢、退出不当关系、寻求保护与支持实现。操守不必以毁伤生命证明，贫困也不是德性的资格证。</p><h2 id="阅读辨析与疑难校正" tabindex="-1">阅读辨析与疑难校正 <a class="header-anchor" href="#阅读辨析与疑难校正" aria-label="Permalink to &quot;阅读辨析与疑难校正&quot;">​</a></h2><table tabindex="0"><thead><tr><th>容易混同的内容</th><th>需要保留的区别</th></tr></thead><tbody><tr><td>人物发言与全书定论</td><td>对舜、汤、周的批评首先是人物立场，须结合叙述评价</td></tr><tr><td>相同人物与固定境界</td><td>颜回、曾子等在不同故事中承担不同问题</td></tr><tr><td>故事与史实</td><td>制度、年代、地望若需核验，应另行处理</td></tr><tr><td>贯通解释与唯一训释</td><td>流畅解读不能掩盖疑难字句</td></tr><tr><td>结局与预先动机</td><td>离去后饿死，不等于原文写明预先求死</td></tr><tr><td>远避与自杀</td><td>入山、携家入海与明确自投、自沉不同</td></tr><tr><td>肯定操守与肯定死亡</td><td>“此二士之节也”不自动推出死亡必须效仿</td></tr><tr><td>尊生与只求存活</td><td>看重生命，不等于不问取得方式与所守之义</td></tr><tr><td>不受与取名策略</td><td>实际拒绝不能全解释成索取更高礼遇</td></tr></tbody></table><p>尤须保留疑义的字句包括：</p><ul><li>人物称名：“子州支父”“子州之父”“子州之伯”“瞀光”等；</li><li>缺字、字形：“大王囗父”“生䇲”“𫄳履”“𫗞粥”；</li><li>居处、衣履：“二室”“华冠”“曳纵”；</li><li>身心论说：“所以之与所以为”“神无恶乎”“无寿类”；</li><li>陈蔡结尾：“削然”“扢然”“道德于此”；</li><li>守节论说：“不若是而已”“乐与政为政，乐与治为治”“推乱以易暴”“苟可得已”“不赖高节戾行”。</li></ul><p>本文采用有助贯通语境的解释，但不将其强定为唯一答案。其他典籍中的“不食周粟”“叩马而谏”等情节，不补作本篇已经明写的内容。</p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><p>以下按阅读区域归组，详释见对应段落词条。</p><h3 id="第一至第四段·天下、土地与生命" tabindex="-1">第一至第四段·天下、土地与生命 <a class="header-anchor" href="#第一至第四段·天下、土地与生命" aria-label="Permalink to &quot;第一至第四段·天下、土地与生命&quot;">​</a></h3><ul><li><strong>辞让与承担</strong>：让、天下、至重、无以天下为、托天下、大器、易生。</li><li><strong>身体处境</strong>：幽忧之病、方且治之、未暇。</li><li><strong>日常自得</strong>：衣皮毛、葛絺、收敛、休食、心意自得。</li><li><strong>远避与经营</strong>：捲捲、葆力之士、夫负妻戴、入于海、反。</li><li><strong>供养与尊生</strong>：所用养、所养、尊生、以养伤身、以利累形。</li><li><strong>君位危险</strong>：患之、熏之以艾、援绥、舍我、为君之患。</li><li><strong>轻重比较</strong>：攫、废、愁身伤生、忧戚、知轻重。</li></ul><h3 id="第五至第八段·聘请、施予与辞受" tabindex="-1">第五至第八段·聘请、施予与辞受 <a class="header-anchor" href="#第五至第八段·聘请、施予与辞受" aria-label="Permalink to &quot;第五至第八段·聘请、施予与辞受&quot;">​</a></h3><ul><li><strong>聘礼关系</strong>：币、以币先焉、致币、听谬、遗使者罪、审之、恶富贵。</li><li><strong>本末与生命</strong>：道之真、治身、绪余、土苴、余事、完身、养生、殉物。</li><li><strong>行动检验</strong>：所以之、所以为、所用、所要、随侯之珠。</li><li><strong>赠粟与判断</strong>：遗之粟、再拜、自知我、罪我、作难。</li><li><strong>功罪与资格</strong>：爵禄、强之、伏其诛、当其赏、重赏大功。</li><li><strong>法约与声名</strong>：废法毁约、闻于天下、三旌之位、万锺之禄、妄施、肆。</li></ul><h3 id="第九至第十一段·贫居、实践与知足" tabindex="-1">第九至第十一段·贫居、实践与知足 <a class="header-anchor" href="#第九至第十一段·贫居、实践与知足" aria-label="Permalink to &quot;第九至第十一段·贫居、实践与知足&quot;">​</a></h3><ul><li><strong>居处衣履</strong>：环堵之室、瓮牖、二室、华冠、𫄳履、緼袍、曳纵。</li><li><strong>贫与病</strong>：病、学以为人、教以为己、希世、比周、慝。</li><li><strong>志与独立</strong>：不得臣、不得友、养志、养形、致道、忘心。</li><li><strong>供给与自得</strong>：𫗞粥、丝麻、鼓琴、自娱、自乐、审自得。</li><li><strong>行为修养</strong>：失之而不惧、行修于内、怍、诵之、是丘之得。</li></ul><h3 id="第十二至第十三段·真实欲求与穷通于道" tabindex="-1">第十二至第十三段·真实欲求与穷通于道 <a class="header-anchor" href="#第十二至第十三段·真实欲求与穷通于道" aria-label="Permalink to &quot;第十二至第十三段·真实欲求与穷通于道&quot;">​</a></h3><ul><li><strong>身心悬系</strong>：魏阙、重生、利轻、自胜、则从、强不从。</li><li><strong>再伤与未完成</strong>：神无恶乎、重伤、无寿类、有其意。</li><li><strong>外在困境</strong>：不火食、藜羹、不糁、削迹、藉夫子、隘。</li><li><strong>自省与所守</strong>：通于道、穷于道、内省。</li><li><strong>境遇与所乐</strong>：所乐非穷通、道德于此、颖阳、共伯、丘首。</li></ul><h3 id="第十四至第十六段·拒辱、所得来源与操守" tabindex="-1">第十四至第十六段·拒辱、所得来源与操守 <a class="header-anchor" href="#第十四至第十六段·拒辱、所得来源与操守" aria-label="Permalink to &quot;第十四至第十六段·拒辱、所得来源与操守&quot;">​</a></h3><ul><li><strong>拒绝卷入</strong>：畎亩、游尧之门、辱行、漫我、羞见之。</li><li><strong>征伐与受利</strong>：强力忍垢、贼、贪、知者、废上、犯其难、廉。</li><li><strong>严守辞受</strong>：非其义者、不践其土、尊我。</li><li><strong>生命结局</strong>：自投、自沈、清泠、椆水、庐水、首阳之山。</li><li><strong>观察与盟约</strong>：似有道者、试往观焉、与盟、加富二等、就官一列。</li><li><strong>治理与自利</strong>：忠信尽治、遭时、行货、阻兵、扬行、说众、要利。</li><li><strong>守节疑难</strong>：推乱以易暴、不为苟存、涂吾身、洁吾行、苟可得已、不赖高节戾行、节。</li></ul><h2 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段落</th><th>核心句</th><th>阅读重点</th></tr></thead><tbody><tr><td>第一段</td><td>夫天下至重也，而不以害其生</td><td>承认天下贵重，仍检验伤生代价</td></tr><tr><td>第一段</td><td>唯无以天下为者可以托天下也</td><td>不争求与可托付之间的反差</td></tr><tr><td>第一段</td><td>心意自得；子之不知余也</td><td>权位未必符合受让者所需</td></tr><tr><td>第二段</td><td>不以所用养害所养</td><td>供养条件不能反伤生命</td></tr><tr><td>第二段</td><td>虽贫贱不以利累形</td><td>未得之利也可能牵累身体</td></tr><tr><td>第三段</td><td>非恶为君也，恶为君之患也</td><td>区分职位与具体危险</td></tr><tr><td>第四段</td><td>所争者，其轻于韩又远</td><td>所求较小，仍可能造成伤生</td></tr><tr><td>第五段</td><td>真恶富贵也</td><td>拒绝落实为离去，而非口头辞让</td></tr><tr><td>第六段</td><td>道之真以治身</td><td>治身被置于根本地位</td></tr><tr><td>第六段</td><td>所用者重而所要者轻也</td><td>所付与所得的轻重倒置</td></tr><tr><td>第七段</td><td>以人之言而遗我粟……又且以人之言</td><td>检验赏罚依赖的判断方式</td></tr><tr><td>第八段</td><td>非臣之罪；非臣之功</td><td>不承虚加之罪，不认不属之功</td></tr><tr><td>第八段</td><td>吾知其贵；吾知其富</td><td>有价值不等于取得合宜</td></tr><tr><td>第九段</td><td>今宪贫也，非病也</td><td>物质缺乏不等于不能行所学</td></tr><tr><td>第十段</td><td>养志者忘形，养形者忘利，致道者忘心</td><td>三种忘各有侧重</td></tr><tr><td>第十一段</td><td>知足者，不以利自累也</td><td>所需有其尺度</td></tr><tr><td>第十一段</td><td>行修于内者，无位而不怍</td><td>官位不是修养的唯一证明</td></tr><tr><td>第十二段</td><td>虽知之，未能自胜也</td><td>知道不自动等于做到</td></tr><tr><td>第十二段</td><td>不能自胜而强不从者，此之谓重伤</td><td>避免强制再伤自身</td></tr><tr><td>第十三段</td><td>通于道之谓通，穷于道之谓穷</td><td>外在遭遇与于道失守不同</td></tr><tr><td>第十三段</td><td>内省而不穷于道，临难而不失其德</td><td>坚持与自我检验并行</td></tr><tr><td>第十三段</td><td>所乐非穷通也</td><td>快乐根源不在境遇本身</td></tr><tr><td>第十四段</td><td>又欲以其辱行漫我</td><td>授位可能被理解为污及自身</td></tr><tr><td>第十五段</td><td>废上非义，杀民非仁，享利非廉</td><td>检验行为与所得来源</td></tr><tr><td>第十五段</td><td>非其义者，不受其禄</td><td>辞受不能只看利益</td></tr><tr><td>第十六段</td><td>似有道者，试往观焉</td><td>认可须经观察</td></tr><tr><td>第十六段</td><td>忠信尽治而无求焉</td><td>尽责而不以治理谋私</td></tr><tr><td>第十六段</td><td>遭治世不避其任，遇乱世不为苟存</td><td>任事与退出都有条件</td></tr><tr><td>第十六段</td><td>独乐其志；此二士之节也</td><td>肯定操守，不自动要求效仿死亡</td></tr></tbody></table><h2 id="与前篇的呼应" tabindex="-1">与前篇的呼应 <a class="header-anchor" href="#与前篇的呼应" aria-label="Permalink to &quot;与前篇的呼应&quot;">​</a></h2><ul><li><strong>《逍遥游》</strong>：许由辞让天下的故事两见，本篇第一段只写「不受」，不再展开理由；两处并读，才见「天下于我也不重要」的分量。</li><li><strong>《养生主》</strong>：「可以保身，可以全生」是本篇「尊生」主线的先声；本篇把它从养生推到权位、土地与赏赐上。</li><li><strong>《人间世》</strong>：有用与被征用、处身与避害，可与第五段颜阖避聘、第七段列子辞粟对读。</li><li><strong>《德充符》</strong>：不以形貌、位势定人，与第九、第十段原宪、曾子的贫居相参。</li><li><strong>《山木》</strong>：贫与不材、处穷与自持，与本篇第九至第十一段同一关切。</li><li><strong>《秋水》</strong>：贵贱大小相对，与第四段「所求与所付的代价」的换算思路相通。</li><li><strong>《让王》与《盗跖》《渔父》《说剑》</strong> 同属杂篇末四篇，多以人物故事立说；读法上宜各篇分立，不强求一条主线贯通。</li></ul><p>参读不等于各句完全同义，也不据此确定写作先后与直接影响。</p><h2 id="十六段·一句话回顾" tabindex="-1">十六段·一句话回顾 <a class="header-anchor" href="#十六段·一句话回顾" aria-label="Permalink to &quot;十六段·一句话回顾&quot;">​</a></h2><ol><li><strong>辞让天下</strong>：权位再重，也不能拿生命去换。</li><li><strong>太王迁岐</strong>：供养生命的东西，不能反过来害被养的人。</li><li><strong>王子搜避位</strong>：患不在君位本身，在于是不是被君位困住。</li><li><strong>子华子辨轻重</strong>：先问所求是什么，再问要付出什么。</li><li><strong>颜阖避聘</strong>：别人认可的贵重，未必是自己所需。</li><li><strong>治身与殉物</strong>：所用不可重于所求，本末不能倒置。</li><li><strong>列子辞粟</strong>：给予也要看依据与关系风险，不是有给就收。</li><li><strong>屠羊说辞赏</strong>：功罪按事实分，破例之利同样要受检验。</li><li><strong>原宪贫而非病</strong>：贫是缺少，病是失守，两者不能混为一谈。</li><li><strong>曾子贫居</strong>：困苦写得具体，不屈也是真的。</li><li><strong>颜回不仕</strong>：知足、自得、行修，是三个不同的尺度。</li><li><strong>公子牟身隐心仕</strong>：知道而未能做到，是应当被承认的状态。</li><li><strong>孔子困于陈蔡</strong>：穷于道才算真穷，境遇不是全部尺度。</li><li><strong>北人无择</strong>：拒绝能保全独立，也可能付出生命。</li><li><strong>卞随、瞀光拒位</strong>：先问所得从哪来，再问自己配不配。</li><li><strong>伯夷叔齐</strong>：守节值得肯定，但不自动要求别人复制死亡。</li></ol><h2 id="一句话读懂《让王》" tabindex="-1">一句话读懂《让王》 <a class="header-anchor" href="#一句话读懂《让王》" aria-label="Permalink to &quot;一句话读懂《让王》&quot;">​</a></h2><blockquote><p><strong>「夫天下至重也，而不以害其生，又况他物乎！」</strong></p></blockquote><p>《让王》不是教人轻视天下，而是把次序摆正：天下极重，仍重不过一条命；其他外物又轻于此。由此往下，才谈得上为什么给、该不该受、缺了外物算不算失败、知道之后有没有做到。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><h3 id="本文直接依据" tabindex="-1">本文直接依据 <a class="header-anchor" href="#本文直接依据" aria-label="Permalink to &quot;本文直接依据&quot;">​</a></h3><ul><li>用户提供的《庄子·让王》原文、字词注解、逐段解读及全篇总论。</li><li>原文依所供文本录入，保留缺字、异形字、称名与所附音注；疑难处在词条和解读中说明，不默改。</li></ul><h3 id="文内对读篇章" tabindex="-1">文内对读篇章 <a class="header-anchor" href="#文内对读篇章" aria-label="Permalink to &quot;文内对读篇章&quot;">​</a></h3><ul><li>《庄子·逍遥游》：许由辞让、誉非与内在尺度等相关论述。</li><li>《庄子·寓言》：言说接受、重言分量、人物理解变化等相关论述。</li><li>《庄子·山木》：孔子困于陈蔡等相关叙述。</li><li>《庄子·外物》：外物、伤生、辞让与毁身等相关故事。</li><li>《庄子·盗跖》：伯夷叔齐等人物行迹的不同评价，可供比较。</li><li>《诗经·商颂》：曾子故事所提及的诗篇类别，原文未指明具体篇目。</li></ul><p>以上为文内比较阅读的参照，不表示本次已对各篇逐一作版本校勘。本文未列入未实际核验的页码、历史年表、制度细节或地望定论。</p><h2 id="全篇最后一问" tabindex="-1">全篇最后一问 <a class="header-anchor" href="#全篇最后一问" aria-label="Permalink to &quot;全篇最后一问&quot;">​</a></h2><p>第一段先立一个尺度：</p><p><strong>天下至重，而不以害其生。</strong></p><p>末段落到一个结局：</p><p><strong>登彼西山，行其节。</strong></p><p>从「不以害生」到「守节而死」，中间十六个故事没有给出统一答案。于是最后可以这样问自己：</p><p><strong>我所追求的那件贵重之物，究竟在养谁？</strong></p><p><strong>我得到的与给出的，依据分别在哪里？</strong></p><p><strong>缺少外物，就意味着我失败了吗？</strong></p><p><strong>我已经知道的，我做到了吗？</strong></p><p><strong>我拒绝的时候，代价由谁承担？</strong></p><h2 id="全篇收束·贵重之物-先看它在养谁" tabindex="-1">全篇收束·贵重之物，先看它在养谁 <a class="header-anchor" href="#全篇收束·贵重之物-先看它在养谁" aria-label="Permalink to &quot;全篇收束·贵重之物，先看它在养谁&quot;">​</a></h2><p>《让王》不只是劝人不要贪求富贵，还反复追问：</p><p><strong>为什么接受，为什么拒绝，所付代价是否合宜，又将因此进入什么关系？</strong></p><p>天下、爵禄与声名不能不经检验便占据最高位置。与此同时，尊生、实践、义与操守也并非在所有处境中毫无冲突。</p><p>因而，不必把全篇压成同一句答案。更重要的是辨明不同辞受的理由，看见真实的生命代价，并承认理想、能力与处境之间仍需持续判断。</p>',148))])}}});export{xa as __pageData,qa as default};
